/* Java 源码解读课程正文注册表（由 frag-src 碎片自动生成）。
   合并扩展已有 QZ_CONTENT（中级/初级/高级），不覆盖；key = track|stack|lessonName。 */
window.QZ_CONTENT = (function (prev) {
  'use strict';
  var data = {
    "backend|java|mall 全景：一个商城为什么拆七个模块": { "body": "<p class=\"lead\">源码解读第一课：拿一个 8 万 star 的真实商城 mall 开刀。搞懂七个 Maven 模块各管什么、一次请求怎么穿过 Controller/Service/Mapper、品牌改名为什么要连带更新商品，再亲手推一遍依赖传递。读完你让 AI 改代码时，能问出「改这里会影响谁」。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">认人</span><span class=\"s\">顾客与运营</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">认岗</span><span class=\"s\">七个模块</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">走流程</span><span class=\"s\">一次品牌查询</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>只想开个店，先收到一份组织架构通知</h2>\n  <p>你让 AI 帮你做个商城，想法很朴素：能展示商品、能下单、再有个后台改价格。结果打开项目，迎面就是 <code>mall-admin</code>、<code>mall-portal</code>、<code>mall-mbg</code>、<code>mall-security</code>……明明只想开个店，怎么先收到一份组织架构调整通知？</p>\n  <p>别急，这些名字不是凑出来显专业的。把 mall 当成一家正在营业的商场，你会发现所谓架构，就是事情多了以后，<b>安排谁负责什么、谁找谁办事</b>。第一课不背语法，先认人：来买东西的顾客，和负责经营的工作人员。</p>\n  <p>你去商场只会看到货架、价格牌和收银台，不会逛着逛着进了办公室，把原价 999 的商品改成 9.9。软件也一样，mall 给两种人各留了一个入口：</p>\n  <table>\n    <tr><th>项目</th><th>给谁用</th><th>相当于商场里的</th></tr>\n    <tr><td><code>mall-admin-web</code> → <code>mall-admin</code></td><td>管理员、运营</td><td>工作人员操作台 → 运营办公室</td></tr>\n    <tr><td><code>mall-app-web</code> → <code>mall-portal</code></td><td>购物用户</td><td>顾客看到的店面 → 营业窗口</td></tr>\n  </table>\n  <p>注意一个容易混的词：<b>后台管理界面也是前端</b>。「后台」说的是给工作人员用，「后端」说的是程序处理业务，两个词长得像，分类标准却不同。后厨的点餐屏依然是块屏幕，不能因为摆在后厨就要求它自己炒菜。</p>\n  <div class=\"key\"><span class=\"tag\">一句话记住</span>分了入口不等于自动安全。员工通道挂块牌子，顾客照样可能走进去；后端必须认真验身份查权限，不能只靠界面藏一个按钮。</div>\n  <div class=\"recap\"><b>收束：</b>顾客走 portal，运营走 admin；界面都算前端，处理业务的才是后端。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>七个模块，按职责认人就不吓人</h2>\n  <p>模块就是<b>有明确职责的一组代码</b>，像商场把收银、仓储、安保分开。mall 用 Maven 管理这些区域，根目录 <code>pom.xml</code> 里写着真实的模块名单。不用背顺序，按岗位认：</p>\n  <figure>\n    <svg viewBox=\"0 0 760 250\" role=\"img\" aria-label=\"mall 七模块分工图\">\n      <defs><marker id=\"ars1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <text x=\"8\" y=\"20\" font-size=\"12\" fill=\"#7C7166\">业务应用（各有启动入口，可独立部署）</text>\n      <rect x=\"8\" y=\"32\" width=\"168\" height=\"62\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"92\" y=\"57\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">mall-admin</text><text x=\"92\" y=\"77\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">运营办公室·后台管理</text>\n      <rect x=\"196\" y=\"32\" width=\"168\" height=\"62\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"280\" y=\"57\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">mall-portal</text><text x=\"280\" y=\"77\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">营业窗口·前台购物</text>\n      <rect x=\"384\" y=\"32\" width=\"168\" height=\"62\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"468\" y=\"57\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">mall-search</text><text x=\"468\" y=\"77\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">查询台·ES 商品搜索</text>\n      <rect x=\"572\" y=\"32\" width=\"180\" height=\"62\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"662\" y=\"57\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#5B4A2F\">mall-demo</text><text x=\"662\" y=\"77\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">培训样板间·非营业必需</text>\n      <text x=\"8\" y=\"132\" font-size=\"12\" fill=\"#7C7166\">公共库（被依赖的零件，不单独启动）</text>\n      <rect x=\"8\" y=\"144\" width=\"230\" height=\"62\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"123\" y=\"169\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">mall-mbg</text><text x=\"123\" y=\"189\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">资料卡+取数工具·生成的模型/Mapper</text>\n      <rect x=\"262\" y=\"144\" width=\"230\" height=\"62\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"377\" y=\"169\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">mall-security</text><text x=\"377\" y=\"189\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">可复用门禁·身份验证组件</text>\n      <rect x=\"516\" y=\"144\" width=\"236\" height=\"62\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"634\" y=\"169\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">mall-common</text><text x=\"634\" y=\"189\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">统一办公用品·CommonResult/工具</text>\n      <line x1=\"92\" y1=\"94\" x2=\"110\" y2=\"142\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1)\"/>\n      <line x1=\"130\" y1=\"94\" x2=\"330\" y2=\"142\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1)\"/>\n      <line x1=\"280\" y1=\"94\" x2=\"160\" y2=\"142\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1)\"/>\n      <line x1=\"310\" y1=\"94\" x2=\"370\" y2=\"142\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1)\"/>\n      <line x1=\"468\" y1=\"94\" x2=\"220\" y2=\"142\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1)\"/>\n      <line x1=\"238\" y1=\"175\" x2=\"514\" y2=\"175\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1)\"/>\n      <line x1=\"492\" y1=\"190\" x2=\"514\" y2=\"190\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1)\"/>\n      <text x=\"380\" y=\"236\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">箭头是代码依赖，不是网络请求。七个模块 ≠ 七台服务器。</text>\n    </svg>\n    <figcaption>图 1 · 三个业务岗位 + 三套共享工具 + 一个样板间，依据根 pom.xml 与各模块 pom.xml。</figcaption>\n  </figure>\n  <p>为什么搜索值得单独一个模块？顾客问「有没有适合出门旅行的背包」，管理员问「编号 123 的库存是多少」，都叫查询，要求完全不同：前者要关键词匹配、筛选、排序。分开后搜索代码和 Elasticsearch 依赖有了自己的归属，也具备单独部署的条件。但多建一个目录，服务器不会自动变快。</p>\n  <p><code>mall-mbg</code> 名字像部门缩写，其实是 MyBatis Generator 按数据库结构生成的一套资料卡（数据模型）和取数工具（Mapper）。它不是数据库本身，也不包办所有复杂的数据访问。</p>\n  <div class=\"note\"><span class=\"tag\">三个概念别画等号</span>模块是在分代码，服务进程是在分运行中的程序，服务器是承载程序的机器。运行 mall-admin 时不需要另外启动一个叫 mall-common 的服务器再打电话借表单——公共库是收银机里装好的零件，不是旁边另开的店。</div>\n  <div class=\"recap\"><b>收束：</b>admin/portal/search/demo 是可启动的应用，common/security/mbg 是被依赖的库；分代码和分进程是两回事。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>跟着一次「查看品牌」进去转一圈</h2>\n  <p>只看模块表像只看楼层导览，知道餐厅在三楼，不知道饭怎么端上桌。找个最小功能：<b>获取全部品牌列表</b>。在 <code>mall-admin</code> 的 <code>PmsBrandController</code> 里，类上定义 <code>/brand</code>，方法上定义 <code>/listAll</code>，组合成 <code>GET /brand/listAll</code>。方法核心只有一行：</p>\n  <pre>return CommonResult.success(brandService.listAllBrand());</pre>\n  <p>翻译成人话：请品牌业务服务把所有品牌找出来，再装进统一的成功响应。这一行已经把三个岗位串起来了。</p>\n  <figure>\n    <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"一次品牌查询的模块与分层流转\">\n      <defs><marker id=\"ars1c\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"34\" width=\"164\" height=\"66\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"90\" y=\"59\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">Controller 接待窗口</text><text x=\"90\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">mall-admin·PmsBrandController</text>\n      <rect x=\"204\" y=\"34\" width=\"164\" height=\"66\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"286\" y=\"59\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">Service 业务经办</text><text x=\"286\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">mall-admin·PmsBrandServiceImpl</text>\n      <rect x=\"400\" y=\"34\" width=\"164\" height=\"66\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"482\" y=\"59\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">Mapper 取数</text><text x=\"482\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">mall-mbg·PmsBrandMapper</text>\n      <rect x=\"596\" y=\"34\" width=\"156\" height=\"66\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"674\" y=\"59\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">CommonResult 回执</text><text x=\"674\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">mall-common·code/message/data</text>\n      <line x1=\"172\" y1=\"67\" x2=\"202\" y2=\"67\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1c)\"/>\n      <line x1=\"368\" y1=\"67\" x2=\"398\" y2=\"67\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1c)\"/>\n      <line x1=\"564\" y1=\"67\" x2=\"594\" y2=\"67\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars1c)\"/>\n      <text x=\"380\" y=\"136\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">Controller/Service/Mapper 是处理流程的分层；admin/mbg/common 是代码的模块划分</text>\n      <text x=\"380\" y=\"158\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">一次查询跨了三个模块，但都在同一个应用进程里协作（省略了安全过滤等环节）</text>\n    </svg>\n    <figcaption>图 2 · 分层管流程，模块管归属；一层不必单独拆一个模块，一个模块也可以包含多层。</figcaption>\n  </figure>\n  <p>Service 的实现就一句 <code>brandMapper.selectByExample(new PmsBrandExample())</code>，看起来像个传话员。接待窗口为什么要把活转交出去？接待员如果既接电话又盘库存、记账、修打印机，办公室不是不能转，只是每次打印机卡纸，全公司都得跟着等。职责集中过头，改一条业务规则就会搅动请求处理的细节。</p>\n  <p><code>CommonResult</code> 三个核心字段 <code>code / message / data</code>，是一张标准回执：业务状态、提示信息、具体结果。注意业务状态码和 HTTP 状态码是两回事。统一包装的价值在于让调用方按相同格式读结果，省去「您这次的表达习惯是什么」的反复猜测。</p>\n  <div class=\"recap\"><b>收束：</b>Controller 接待、Service 经办、Mapper 取数、CommonResult 开回执；分层是流程，模块是归属。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>品牌改名，为什么不能只改品牌表</h2>\n  <p>现在换个需求：把一个品牌的名字改掉。直觉上找到记录换掉名字就完了？看 <code>PmsBrandServiceImpl.updateBrand()</code> 的真实源码：</p>\n  <pre>PmsProduct product = new PmsProduct();\nproduct.setBrandName(pmsBrand.getName());\nPmsProductExample example = new PmsProductExample();\nexample.createCriteria().andBrandIdEqualTo(id);\nproductMapper.updateByExampleSelective(product, example);\nreturn brandMapper.updateByPrimaryKeySelective(pmsBrand);</pre>\n  <p>它先把这个品牌相关商品里保存的品牌名称一起更新，再更新品牌记录。因为 mall 的商品数据里<b>也存了一份品牌名</b>。专柜换了招牌，价签上印的旧名字也得处理，不能门头叫新名字，货架还在怀念过去。</p>\n  <p>这是一个真实的工程取舍：多存一份名称，部分读取场景更方便；名称变了，就要承担同步维护的工作。省了多少查询成本要靠实际测量，不能靠想象下结论。这也回答了「Service 是不是凑工位的」——Mapper 擅长改这张表，Service 负责「业务上改一个品牌，还要连带处理哪些事」。</p>\n  <div class=\"key\"><span class=\"tag\">让 AI 改这里时，问这三个问题</span>商品里是不是也存了品牌名？改名后那些数据怎么保持一致？<b>两条更新只成功了一条会怎样？</b>最后一问涉及事务——看见两条更新语句，不代表已经证明它们能一起成功或一起撤销，还要核查事务配置和失败场景。</div>\n  <div class=\"recap\"><b>收束：</b>源码里真正重要的不是语法，是数据之间的业务关系；读源码不是作者写了就认定最佳，要看懂它解决了什么、还欠什么确认。</div>\n</section>\n\n<section id=\"e\">\n  <h2><span class=\"no\">第 5 步</span>代码分开了，为什么还能互相使用</h2>\n  <p>mall-admin 用了 mall-mbg 的 Mapper、mall-common 的回执，它们在互相发网络请求吗？不是，这是同一个应用内部的代码协作。把零件带上的是 Maven：<code>mall-admin/pom.xml</code> 声明依赖 <code>mall-mbg</code> 和 <code>mall-security</code>，像一份装配清单。</p>\n  <ul>\n    <li><b>依赖会传递</b>：admin 没直接列 mall-common 却能用它，因为 mbg 和 security 都依赖 common，顺着链条带进来了。像订了打印机，配套电源也得一起送到。</li>\n    <li><b>父 pom 统一采购规格</b>：根 pom <code>&lt;packaging&gt;pom&lt;/packaging&gt;</code> 只做组织和配置管理。<code>&lt;dependencyManagement&gt;</code> 管版本，子模块引依赖可以不写版本号。但标准目录里写了零件，不代表每个部门都领了一份——列在管理区不等于自动引入。</li>\n    <li><b>Spring 负责接好零件</b>：<code>@Autowired</code> 说「这里需要一个符合要求的对象」。启动类 <code>MallAdminApplication</code> 的组件扫描从自己包往下找，只能用当前应用实际引入的组件。根 pom 列了七个模块，不代表七个全装进后台。</li>\n  </ul>\n  <p>最有趣的是搜索模块会「退赠品」：<code>mall-search/pom.xml</code> 依赖 mall-mbg，却特意写了 <code>&lt;exclusions&gt;</code> 把顺链条带来的 <code>spring-boot-starter-data-redis</code> 退掉。像买站立办公桌退掉赠品椅子——桌子留下，椅子不搬进来。不同岗位需要不同工具，没必要为了整齐让每人背同一个工具箱。当然，排除项只控制这条依赖路径，不证明整个项目不可能从别的路径引入 Redis。</p>\n  <div class=\"note\"><span class=\"tag\">两个常见误会</span>① 单体项目就不能分工？可以分工，单模块也能靠包和接口分清职责；多模块讨论代码组织，微服务讨论运行部署。② 模块拆开修改就不影响别人？改 mall-common 的回执格式，admin 和 portal 都受影响，还要重新构建部署。<b>复用减少重复劳动，也扩大公共变更的影响面。</b>几个接口的小工具不必照拆七份——不要店还没开起来，先给七个部门刻公章。</div>\n  <div class=\"recap\"><b>收束：</b>Maven 带零件、父 pom 定规格、Spring 接对象；依赖会传递也能排除，公共库改动要清点所有使用方。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：改动落点、依赖传递</h2>\n  <p>演练一换三个真实改动场景，看该改哪个模块、波及哪些应用。演练二亲手搭依赖清单，看传递依赖怎么把零件带进来、排除项怎么退赠品、改 common 时谁要跟着重新构建。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 这个改动该落在哪</b><span class=\"hint\">点按钮切换场景</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"brand\" class=\"on\">品牌改名规则</button><button data-k=\"result\">统一回执格式</button><button data-k=\"search\">搜索加个依赖</button></div></div>\n    <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>影响面分析</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">先想清楚落点和影响面，再让 AI 动手</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 依赖传递沙盒</b><span class=\"hint\">勾选依赖与排除项，看 admin 实际拿到什么</span></div>\n    <div class=\"controls\">\n      <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1mbg\" checked> admin→mbg</label></div>\n      <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1sec\" checked> admin→security</label></div>\n      <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1ex\"> mbg 排除 redis starter</label></div>\n      <div class=\"ctl\"><label>使用 common 的应用数</label><input type=\"range\" id=\"g1apps\" min=\"1\" max=\"4\" value=\"3\"><span class=\"val\" id=\"g1appsV\">3</span></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>装配过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">模型：mbg→common+redis starter；security→common；应用= admin/portal/search/demo</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>模块边界决定「改哪里」，依赖关系决定「影响谁」。让 AI 改共享模块前，先数一遍使用方。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>六个问题</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。七个目录在你眼里已经是一家商场的岗位表了。下一课看门禁：JWT 怎么确认「你是你」。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>速查表</h2>\n  <table>\n    <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n    <tr><td>mall-admin / mall-portal</td><td>运营办公室 / 营业窗口</td><td>两种人两个入口，分入口≠自动安全</td></tr>\n    <tr><td>mall-common / security / mbg</td><td>办公用品 / 门禁 / 资料卡</td><td>公共库被依赖，不单独启动</td></tr>\n    <tr><td>Controller→Service→Mapper</td><td>接待→经办→取数</td><td>分层是流程，模块是归属</td></tr>\n    <tr><td>CommonResult</td><td>标准回执单</td><td>code/message/data；业务码≠HTTP码</td></tr>\n    <tr><td>品牌改名同步商品</td><td>换招牌也要换价签</td><td>冗余存储换读取方便，代价是同步维护</td></tr>\n    <tr><td>依赖传递 / exclusions</td><td>订打印机送电源 / 退赠品椅子</td><td>传递受排除影响；只管这条路径</td></tr>\n    <tr><td>dependencyManagement</td><td>统一采购规格</td><td>管版本不等于自动引入</td></tr>\n    <tr><td>多模块 vs 微服务</td><td>分代码 vs 分进程</td><td>单体也能多模块；小工具别急着拆</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>本页依据课程仓库 <code>code/source-reading/java/mall/mall/</code> 当前源码重写；比喻帮助理解，结论以源码为准。演练为依赖模型模拟，非真实 Maven 解析。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第一篇-mall整体架构与多模块设计 <span class=\"src\">— 本课重写底稿</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/</code> <span class=\"src\">— 已在本地，含全部七模块；路径见下方路标</span></li>\n      <li>配套编排 <code>code/source-reading/java/mall/mall-docker/docker-compose.yml</code> <span class=\"src\">— MySQL 初始化分 schema/data_config/data_test 三份脚本，首次初始化时执行</span></li>\n    </ul>\n    <h3>源码路标（相对 mall 工程根）</h3>\n    <ul>\n      <li><code>pom.xml</code>、<code>mall-admin/pom.xml</code>、<code>mall-search/pom.xml</code> <span class=\"src\">— 模块名单、依赖声明、Redis starter 排除项</span></li>\n      <li><code>mall-admin/.../controller/PmsBrandController.java</code>、<code>service/impl/PmsBrandServiceImpl.java</code> <span class=\"src\">— 品牌查询与改名的连带更新</span></li>\n      <li><code>mall-common/.../api/CommonResult.java</code> <span class=\"src\">— 统一回执三字段</span></li>\n      <li><code>mall-admin/.../config/MallSecurityConfig.java</code> 与 <code>mall-portal/.../config/MallSecurityConfig.java</code> <span class=\"src\">— 同一门禁组件，各自提供用户加载</span></li>\n    </ul>\n    <h3>官方文档</h3>\n    <ul>\n      <li><a href=\"https://github.com/macrozheng/mall\" target=\"_blank\" rel=\"noopener\">macrozheng/mall · GitHub</a> <span class=\"src\">— 上游项目与文档</span></li>\n      <li><a href=\"https://maven.apache.org/guides/introduction/introduction-to-dependency-mechanism.html\" target=\"_blank\" rel=\"noopener\">Maven · Introduction to the Dependency Mechanism</a> <span class=\"src\">— 传递依赖、exclusions、dependencyManagement</span></li>\n      <li><a href=\"https://docs.spring.io/spring-boot/index.html\" target=\"_blank\" rel=\"noopener\">Spring Boot Reference</a> <span class=\"src\">— 组件扫描与自动装配边界</span></li>\n    </ul>\n    <h3>下一课要用</h3>\n    <ul>\n      <li><a href=\"https://jwt.io/introduction\" target=\"_blank\" rel=\"noopener\">JWT · Introduction to JSON Web Tokens</a> <span class=\"src\">— S2 登录凭证的三段结构</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"两种人两个入口"},{"id":"b","title":"七个模块认岗"},{"id":"c","title":"一次品牌查询"},{"id":"d","title":"改名连带更新"},{"id":"e","title":"依赖怎么工作"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    brand:{code:\"场景：品牌改名要连带更新商品里的品牌名\\n落点：mall-admin\\n  PmsBrandServiceImpl.updateBrand()\\n取数：mall-mbg 的 productMapper/brandMapper\\n追问：两条更新只成功一条怎么办？(事务)\",log:[[\"ok\",\"落点明确：业务规则属于 admin 的 Service 层\"],[\"c\",\"// Mapper 只改表，连带规则归 Service\"],[\"warn\",\"影响面：本应用；但要核查事务保障\"],[\"c\",\"// 别把连带更新写进 Controller\"]]},\n    result:{code:\"场景：统一回执 CommonResult 加一个字段\\n落点：mall-common\\n  common/api/CommonResult.java\\n使用方：admin、portal、search、demo\\n追问：哪些应用要重新构建、验证、部署？\",log:[[\"warn\",\"公共库改动：所有依赖方都受影响\"],[\"api\",\"mbg→common、security→common 传递到各应用\"],[\"err\",\"已部署的应用不会凭空更新，需重新构建部署\"],[\"c\",\"// 复用省重复劳动，也放大变更影响面\"]]},\n    search:{code:\"场景：搜索模块要加一个自己的依赖\\n落点：mall-search/pom.xml\\n参照：它已引入 ES 依赖、排除 redis starter\\n追问：会不会顺依赖链带进不需要的零件？\",log:[[\"ok\",\"岗位专属工具放自己模块，不塞公共库\"],[\"c\",\"// search 已示范 exclusions 退赠品\"],[\"warn\",\"检查传递依赖，别让别人背上你的工具箱\"],[\"c\",\"// 依赖隔离正是拆模块的理由之一\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById(\"e1code\").textContent=c.code;\n    document.getElementById(\"e1log\").innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"brand\");\n})();\n\n(function(){\n  function calc(){\n    var mbg=document.getElementById('g1mbg').checked;\n    var sec=document.getElementById('g1sec').checked;\n    var ex=document.getElementById('g1ex').checked;\n    var apps=parseInt(document.getElementById('g1apps').value,10);\n    document.getElementById('g1appsV').textContent=apps;\n    var parts=[];\n    if(mbg)parts.push('mall-mbg');\n    if(sec)parts.push('mall-security');\n    var common=(mbg||sec);\n    if(common)parts.push('mall-common(传递)');\n    var redis=mbg&&!ex;\n    if(redis)parts.push('redis starter(传递)');\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+parts.length+'</b><small>admin 拿到的内部零件</small></div>'+\n      '<div class=\"stat-box '+(redis?'bad':'good')+'\"><b>'+(redis?'带入':'未带')+'</b><small>redis starter</small></div>'+\n      '<div class=\"stat-box '+(apps>1?'bad':'good')+'\"><b>'+apps+'</b><small>改 common 波及应用</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(common?'on':'bad')+'\">'+(common?'common 顺链条进来':'common 进不来')+'</span>'+\n      (mbg&&ex?'<span class=\"chip on\">exclusions 生效：退掉赠品</span>':'')+\n      (!mbg&&!sec?'<span class=\"chip bad\">清单为空：Mapper/门禁都没了</span>':'')+\n      '<span class=\"chip '+(apps>1?'bad':'on')+'\">common 变更影响 '+apps+' 个应用</span>';\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(!common?'断链':'传递')+'</span>'+\n      (!common?'admin 不依赖 mbg 也不依赖 security 时，common 不会凭空出现——依赖Management 只管版本，列了不等于引入。':(redis?'mbg 把 redis starter 顺链条带给了 admin。search 的做法是写 exclusions 退掉这条路径上的赠品。':'exclusions 只掐断这条路径；若别处再引 redis，仍会进来。排除项不是全项目封杀。'));\n    var log=[];\n    log.push('<div><span class=\"api\">装配清单：'+(mbg?'mbg ':'')+(sec?'security ':'')+(!mbg&&!sec?'(空)':'')+'</span></div>');\n    if(mbg)log.push('<div><span class=\"ok\">mbg → common（传递引入）</span></div>');\n    if(sec)log.push('<div><span class=\"ok\">security → common（传递引入）</span></div>');\n    if(mbg)log.push(redis?'<div><span class=\"warn\">mbg → redis starter 顺链带入 ⚠</span></div>':'<div><span class=\"ok\">exclusions：redis starter 已退</span></div>');\n    log.push('<div><span class=\"c\">// 改 common 回执格式 → '+apps+' 个应用需重新构建验证部署</span></div>');\n    document.getElementById('g1log').innerHTML=log.join('');\n  }\n  ['g1mbg','g1sec','g1ex'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  document.getElementById('g1apps').addEventListener('input',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. mall-admin-web 后台管理界面属于？\",\"opts\":[[\"前端，「后台」指给工作人员用\",true,\"对。后台/后端分类标准不同。\"],[\"后端，因为名字带后台\",false,\"处理业务的才是后端。\"],[\"数据库层\",false,\"它是界面。\"]]},{\"q\":\"2. 运行 mall-admin 时，mall-common 需要单独启动吗？\",\"opts\":[[\"不需要，它是被依赖的公共库\",true,\"对。零件不是另开的店。\"],[\"需要，七个模块七台服务器\",false,\"模块≠进程≠服务器。\"],[\"需要，模块间靠网络请求\",false,\"同一应用内代码协作。\"]]},{\"q\":\"3. Controller、Service、Mapper 与 admin、mbg、common 的关系？\",\"opts\":[[\"前者是流程分层，后者是模块划分\",true,\"对。一个模块可含多层。\"],[\"一一对应，一层一个模块\",false,\"不必对应。\"],[\"都是 Maven 模块\",false,\"分层不是模块。\"]]},{\"q\":\"4. mall 品牌改名为什么先更新商品表？\",\"opts\":[[\"商品里冗余存了品牌名，要同步\",true,\"对。换招牌也要换价签。\"],[\"商品表是主表\",false,\"品牌记录才是本体。\"],[\"为了加事务\",false,\"同步是业务关系，事务另核查。\"]]},{\"q\":\"5. mall-search 对 mbg 写 exclusions 排除 redis starter，说明？\",\"opts\":[[\"依赖会传递，可按路径退掉不需要的\",true,\"对。但只管这条路径。\"],[\"全项目从此没有 Redis\",false,\"别的路径仍可能引入。\"],[\"dependencyManagement 自动引入所有库\",false,\"管版本不等于引入。\"]]},{\"q\":\"6. 改 mall-common 的 CommonResult 格式，正确预期是？\",\"opts\":[[\"所有使用方都要检查并重新构建部署\",true,\"对。复用放大变更影响面。\"],[\"只影响 common 自己\",false,\"传递依赖波及全部使用方。\"],[\"已部署应用自动更新\",false,\"不会凭空更新。\"]]}];" },
    "backend|java|登录认证：JWT 怎么确认你是你": { "body": "<p class=\"lead\">源码解读第二课：账号密码交上去之后，mall 怎么确认「你是你」。从 Session 的多服务器麻烦讲到 JWT 三段式通行证，拆开登录发证的五步和每次请求的安检闸机，再看本仓库的双 token + 版本号单点登录改造。BCrypt 为什么故意慢，这场演练算给你看。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">问题</span><span class=\"s\">服务器怎么认人</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">通行证</span><span class=\"s\">JWT 三段式</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">发证</span><span class=\"s\">登录五步</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">安检</span><span class=\"s\">过滤器+权限</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">动手</span><span class=\"s\">演练与自测</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>一楼登录了，二楼凭什么让我再登一次</h2>\n  <p>商城后台上线后加了第二台服务器。运营小张登录成功，刷新一下页面，又跳回登录页；再刷新，又进去了。像在一楼办了会员卡，上二楼却被要求重新办一张——因为两次请求被负载均衡分到了不同服务器。</p>\n  <p>传统做法是 <span class=\"term\">Session</span>：登录成功后服务器自己记一条「这人登录了」，把 SessionId 种进浏览器 Cookie，每次请求凭 Id 找回记录。这叫<b>有状态</b>。单台服务器没问题；多台就麻烦了——Session 存在 A 上，请求落到 B，B 翻遍口袋没这条记录，只能当你没登录。要么做 Session 共享，要么做粘性会话，都不省心。</p>\n  <p><span class=\"term\">JWT</span> 换了个思路：服务器不记了，给客户端发一张<b>通行证</b>，每次请求带上，哪台服务器都能当场验。这叫<b>无状态</b>。</p>\n  <table>\n    <tr><th></th><th>Session（有状态）</th><th>JWT（无状态）</th></tr>\n    <tr><td>服务器存登录状态吗</td><td>存</td><td>不存</td></tr>\n    <tr><td>每次请求带什么</td><td>Cookie 里的 SessionId</td><td>请求头里的 token</td></tr>\n    <tr><td>验身份靠什么</td><td>查自己存的记录</td><td>验 token 签名</td></tr>\n    <tr><td>多台服务器扩展</td><td>要共享 Session，麻烦</td><td>谁都能验，加机器就行</td></tr>\n  </table>\n  <div class=\"recap\"><b>收束：</b>Session 是服务器记账认人，JWT 是客户端带证、服务器验证；无状态天然好扩展。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>通行证长什么样：三段式，防篡改不防偷看</h2>\n  <p>JWT 是一串字符串，两个点分成三段：<code>header.payload.signature</code>。header 声明用什么算法（HS256/HS512），payload 装用户名、签发时间、过期时间，signature 是拿前两段加一把<b>只有服务器知道的密钥</b>算出来的封印。</p>\n  <figure>\n    <svg viewBox=\"0 0 760 210\" role=\"img\" aria-label=\"JWT 三段结构与验签\">\n      <defs><marker id=\"ars2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"30\" width=\"200\" height=\"64\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"108\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">header 头</text><text x=\"108\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">声明算法 HS512</text>\n      <text x=\"216\" y=\"66\" font-size=\"16\" fill=\"#A39B8E\">.</text>\n      <rect x=\"230\" y=\"30\" width=\"220\" height=\"64\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"340\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">payload 身体</text><text x=\"340\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">用户名·签发时间·过期时间</text>\n      <text x=\"458\" y=\"66\" font-size=\"16\" fill=\"#A39B8E\">.</text>\n      <rect x=\"472\" y=\"30\" width=\"280\" height=\"64\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"612\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">signature 签名</text><text x=\"612\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">前两段 + 服务器密钥算出的封印</text>\n      <line x1=\"108\" y1=\"94\" x2=\"500\" y2=\"134\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars2)\"/>\n      <line x1=\"340\" y1=\"94\" x2=\"560\" y2=\"134\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars2)\"/>\n      <rect x=\"440\" y=\"136\" width=\"312\" height=\"52\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/>\n      <text x=\"596\" y=\"158\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8A5510\">验签：重算签名，对得上=没被改过</text>\n      <text x=\"596\" y=\"176\" text-anchor=\"middle\" font-size=\"11\" fill=\"#B04A35\">改了任何一个字 → 签名破 → 拒绝</text>\n      <text x=\"120\" y=\"150\" font-size=\"12\" fill=\"#B04A35\">⚠ payload 是 base64，谁都能解开看</text>\n      <text x=\"120\" y=\"170\" font-size=\"12\" fill=\"#7C7166\">防的是篡改，不是偷看</text>\n    </svg>\n    <figcaption>图 1 · 签名密钥只在服务器手里；黑客把用户名改成 admin，签名立刻对不上。</figcaption>\n  </figure>\n  <p>没有签名会怎样？token 里只装用户名的话，黑客自己造一张、把用户名写成 admin 就冒充管理员了。加了签名，改动任何一个字封印就破，服务器一验便知。</p>\n  <div class=\"key\"><span class=\"tag\">新手最大的坑</span>以为 token 是加密保密的。payload 只是 base64 编码，<b>任何人都能解开看</b>。密码、手机号这类敏感信息千万别塞进 token。JWT 防篡改，不防偷看。</div>\n  <div class=\"recap\"><b>收束：</b>头声明算法、身体装信息、签名防伪造；信息可见但不可改，敏感信息不进 payload。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>登录发证：五步里藏着 BCrypt 的门道</h2>\n  <p>前端 <code>POST /admin/login</code>，<code>UmsAdminController</code> 转给 Service，mall 的 <code>login()</code> 按顺序做五件事：</p>\n  <pre>① UserDetails u = loadUserByUsername(username);   // 查出这个人（走缓存）\n② passwordEncoder.matches(password, u.getPassword()) // 明文 vs 库里密文\n③ u.isEnabled()                                    // 账号是否被禁用\n④ SecurityContextHolder.getContext().setAuthentication(...) // 本次请求的记事本\n⑤ token = jwtTokenUtil.generateToken(u);           // 签发通行证</pre>\n  <p>第②步值得停一下：数据库里存的不是明文，是 <span class=\"term\">BCrypt</span> 加密后的密文（注册时 <code>encode()</code>），登录时用 <code>matches()</code> 比对。BCrypt 这台「乱码机器」有三个脾气：</p>\n  <ul>\n    <li><b>不可逆</b>：只能明文→密文，不能反推。数据库被拖走，黑客拿到的也是乱码。</li>\n    <li><b>带随机盐</b>：同一个密码每次加密结果都不同，防的是提前算好对照表的彩虹表攻击。</li>\n    <li><b>故意慢</b>：算一次几十毫秒。你登录只试一次，无感；黑客要试几亿次，每次都心疼。换成算得极快的 MD5，黑客每秒试几十亿次，8 位密码几小时就破。慢是一种不对称防御。</li>\n  </ul>\n  <div class=\"note\"><span class=\"tag\">两把锁各管一段</span>传输路上被偷看归 HTTPS 防，数据库被拖库归 BCrypt 防。明文密码在系统里只活一瞬间：传进来→内存里比对完→没了。<b>明文永远不落库、不写日志。</b></div>\n  <div class=\"recap\"><b>收束：</b>查人→比密文→查禁用→记认证→发 token；BCrypt 用不可逆、随机盐、故意慢守住存储这一关。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>每次请求过闸机：验完身份还要验权限</h2>\n  <p>登录后访问商品列表，前端带请求头 <code>Authorization: Bearer eyJhbG...</code>。Bearer 是协议约定，意思是「我来送一张通行证」。每个请求都要过 <code>JwtAuthenticationTokenFilter</code> 这道安检闸机，三步：</p>\n  <figure>\n    <svg viewBox=\"0 0 760 170\" role=\"img\" aria-label=\"过滤器三步与动态权限\">\n      <defs><marker id=\"ars2d\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"34\" width=\"170\" height=\"62\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"93\" y=\"59\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">① 抠出 token</text><text x=\"93\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">去掉 Bearer 前缀</text>\n      <rect x=\"210\" y=\"34\" width=\"170\" height=\"62\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"295\" y=\"59\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">② 验签+解析用户名</text><text x=\"295\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">不查库，很快</text>\n      <rect x=\"412\" y=\"34\" width=\"170\" height=\"62\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"497\" y=\"59\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">③ 查人+验过期</text><text x=\"497\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">放进 SecurityContext</text>\n      <rect x=\"614\" y=\"34\" width=\"138\" height=\"62\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"683\" y=\"59\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">动态权限</text><text x=\"683\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">没权限→403</text>\n      <line x1=\"178\" y1=\"65\" x2=\"208\" y2=\"65\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars2d)\"/>\n      <line x1=\"380\" y1=\"65\" x2=\"410\" y2=\"65\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars2d)\"/>\n      <line x1=\"582\" y1=\"65\" x2=\"612\" y2=\"65\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars2d)\"/>\n      <text x=\"380\" y=\"130\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">身份=你是谁；权限=你能不能进这个门。业务代码拿到的是已认证+带权限的完整信息</text>\n      <text x=\"380\" y=\"152\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">登录/注册等白名单接口走 ignored.urls，不过这道闸（否则登录本身都 401）</text>\n    </svg>\n    <figcaption>图 2 · 闸机三步 + 动态权限。权限存数据库，改库就能加权限，不用重新发版。</figcaption>\n  </figure>\n  <p>验完身份，<code>DynamicAuthorizationManager</code> 再对照「当前用户的权限列表里有没有这个接口需要的权限」，有就放行，没有返回 403。mall 的权限是<b>动态</b>的：用户→角色→接口权限存在数据库里，登录后查出来放进缓存。</p>\n  <p>配置里有三个必须盯住的点：<code>jwt.secret</code> 默认密钥生产环境必须换（泄露=任何人可伪造 token）；<code>tokenHead</code> 前缀前后端要对上，否则 substring 抠不出 token；登录、注册、文档接口要进白名单 <code>ignored.urls</code>，不然连登录都进不来。</p>\n  <div class=\"recap\"><b>收束：</b>闸机三步认人，动态权限管门；密钥要换、前缀要对、白名单别漏。</div>\n</section>\n\n<section id=\"e\">\n  <h2><span class=\"no\">第 5 步</span>机制公用业务各自，以及本仓库的双 token 改造</h2>\n  <p>后台和前台都要登录，安全逻辑一样，mall 把它抽成 <code>mall-security</code> 模块：写一次，两处复用。更关键的是<b>机制和业务分开</b>——security 只管怎么验 token、怎么鉴权；用户从哪个表查、密码对不对，由各业务应用通过 <code>UserDetailsService</code> 接口交进来。admin 交的是查管理员，portal 交的是查会员。不能有人拿会员卡来，就发办公室钥匙。</p>\n  <p>反方向的协作闭环也值得看懂：<code>CommonSecurityConfig</code> 用 <code>@Bean</code> 注册 <code>JwtTokenUtil</code> 和 <code>PasswordEncoder</code>；admin 启动类扫 <code>com.macro.mall</code> 及子包，正好扫到 security 的配置类；<code>UmsAdminServiceImpl</code> 里 <code>@Autowired</code> 按类型注入，直接调方法。编译期靠 pom 依赖，运行期靠扫描装配，注入期靠容器对接。</p>\n  <div class=\"key\"><span class=\"tag\">本仓库已改造（可照搬样板）</span>本地源码在原始单 token（7 天）基础上升级为<b>双 token + 版本号单点登录</b>：accessToken 15 分钟管日常访问，refreshToken 7 天只在过期时换新；登录时 Redis 版本号 <code>incr</code> +1，新 token 带新版本，旧设备 token 版本对不上即被强制下线。<b>关键坑：access 和 refresh 都要校验版本号</b>，否则旧 refresh 能绕过下线换到新 access。</div>\n  <table>\n    <tr><th>维度</th><th>原始 mall</th><th>本仓库改造后</th></tr>\n    <tr><td>登录返回</td><td>单 token（7 天）</td><td>accessToken(900s) + refreshToken(604800s)</td></tr>\n    <tr><td>续期</td><td>拿未过期旧 token 续</td><td>refresh 换新 access；refresh 过期须重登</td></tr>\n    <tr><td>强制下线</td><td>无，旧 token 一直有效</td><td>版本号 +1，旧 token 全作废</td></tr>\n    <tr><td>前端配合</td><td>存单 token</td><td>401 时用 refresh 刷新并重放原请求（带并发锁）</td></tr>\n  </table>\n  <div class=\"recap\"><b>收束：</b>机制打包在 security、业务各自实现；双 token 管续期、版本号管下线，两条链都要验版本。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：通行证检查台、破解成本计算器</h2>\n  <p>演练一往闸机里塞四种不同的通行证，看它卡在哪一步。演练二算一笔账：同样的密码，MD5 和 BCrypt 各要多久才被暴力破解。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 通行证检查台</b><span class=\"hint\">点按钮换一张 token 过闸</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"ok\" class=\"on\">正常通行证</button><button data-k=\"tamper\">改了用户名</button><button data-k=\"expired\">已过期</button><button data-k=\"oldver\">旧版本号</button></div></div>\n    <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>闸机日志</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">四种结局：放行 / 验签拒 / 过期拒 / 版本拒</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 暴力破解成本计算器</b><span class=\"hint\">换算法、拖密码位数，看黑客要算多久</span></div>\n    <div class=\"controls\">\n      <div class=\"seg\" id=\"g1alg\"><button data-k=\"md5\" class=\"on\">MD5（极快）</button><button data-k=\"bcrypt\">BCrypt（故意慢）</button></div>\n      <div class=\"ctl\"><label>密码位数</label><input type=\"range\" id=\"g1len\" min=\"6\" max=\"12\" value=\"8\"><span class=\"val\" id=\"g1lenV\">8</span></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>算账过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">模型：62 种字符；MD5 每秒 10 亿次，BCrypt 每秒 50 次（数量级示意）；按平均试一半计</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>闸机的每一步各拦一种假证；BCrypt 的慢让攻击者每试一次都心疼，而你只付一次几十毫秒。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>六个问题</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。门禁这套你已经能跟面试官过招了。下一课看为什么每次请求都先查 Redis。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>速查表</h2>\n  <table>\n    <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n    <tr><td>Session vs JWT</td><td>服务器记账 vs 客户端带证</td><td>有状态难扩展，无状态谁都能验</td></tr>\n    <tr><td>JWT 三段</td><td>头/身体/封印</td><td>payload 可解开看，敏感信息不放</td></tr>\n    <tr><td>签名</td><td>密钥算出的封印</td><td>防篡改不防偷看；secret 必须换</td></tr>\n    <tr><td>BCrypt</td><td>故意慢的乱码机器</td><td>不可逆+随机盐+慢；matches 比密文</td></tr>\n    <tr><td>过滤器三步</td><td>抠证→验签→查人验期</td><td>认证信息放 SecurityContextHolder</td></tr>\n    <tr><td>动态权限</td><td>权限存库改库即生效</td><td>身份≠权限；没权限 403</td></tr>\n    <tr><td>机制公用业务各自</td><td>门禁设备共用，资料各自查</td><td>UserDetailsService 接口交接</td></tr>\n    <tr><td>双 token + 版本号</td><td>短证日常用，长证换新的</td><td>access/refresh 都要验版本，防绕过下线</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>原始逻辑以底稿为准；双 token/版本号部分描述的是本仓库改造后的源码（JwtTokenUtil/LoginTokenResult 已在本地核对）。破解速度为数量级示意，非实测。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第二篇-登录认证与JWT（含双 token 改造附录） <span class=\"src\">— 本课重写底稿</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/</code> <span class=\"src\">— 已改造为双 token + 版本号单点登录</span></li>\n    </ul>\n    <h3>源码路标（相对 mall 工程根）</h3>\n    <ul>\n      <li><code>mall-security/.../util/JwtTokenUtil.java</code>、<code>util/LoginTokenResult.java</code> <span class=\"src\">— 双 token 签发与返回 DTO（改造新增）</span></li>\n      <li><code>mall-security/.../component/JwtAuthenticationTokenFilter.java</code> <span class=\"src\">— 安检闸机，验签+版本号比对</span></li>\n      <li><code>mall-security/.../component/DynamicAuthorizationManager.java</code>、<code>config/CommonSecurityConfig.java</code> <span class=\"src\">— 动态权限与机制 Bean 注册</span></li>\n      <li><code>mall-admin/.../service/impl/UmsAdminServiceImpl.java</code>、<code>mall-admin/src/main/resources/application.yml</code> <span class=\"src\">— 登录五步、jwt 配置与白名单</span></li>\n    </ul>\n    <h3>官方文档</h3>\n    <ul>\n      <li><a href=\"https://jwt.io/introduction\" target=\"_blank\" rel=\"noopener\">JWT · Introduction to JSON Web Tokens</a> <span class=\"src\">— 三段结构与签名原理</span></li>\n      <li><a href=\"https://docs.spring.io/spring-security/reference/index.html\" target=\"_blank\" rel=\"noopener\">Spring Security Reference</a> <span class=\"src\">— 过滤器链、认证授权架构</span></li>\n      <li><a href=\"https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html\" target=\"_blank\" rel=\"noopener\">OWASP · Password Storage Cheat Sheet</a> <span class=\"src\">— BCrypt 与密码存储规范</span></li>\n    </ul>\n    <h3>下一课要用</h3>\n    <ul>\n      <li><a href=\"https://redis.io/docs/latest/develop/get-started/\" target=\"_blank\" rel=\"noopener\">Redis · Get started</a> <span class=\"src\">— S3 缓存主角，登录查人走的缓存就是它</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"Session 的麻烦"},{"id":"b","title":"JWT 三段式"},{"id":"c","title":"登录五步与 BCrypt"},{"id":"d","title":"闸机与动态权限"},{"id":"e","title":"机制复用与双 token"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    ok:{code:\"Authorization: Bearer eyJhbG...(v3)\\n① 抠出 token：去掉 Bearer 前缀 ✓\\n② 验签：重算签名一致 ✓ 解析出 admin\\n③ 查人(缓存) + 未过期 ✓ + 版本 v3=v3 ✓\\n→ 放入 SecurityContext，动态权限放行\",log:[[\"ok\",\"验签通过：payload 没被改过\"],[\"ok\",\"未过期，版本号与 Redis 一致\"],[\"ok\",\"放行：业务代码拿到完整认证信息\"]]},\n    tamper:{code:\"Authorization: Bearer eyJhbG...(payload 改成 admin)\\n① 抠出 token ✓\\n② 验签：重算签名 ≠ token 里的签名 ✗\\n→ 拒绝。黑客没有服务器密钥，造不出合法封印\",log:[[\"err\",\"验签失败：改了一个字，封印就破\"],[\"c\",\"// 这就是 signature 存在的意义\"],[\"warn\",\"若 secret 泄露，黑客就能自己签——密钥必须换\"]]},\n    expired:{code:\"Authorization: Bearer eyJhbG...(exp 已过)\\n① 抠出 token ✓\\n② 验签 ✓（签名没破）\\n③ validateToken：已过期 ✗ → 401\\n前端：用 refreshToken 换新 access 再重放\",log:[[\"warn\",\"签名合法但已过期 → 401\"],[\"api\",\"双 token：refresh 换新 access，用户无感\"],[\"c\",\"// refresh 也过期 = 必须重新登录\"]]},\n    oldver:{code:\"Authorization: Bearer eyJhbG...(version=v2)\\n① 抠出 token ✓ ② 验签 ✓ ③ 未过期 ✓\\n④ 版本比对：token v2 ≠ Redis v3 ✗\\n→ 拒绝：该账号已在新设备登录，旧端强制下线\",log:[[\"err\",\"版本号对不上：登录已失效\"],[\"c\",\"// 登录时 incr 版本号，旧 token 全作废\"],[\"warn\",\"refresh 接口也要验版本，否则旧 refresh 绕过下线\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById(\"e1code\").textContent=c.code;\n    document.getElementById(\"e1log\").innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"ok\");\n})();\n\n(function(){\n  function fmt(sec){\n    if(sec<1)return '<1 秒';\n    if(sec<60)return Math.round(sec)+' 秒';\n    if(sec<3600)return (sec/60).toFixed(1)+' 分钟';\n    if(sec<86400)return (sec/3600).toFixed(1)+' 小时';\n    if(sec<31536000)return (sec/86400).toFixed(1)+' 天';\n    var y=sec/31536000;\n    if(y<1e4)return y.toFixed(1)+' 年';\n    if(y<1e8)return (y/1e4).toFixed(1)+' 万年';\n    return (y/1e8).toFixed(1)+' 亿年';\n  }\n  var alg='md5';\n  function calc(){\n    var len=parseInt(document.getElementById('g1len').value,10);\n    document.getElementById('g1lenV').textContent=len;\n    var combos=Math.pow(62,len);\n    var rate=alg==='md5'?1e9:50;\n    var sec=combos/2/rate;\n    var userCost=alg==='md5'?'微秒级':'几十毫秒';\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>62^'+len+'</b><small>组合数≈'+combos.toExponential(1)+'</small></div>'+\n      '<div class=\"stat-box\"><b>'+(alg==='md5'?'10亿':'50')+'/秒</b><small>攻击者尝试速度</small></div>'+\n      '<div class=\"stat-box '+(sec>31536000*100?'good':'bad')+'\"><b>'+fmt(sec)+'</b><small>平均破解耗时</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(alg==='bcrypt'?'on':'bad')+'\">'+(alg==='bcrypt'?'故意慢：攻击者心疼':'极快：黑客每秒几十亿次')+'</span>'+\n      '<span class=\"chip on\">合法用户单次成本：'+userCost+'</span>'+\n      (alg==='md5'&&len<=8?'<span class=\"chip bad\">8 位内 MD5 很快沦陷</span>':'');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">不对称</span>'+\n      (alg==='md5'?'MD5 算得极快，对黑客是好消息：每秒几十亿次，短密码几小时内破。快哈希不适合存密码。':'BCrypt 每次几十毫秒，你登录只付一次；黑客要试 '+combos.toExponential(1)+' 次的一半，耗时就变成天文数字。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">组合数 = 62^'+len+' ≈ '+combos.toExponential(2)+'</span></div>',\n      '<div><span class=\"ok\">平均要试一半 ≈ '+(combos/2).toExponential(2)+' 次</span></div>',\n      '<div><span class=\"'+(alg==='md5'?'err':'ok')+'\">耗时 = 次数 ÷ '+rate.toExponential(0)+'/秒 ≈ '+fmt(sec)+'</span></div>',\n      '<div><span class=\"c\">// 另记：BCrypt 随机盐让彩虹表失效，这里只算暴力破解</span></div>'\n    ].join('');\n  }\n  document.querySelectorAll('#g1alg button').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('#g1alg button').forEach(function(x){x.classList.remove('on');});b.classList.add('on');alg=b.getAttribute('data-k');calc();});});\n  document.getElementById('g1len').addEventListener('input',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 多台服务器时 Session 的麻烦是？\",\"opts\":[[\"Session 存在某一台上，别的服务器认不出\",true,\"对。要共享或粘性会话。\"],[\"Session 会自动同步\",false,\"默认不会。\"],[\"JWT 也要共享 Session\",false,\"JWT 无状态不存。\"]]},{\"q\":\"2. JWT 的三段是？\",\"opts\":[[\"header / payload / signature\",true,\"对。算法声明/信息/封印。\"],[\"用户名 / 密码 / 过期时间\",false,\"密码绝不进 token。\"],[\"加密头 / 加密体 / 密钥\",false,\"payload 不加密。\"]]},{\"q\":\"3. JWT 能防什么、不能防什么？\",\"opts\":[[\"防篡改，不防偷看\",true,\"对。payload 是 base64 可解开。\"],[\"防偷看，不防篡改\",false,\"反了。\"],[\"既防篡改又防偷看\",false,\"payload 谁都能看。\"]]},{\"q\":\"4. BCrypt 故意慢的意义是？\",\"opts\":[[\"让暴力破解每次尝试都付出高成本\",true,\"对。用户只试一次无感。\"],[\"防止用户登录太快\",false,\"不是。\"],[\"让数据库查询变慢\",false,\"与查询无关。\"]]},{\"q\":\"5. 双 token 方案里 refreshToken 的职责？\",\"opts\":[[\"access 过期时换新的 access\",true,\"对。refresh 过期须重登。\"],[\"每次请求都带上访问接口\",false,\"日常访问用 access。\"],[\"替代密码登录\",false,\"首次登录仍靠账号密码。\"]]},{\"q\":\"6. 版本号单点登录的关键坑是？\",\"opts\":[[\"access 和 refresh 都要校验版本号\",true,\"对。否则旧 refresh 绕过下线。\"],[\"只验 access 就够\",false,\"refresh 会漏。\"],[\"版本号存前端\",false,\"存 Redis，服务端比对。\"]]}];" },
    "backend|java|Redis 缓存：为什么先查缓存再查库": { "body": "<p class=\"lead\">源码解读第三课：mall 每次请求验身份都先查 Redis，为什么？看懂「住在内存里的数据库」怎么用内存换时间，拆开 Cache-Aside 三步和改权限时的连锁失效，再亲手拖一拖命中率，看数据库什么时候被救、什么时候被压垮。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">问题</span><span class=\"s\">数据库为什么慢</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">认识</span><span class=\"s\">内存换时间</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">模式</span><span class=\"s\">Cache-Aside</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">一致性</span><span class=\"s\">主动删+连锁</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">动手</span><span class=\"s\">演练与自测</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>每卖一瓶水都跑一趟仓库，店迟早瘫痪</h2>\n  <p>想象一家便利店：店员每卖一瓶水，都要跑去后面的大仓库找一遍货。顾客少还行，晚高峰一来，店员全在仓库和柜台之间来回跑，收银台排起长队。聪明的做法谁都见过——把卖得最快的几十种商品摆到<b>柜台边的小货架</b>，随手就拿，仓库只在补货时去。</p>\n  <p>后端一模一样。业务数据存在 MySQL 里，数据在<b>磁盘</b>上：磁盘读写是毫秒级，内存是纳秒级，差几个数量级；数据库还要做 SQL 解析、事务、索引，每次查询都有固定开销。用户每点一个按钮就查一次库，人一多，数据库就是瓶颈，慢查询会拖垮整个系统。</p>\n  <p>mall 的答案就是那个小货架：<span class=\"term\">Redis</span>，一个把数据存在<b>内存</b>里的键值数据库。把「高频读、不怎么变」的数据从慢的磁盘搬到快的内存，随取随用。本质四个字：<b>用内存换时间</b>。</p>\n  <div class=\"recap\"><b>收束：</b>MySQL 是大仓库管持久账本，Redis 是柜台小货架管快取快用；慢的根源在磁盘和查询开销。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>Redis 是什么：住内存、带过期、结构多</h2>\n  <table>\n    <tr><th></th><th>MySQL</th><th>Redis</th></tr>\n    <tr><td>数据存哪</td><td>磁盘</td><td>内存</td></tr>\n    <tr><td>读取速度</td><td>毫秒级</td><td>微秒级，快几个数量级</td></tr>\n    <tr><td>用途</td><td>核心业务数据，持久</td><td>热点数据缓存，快取快用</td></tr>\n    <tr><td>数据结构</td><td>表 / 行</td><td>key-value，另有 list/set/hash/zset</td></tr>\n  </table>\n  <p>除了缓存，Redis 常干的活还有：验证码（短命高频，自带过期正合适）、计数器（<code>INCR</code> 原子自增，点赞数订单号）、分布式锁（多台服务器抢同一资源）、Session 共享。这一课聚焦 mall 的核心用法——缓存。</p>\n  <p>一个关键特性是 <span class=\"term\">TTL</span>：每个 key 都能设过期时间，到点自动删。<code>SET key value EX 90</code> 就是「存进去，90 秒后自动消失」。它防止数据永久占着内存，也顺手实现了验证码过期这类需求。</p>\n  <div class=\"note\"><span class=\"tag\">Redis 为什么快（面试常问）</span>① 基于内存；② 命令执行单线程，避免线程切换和锁竞争；③ IO 多路复用；④ 高效数据结构。四条一起答，别只说「因为在内存里」。</div>\n  <div class=\"recap\"><b>收束：</b>内存键值库 + TTL 自动过期 + 多种结构；缓存、验证码、计数、锁、Session 共享都是它的活。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>Cache-Aside：先缓存、再数据库、查到写回</h2>\n  <p>mall 缓存用户信息用的是业界标准模式 <span class=\"term\">Cache-Aside（旁路缓存）</span>。看 <code>UmsAdminServiceImpl.getAdminByUsername()</code> 的真实骨架：</p>\n  <pre>UmsAdmin admin = getCacheService().getAdmin(username);  // ① 先查缓存\nif (admin != null) return admin;                        //    命中直接返回\n// ② 没命中才查数据库\nList&lt;UmsAdmin&gt; list = adminMapper.selectByExample(example);\nif (list != null &amp;&amp; list.size() &gt; 0) {\n    admin = list.get(0);\n    getCacheService().setAdmin(admin);                  // ③ 查到写回缓存\n    return admin;\n}</pre>\n  <figure>\n    <svg viewBox=\"0 0 760 200\" role=\"img\" aria-label=\"Cache-Aside 三步流程\">\n      <defs><marker id=\"ars3\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"60\" width=\"140\" height=\"60\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"78\" y=\"85\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">请求要用户信息</text><text x=\"78\" y=\"103\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">每次鉴权都要读</text>\n      <rect x=\"196\" y=\"60\" width=\"150\" height=\"60\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"271\" y=\"85\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">① 查 Redis</text><text x=\"271\" y=\"103\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">mall:ums:admin:admin</text>\n      <rect x=\"404\" y=\"16\" width=\"150\" height=\"52\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"479\" y=\"38\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">命中 → 直接返回</text><text x=\"479\" y=\"56\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">微秒级，不碰数据库</text>\n      <rect x=\"404\" y=\"112\" width=\"150\" height=\"52\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"479\" y=\"134\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">② 未命中 → 查 MySQL</text><text x=\"479\" y=\"152\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">毫秒级</text>\n      <rect x=\"600\" y=\"112\" width=\"152\" height=\"52\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"676\" y=\"134\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">③ 写回缓存</text><text x=\"676\" y=\"152\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">下次直接命中</text>\n      <line x1=\"148\" y1=\"90\" x2=\"194\" y2=\"90\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars3)\"/>\n      <line x1=\"346\" y1=\"76\" x2=\"402\" y2=\"46\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars3)\"/>\n      <line x1=\"346\" y1=\"104\" x2=\"402\" y2=\"134\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars3)\"/>\n      <line x1=\"554\" y1=\"138\" x2=\"598\" y2=\"138\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars3)\"/>\n      <text x=\"380\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">口诀：先缓存 → 再数据库 → 查到写回。缓存领域的标准答案。</text>\n    </svg>\n    <figcaption>图 1 · Cache-Aside 三步。mall 缓存的两类 key：用户信息 ums:admin、权限列表 ums:resourceList，TTL 24 小时。</figcaption>\n  </figure>\n  <p>为什么偏偏缓存这两样？上一课讲过，<b>每次请求</b>过安检闸机都要查「这个人」和「他的权限」——读得最频繁，改得却很少。实际 key 形如 <code>mall:ums:admin:admin</code>、<code>mall:ums:resourceList:1</code>，配置里 <code>expire.common: 86400</code>（24 小时）。这就是「为什么每次请求都从缓存查」的答案。</p>\n  <div class=\"recap\"><b>收束：</b>高频读低频改的数据才值得缓存；Cache-Aside 三步是到处都用的标准答案。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>改了必须删：主动删除 + 连锁失效</h2>\n  <p>缓存天生的毛病：数据改了，缓存里还是旧的。mall 不靠「等自然过期」，靠<b>主动删除</b>——更新完数据库立刻删缓存，下次没命中自动去库里拿新的：</p>\n  <pre>int count = adminMapper.updateByPrimaryKeySelective(admin);\ngetCacheService().delAdmin(id);   // 更新库后立刻删缓存\nreturn count;</pre>\n  <p>更严谨的是那一排删除方法，后两个是<b>连锁失效</b>：</p>\n  <table>\n    <tr><th>方法</th><th>什么时候调</th><th>删掉谁</th></tr>\n    <tr><td><code>delAdmin(adminId)</code></td><td>用户信息变了</td><td>该用户的缓存</td></tr>\n    <tr><td><code>delResourceList(adminId)</code></td><td>某用户的角色变了</td><td>该用户的权限缓存</td></tr>\n    <tr><td><code>delResourceListByRole(roleId)</code></td><td>某角色的权限变了</td><td><b>所有</b>担任该角色用户的缓存</td></tr>\n    <tr><td><code>delResourceListByResource(resourceId)</code></td><td>某接口的权限变了</td><td><b>所有</b>能访问该接口用户的缓存</td></tr>\n  </table>\n  <p>改一个「商品管理员」角色的权限，担任这个角色的可能有几百人，几百份权限缓存全删。效果是后台改权限<b>立即生效</b>，不等 24 小时过期，更不用重启服务。</p>\n  <div class=\"key\"><span class=\"tag\">为什么是删，不是更新缓存</span>并发写时「更新缓存」容易把旧值写回去（A 先更新库、B 后更新库，但 B 先写缓存 A 后写缓存，缓存里留下 A 的旧值）。<b>删除更安全</b>：下次读时从库里拿最新再写回。简历上写「熟悉缓存优化」，指的就是这套组合拳，不是会敲 redis.set。</div>\n  <div class=\"recap\"><b>收束：</b>缓存优先 + 主动删除 + 连锁失效；先更新库再删缓存，删除比更新安全。</div>\n</section>\n\n<section id=\"e\">\n  <h2><span class=\"no\">第 5 步</span>什么时候别用缓存，以及面试经典三连</h2>\n  <p>判断口诀：<b>高频读 + 低频改 + 能容忍短暂不一致 → 用缓存，三条缺一都别硬缓存。</b>读写都频繁且要强一致的数据，缓存反而引入一致性麻烦；几乎不读的数据，缓存白占内存；缓存和库之间总有哪怕几毫秒的不同步，接受不了就别用。</p>\n  <p>面试重灾区「穿透 / 击穿 / 雪崩」，一张表分清：</p>\n  <table>\n    <tr><th>名字</th><th>现象</th><th>常用解法</th></tr>\n    <tr><td>穿透</td><td>查一个<b>根本不存在</b>的 key，缓存永远没命中，每次都打库</td><td>缓存空值 / 布隆过滤器</td></tr>\n    <tr><td>击穿</td><td><b>一个热点 key</b> 过期瞬间，大量请求同时打库</td><td>分布式锁 / 逻辑过期</td></tr>\n    <tr><td>雪崩</td><td><b>大量 key 同一时间</b>集体过期，请求洪峰打库</td><td>TTL 加随机值 / 多级缓存 / 限流降级</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">本地跑起来的三个坑</span>① Redis 服务没起，程序连接超时——先 docker ps 确认；② 容器里连 Redis 写 localhost 连不上，要写容器名（同 Docker 网络）；③ 改了数据没删缓存，排查半天发现拿到的是旧值。<code>docker exec -it mall-redis redis-cli ping</code> 返回 PONG 才算起好了。</div>\n  <div class=\"recap\"><b>收束：</b>三条口诀决定用不用；穿透查不存在、击穿单热点过期、雪崩集体过期，解法各不相同。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：读路径对照、命中率沙盒</h2>\n  <p>演练一切换三种读场景，看请求走哪条路、卡在哪。演练二拖 QPS 和命中率，看落到数据库的压力什么时候超标——这就是「为什么必须缓存」的数字化版本。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 一次读取走哪条路</b><span class=\"hint\">点按钮切换场景</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"hit\" class=\"on\">缓存命中</button><button data-k=\"miss\">未命中写回</button><button data-k=\"stale\">改库忘删缓存</button></div></div>\n    <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>读取日志</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">第三条路就是生产事故里最常见的「怎么改了半天没生效」</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 命中率沙盒</b><span class=\"hint\">拖滑杆，看数据库扛不扛得住</span></div>\n    <div class=\"controls\">\n      <div class=\"ctl\"><label>请求 QPS</label><input type=\"range\" id=\"g1qps\" min=\"100\" max=\"5000\" step=\"100\" value=\"2000\"><span class=\"val\" id=\"g1qpsV\">2000</span></div>\n      <div class=\"ctl\"><label>命中率%</label><input type=\"range\" id=\"g1hit\" min=\"0\" max=\"99\" value=\"95\"><span class=\"val\" id=\"g1hitV\">95</span></div>\n      <div class=\"ctl\"><label>DB 容量 QPS</label><input type=\"range\" id=\"g1cap\" min=\"100\" max=\"1000\" step=\"50\" value=\"500\"><span class=\"val\" id=\"g1capV\">500</span></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">模型：Redis 0.1ms/次，MySQL 5ms/次（数量级示意）；落库 QPS = 总 QPS × (1-命中率)</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>命中率每掉一个点，数据库压力就涨一截；缓存的价值不在「会用命令」，在于把落库压力算清楚、把失效做干净。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>六个问题</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。缓存这套组合拳你已经能讲给面试官听了。下一课看浏览记录为什么搬去 MongoDB。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>速查表</h2>\n  <table>\n    <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n    <tr><td>Redis</td><td>住在内存里的键值库</td><td>用内存换时间；微秒级</td></tr>\n    <tr><td>TTL</td><td>到点自动消失</td><td>SET ... EX 秒；防占内存</td></tr>\n    <tr><td>Cache-Aside</td><td>先缓存→再库→写回</td><td>标准答案，三步缺一不可</td></tr>\n    <tr><td>mall 缓存的两样</td><td>用户信息+权限列表</td><td>每次鉴权都读；TTL 24h</td></tr>\n    <tr><td>主动删+连锁失效</td><td>改了立刻删，牵连的全删</td><td>ByRole/ByResource 立即生效</td></tr>\n    <tr><td>删而非更新</td><td>下次读时拿最新写回</td><td>避免并发写回旧值</td></tr>\n    <tr><td>穿透/击穿/雪崩</td><td>不存在/单热点过期/集体过期</td><td>空值布隆/锁逻辑过期/随机TTL</td></tr>\n    <tr><td>选型口诀</td><td>高频读+低频改+容忍短暂不一致</td><td>三条缺一别硬缓存</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>源码行为依据本仓库 mall 当前实现；延迟与容量数字为数量级示意，非实测压测。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第三篇-Redis缓存 <span class=\"src\">— 本课重写底稿</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/</code>；编排 <code>mall-docker/docker-compose.yml</code> <span class=\"src\">— Redis 服务随编排启动</span></li>\n    </ul>\n    <h3>源码路标（相对 mall 工程根）</h3>\n    <ul>\n      <li><code>mall-admin/.../service/impl/UmsAdminServiceImpl.java</code> <span class=\"src\">— getAdminByUsername 的 Cache-Aside 三步与更新后删缓存</span></li>\n      <li><code>mall-admin/.../service/UmsAdminCacheService.java</code> 及其实现 <span class=\"src\">— delAdmin/delResourceList/ByRole/ByResource 连锁失效</span></li>\n      <li><code>mall-admin/src/main/resources/application.yml</code> <span class=\"src\">— redis.database/key/expire 配置（86400s）</span></li>\n    </ul>\n    <h3>官方文档</h3>\n    <ul>\n      <li><a href=\"https://redis.io/docs/latest/develop/\" target=\"_blank\" rel=\"noopener\">Redis Docs · Develop</a> <span class=\"src\">— 数据类型、过期、命令参考</span></li>\n      <li><a href=\"https://docs.spring.io/spring-data/redis/reference/\" target=\"_blank\" rel=\"noopener\">Spring Data Redis Reference</a> <span class=\"src\">— mall 使用的客户端封装</span></li>\n      <li><a href=\"https://github.com/macrozheng/mall\" target=\"_blank\" rel=\"noopener\">macrozheng/mall · GitHub</a> <span class=\"src\">— 上游项目</span></li>\n    </ul>\n    <h3>下一课要用</h3>\n    <ul>\n      <li><a href=\"https://www.mongodb.com/docs/manual/\" target=\"_blank\" rel=\"noopener\">MongoDB Manual</a> <span class=\"src\">— S4 浏览记录的去处</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"仓库与货架"},{"id":"b","title":"Redis 是什么"},{"id":"c","title":"Cache-Aside 三步"},{"id":"d","title":"主动删+连锁失效"},{"id":"e","title":"边界与三连"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    hit:{code:\"getAdminByUsername(\\\"admin\\\")\\n① GET mall:ums:admin:admin → 命中\\nreturn admin;  // 0.1ms，不碰 MySQL\",log:[[\"ok\",\"缓存命中：微秒级返回\"],[\"c\",\"// 每次鉴权都走这条快路\"],[\"ok\",\"数据库压力：0\"]]},\n    miss:{code:\"getAdminByUsername(\\\"newuser\\\")\\n① GET mall:ums:admin:newuser → nil\\n② SELECT ... FROM ums_admin → 5ms\\n③ SET mall:ums:admin:newuser (EX 86400)\\nreturn admin;  // 下次直接命中\",log:[[\"warn\",\"未命中：查库一次\"],[\"api\",\"写回缓存，TTL 24 小时\"],[\"ok\",\"下次同样的请求走快路\"]]},\n    stale:{code:\"update(admin)  // 只更新了 MySQL\\n// getCacheService().delAdmin(id)  ← 忘了调！\\n下次读取：GET → 命中旧值\\n前端：怎么改了半小时还没生效？？\",log:[[\"err\",\"缓存里还是旧数据，命中即返回旧值\"],[\"warn\",\"要等 24h TTL 自然过期才恢复\"],[\"c\",\"// 改数据必须同步删缓存——排查头号嫌疑\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById(\"e1code\").textContent=c.code;\n    document.getElementById(\"e1log\").innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"hit\");\n})();\n\n(function(){\n  function calc(){\n    var qps=parseInt(document.getElementById('g1qps').value,10);\n    var hit=parseInt(document.getElementById('g1hit').value,10);\n    var cap=parseInt(document.getElementById('g1cap').value,10);\n    document.getElementById('g1qpsV').textContent=qps;\n    document.getElementById('g1hitV').textContent=hit;\n    document.getElementById('g1capV').textContent=cap;\n    var dbQps=qps*(100-hit)/100;\n    var avg=(hit/100)*0.1+(1-hit/100)*5;\n    var ok=dbQps<=cap;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(ok?'good':'bad')+'\"><b>'+Math.round(dbQps)+'</b><small>落到 MySQL 的 QPS</small></div>'+\n      '<div class=\"stat-box\"><b>'+avg.toFixed(2)+'ms</b><small>平均读延迟</small></div>'+\n      '<div class=\"stat-box\"><b>'+cap+'</b><small>DB 容量上限</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(ok?'on':'bad')+'\">'+(ok?'DB 扛得住':'DB 超载 '+Math.round(dbQps-cap)+' QPS')+'</span>'+\n      '<span class=\"chip '+(hit>=90?'on':'bad')+'\">命中率 '+hit+'%</span>'+\n      (hit===0?'<span class=\"chip bad\">等于没上缓存</span>':'');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(ok?'算账':'告警')+'</span>'+\n      (ok?'落库 QPS = '+qps+' × '+(100-hit)+'% = '+Math.round(dbQps)+'，在容量 '+cap+' 之内。命中率就是数据库的护城河。':'落库 '+Math.round(dbQps)+' 超过容量 '+cap+'。要么提命中率（缓存更多热点），要么扩容/限流。命中率掉到 '+Math.max(0,Math.floor(100-cap/qps*100))+'% 以下就会超载。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">落库 QPS = '+qps+' × (1 - '+hit+'%) = '+Math.round(dbQps)+'</span></div>',\n      '<div><span class=\"ok\">平均延迟 = '+hit+'%×0.1ms + '+(100-hit)+'%×5ms ≈ '+avg.toFixed(2)+'ms</span></div>',\n      '<div><span class=\"'+(ok?'ok':'err')+'\">'+(ok?'≤ 容量 '+cap+'，安全':'＞ 容量 '+cap+'，数据库要被打垮')+'</span></div>',\n      '<div><span class=\"c\">// 高频读+低频改的数据，命中率天然容易做高</span></div>'\n    ].join('');\n  }\n  ['g1qps','g1hit','g1cap'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. Redis 比 MySQL 快的根本原因是？\",\"opts\":[[\"数据在内存，且单线程+IO多路复用+高效结构\",true,\"对。四条一起答。\"],[\"因为它是新软件\",false,\"与新旧无关。\"],[\"因为不存数据\",false,\"它存，在内存。\"]]},{\"q\":\"2. Cache-Aside 的三步口诀？\",\"opts\":[[\"先缓存→再数据库→查到写回\",true,\"对。标准答案。\"],[\"先数据库→再缓存→定时刷新\",false,\"那是另一种模式。\"],[\"只查缓存，永不查库\",false,\"未命中要查库。\"]]},{\"q\":\"3. mall 改了一个角色的权限，缓存怎么处理？\",\"opts\":[[\"连锁删除所有担任该角色用户的权限缓存\",true,\"对。delResourceListByRole。\"],[\"只删这一个角色的 key\",false,\"用户权限缓存按人存。\"],[\"等 24 小时自然过期\",false,\"要立即生效。\"]]},{\"q\":\"4. 查一个根本不存在的 key，每次都打库，这叫？\",\"opts\":[[\"缓存穿透\",true,\"对。缓存空值/布隆过滤器。\"],[\"缓存击穿\",false,\"击穿是热点 key 过期。\"],[\"缓存雪崩\",false,\"雪崩是大量 key 同时过期。\"]]},{\"q\":\"5. 大量 key 同一时间过期导致请求洪峰打库，常用解法？\",\"opts\":[[\"过期时间加随机值，错开过期\",true,\"对。另有多级缓存/限流降级。\"],[\"把 TTL 全设成一样\",false,\"正是病因。\"],[\"删掉所有缓存\",false,\"更糟。\"]]},{\"q\":\"6. 哪种数据不适合上缓存？\",\"opts\":[[\"读写都频繁且要求强一致\",true,\"对。三条口诀缺一别硬缓存。\"],[\"高频读低频改的用户信息\",false,\"正适合。\"],[\"权限列表\",false,\"mall 就缓存了它。\"]]}];" },
    "backend|java|MongoDB：浏览记录为什么不用 MySQL": { "body": "<p class=\"lead\">源码解读第四课：用户每点开一个商品就是一条浏览记录，一天几千万条，为什么 mall 不把它写进 MySQL？看懂关系型「正规账本」和文档型「流水账」的分工，拆开浏览记录从 MySQL 回填快照再存 MongoDB 的三步，最后拖一拖改价滑杆，体会快照存的是什么。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">问题</span><span class=\"s\">流水账压垮账本</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">认识</span><span class=\"s\">文档型数据库</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">源码</span><span class=\"s\">回填+保存三步</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">快照</span><span class=\"s\">当时的样子</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">动手</span><span class=\"s\">演练与自测</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>顾客每摸一件商品都要记一笔，账房先生疯了</h2>\n  <p>商场老板想知道顾客逛过什么，规定：每拿起一件商品看一眼，就记一笔。开业当天账房先生就崩溃了——买东西的账一天几百笔，「看了一眼」的账一天几十万笔。更要命的是老板天天改需求：今天记商品名和价格，明天要加「看了多久」，后天要加「从哪个页面点进来的」。账本每加一栏，整本都要重新划线。</p>\n  <p>后端就是这个账房。<span class=\"term\">浏览记录、收藏、关注</span>这类用户行为数据有三个脾气：</p>\n  <ul>\n    <li><b>写入极其频繁</b>：用户每点一下就是一条，几百万用户一天几千万条。</li>\n    <li><b>字段可能变</b>：今天记名称价格，明天想加收藏原因。</li>\n    <li><b>不需要强事务</b>：浏览记录写失败了无所谓，再记一次就行，不像扣款必须要么全成要么全撤。</li>\n  </ul>\n  <p>MySQL 是<b>正规账本</b>：结构固定、每笔都要事务保障，强在订单账户这种核心交易。让它扛疯狂追加的流水账，既吃力又憋屈。mall 的答案是给流水账单独配一个轻快的本子——<span class=\"term\">MongoDB</span>。</p>\n  <div class=\"recap\"><b>收束：</b>行为数据高写入、字段活、不要求强事务；正规账本和流水账要分开记。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>文档型数据库：一条数据就是一个 JSON</h2>\n  <p>MySQL 是关系型：数据存在表里，列在建表时定死，加字段要 <code>ALTER TABLE</code> 改表结构。MongoDB 是文档型：一条数据叫一个<b>文档</b>，长得就是 JSON，<b>不同文档的字段可以不一样</b>。张三的记录有 <code>productSubTitle</code>，李四的没有，都没关系。</p>\n  <pre>{\n  \"memberId\": 1,\n  \"memberNickname\": \"张三\",\n  \"productId\": 10,\n  \"productName\": \"iPhone 15\",\n  \"productPrice\": \"6999\",\n  \"createTime\": \"2026-08-25T10:00:00\"\n}</pre>\n  <table>\n    <tr><th></th><th>MySQL</th><th>MongoDB</th></tr>\n    <tr><td>数据模型</td><td>表 + 固定的列</td><td>文档（JSON），字段可变</td></tr>\n    <tr><td>加字段</td><td>ALTER TABLE 改结构</td><td>直接加，不改结构</td></tr>\n    <tr><td>强项</td><td>事务、关联查询</td><td>高写入、灵活结构</td></tr>\n    <tr><td>典型数据</td><td>订单、用户、商品</td><td>行为记录、日志、个性化数据</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">别抬杠</span>MongoDB 4.0 起也支持多文档事务，但开销大，它不是为强事务设计的。核心交易数据仍用 MySQL——「支持」和「擅长」是两回事。</div>\n  <div class=\"recap\"><b>收束：</b>文档=JSON、字段随写随加；MySQL 管结构固定的核心账，MongoDB 管结构灵活的流水。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>mall 源码：查两边、存一边的三步舞</h2>\n  <p>前台 <code>mall-portal</code> 用 <code>MemberReadHistoryRepository</code> 操作浏览记录，它继承 Spring Data MongoDB 的 <code>MongoRepository</code>：</p>\n  <pre>public interface MemberReadHistoryRepository\n        extends MongoRepository&lt;MemberReadHistory, String&gt; {\n    Page&lt;MemberReadHistory&gt; findByMemberIdOrderByCreateTimeDesc(Long memberId, Pageable pageable);\n    void deleteAllByMemberId(Long memberId);\n}</pre>\n  <p>这是 Spring Data 的魔法：方法名 <code>findByMemberIdOrderByCreateTimeDesc</code> 被自动翻译成「按 memberId 查、按 createTime 倒序」，不用写一行查询语句。保存一条记录的 <code>create()</code> 分三步：</p>\n  <figure>\n    <svg viewBox=\"0 0 760 210\" role=\"img\" aria-label=\"浏览记录双存储协作\">\n      <defs><marker id=\"ars4\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"70\" width=\"150\" height=\"64\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"83\" y=\"95\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">用户点开商品</text><text x=\"83\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">create(readHistory)</text>\n      <rect x=\"216\" y=\"16\" width=\"220\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"326\" y=\"39\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">① MySQL 查当前会员</text><text x=\"326\" y=\"57\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">UmsMember：id/昵称/头像</text>\n      <rect x=\"216\" y=\"128\" width=\"220\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"326\" y=\"151\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">② MySQL 回填商品快照</text><text x=\"326\" y=\"169\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">sqlEnable 时查 PmsProduct 名称/价格/图</text>\n      <rect x=\"508\" y=\"70\" width=\"244\" height=\"64\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"630\" y=\"95\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">③ 存进 MongoDB</text><text x=\"630\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">repository.save() · mall-port 库</text>\n      <line x1=\"158\" y1=\"90\" x2=\"214\" y2=\"48\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars4)\"/>\n      <line x1=\"158\" y1=\"112\" x2=\"214\" y2=\"152\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars4)\"/>\n      <line x1=\"436\" y1=\"44\" x2=\"506\" y2=\"88\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars4)\"/>\n      <line x1=\"436\" y1=\"156\" x2=\"506\" y2=\"116\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars4)\"/>\n      <text x=\"380\" y=\"200\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">MySQL 是数据源，MongoDB 是快照仓库；已删除商品(deleteStatus=1)直接不记</text>\n    </svg>\n    <figcaption>图 1 · 用户和商品的基础信息从 MySQL 查出回填，最终整条文档落 MongoDB。</figcaption>\n  </figure>\n  <p>查询侧同样简单：<code>list()</code> 拿当前会员 id，调那个方法名魔法接口分页倒序返回。配置在 <code>application.yml</code>：<code>spring.data.mongodb</code> 连 <code>mall-port</code> 库，<code>mongo.insert.sqlEnable: true</code> 控制要不要从 MySQL 回填。</p>\n  <div class=\"recap\"><b>收束：</b>方法名即查询；create 三步=查会员→回填商品→存文档；MySQL 供料，MongoDB 收货。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>快照的妙处：商品改价了，历史里还是当时的样子</h2>\n  <p>为什么要把商品名、价格、图片<b>复制一份</b>存进浏览记录，而不是只存个 productId、看的时候再查？因为浏览记录的语义是「你<b>当时</b>看到了什么」。你上周看到 6999 的手机，今天它涨到 7999 甚至下架了，历史记录里应该还是 6999——那是你当时犹豫过的价格。</p>\n  <p>这就是「MySQL 是数据源，MongoDB 是快照仓库」的含义：存的是<b>当时的商品名称、价格快照</b>。跟第一篇品牌改名要同步商品里的品牌名正好对照——那边选择「冗余+同步维护」，这边选择「冗余+故意不同步」，因为业务语义不同：<b>商品信息要最新，历史快照要定格</b>。冗余不是错，关键是想清楚这份副本要不要跟着变。</p>\n  <div class=\"key\"><span class=\"tag\">读源码时问自己</span>同样是把名称价格多存一份，为什么品牌表那边要连带更新，浏览记录这边却不动？答案不在技术，在业务语义。能答出这一问，才算真读懂了这两段源码。</div>\n  <div class=\"recap\"><b>收束：</b>快照定格当时的样子；冗余副本跟不跟着源数据变，由业务语义决定。</div>\n</section>\n\n<section id=\"e\">\n  <h2><span class=\"no\">第 5 步</span>选型口诀：什么进 MongoDB，什么必须留在 MySQL</h2>\n  <table>\n    <tr><th>数据</th><th>放哪</th><th>理由</th></tr>\n    <tr><td>浏览记录 / 收藏 / 关注 / 点击流</td><td>MongoDB</td><td>高写入、字段活、非强事务</td></tr>\n    <tr><td>订单 / 账户 / 库存</td><td>MySQL</td><td>必须强事务、强一致、关联查询</td></tr>\n    <tr><td>数据量小、字段固定的简单存取</td><td>MySQL 就够</td><td>别为了用而用</td></tr>\n    <tr><td>要长期保留的大量行为数据</td><td>MongoDB（不是 Redis）</td><td>Redis 是内存缓存，不能当持久仓库</td></tr>\n  </table>\n  <p>判断口诀：<b>高写入 + 字段灵活 + 非强事务 → MongoDB；要强事务 + 要关联查询 → MySQL。</b></p>\n  <div class=\"note\"><span class=\"tag\">本地三个坑</span>① MongoDB 没起，浏览/收藏/关注接口报 27017 连接失败，先 docker ps；② 容器互连写容器名 <code>mall-mongo</code>，别写 localhost；③ 以为 MongoDB 能替代 MySQL——订单账户必须留在关系型账本里。验证：<code>mongosh --eval \"db.runCommand({ping:1})\"</code> 返回 ok:1。</div>\n  <div class=\"recap\"><b>收束：</b>流水进 Mongo、交易留 MySQL、缓存归 Redis；三个存储各管一类数据，谁也别抢谁的活。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：账本分拣台、改价快照沙盒</h2>\n  <p>演练一把四种数据递给你，判断该进哪个本子。演练二模拟「浏览时 6999、后来涨到 7999」，看快照模式和实时模式各显示什么价格。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 这笔数据进哪个账本</b><span class=\"hint\">点按钮切换数据</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"history\" class=\"on\">浏览记录</button><button data-k=\"order\">订单扣款</button><button data-k=\"token\">登录 token 缓存</button><button data-k=\"log\">点击流日志</button></div></div>\n    <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>分拣理由</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">口诀：高写入+字段活+非强事务→Mongo；强事务+关联→MySQL；快取快用→Redis</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 改价快照沙盒</b><span class=\"hint\">拖改价滑杆，看历史记录里的价格变不变</span></div>\n    <div class=\"controls\">\n      <div class=\"ctl\"><label>浏览时价格</label><input type=\"range\" id=\"g1old\" min=\"1000\" max=\"9999\" step=\"100\" value=\"6999\"><span class=\"val\" id=\"g1oldV\">6999</span></div>\n      <div class=\"ctl\"><label>现价</label><input type=\"range\" id=\"g1new\" min=\"1000\" max=\"9999\" step=\"100\" value=\"7999\"><span class=\"val\" id=\"g1newV\">7999</span></div>\n      <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1sql\" checked> sqlEnable 回填快照</label></div>\n      <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1del\"> 商品已下架</label></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>写入与读取</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">模型依据 create()：sqlEnable 时回填名称价格；deleteStatus=1 不记录</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>存储选型看数据脾气；快照存的是「当时」，改价下架都动不了它——这正是产品想要的。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>六个问题</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。三个存储的分工你已经拿得住了。下一课看订单 30 分钟不付款怎么自动取消。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>速查表</h2>\n  <table>\n    <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n    <tr><td>文档型</td><td>一条数据一个 JSON</td><td>字段可变，不用建表定结构</td></tr>\n    <tr><td>行为数据三脾气</td><td>写得多、字段活、不怕丢一笔</td><td>高写入+灵活+非强事务</td></tr>\n    <tr><td>方法名魔法</td><td>findBy...OrderBy...Desc</td><td>Spring Data 自动翻译成查询</td></tr>\n    <tr><td>create 三步</td><td>查会员→回填商品→存文档</td><td>MySQL 供料，MongoDB 收货</td></tr>\n    <tr><td>快照</td><td>定格当时的名称价格</td><td>改价下架不影响历史</td></tr>\n    <tr><td>sqlEnable</td><td>要不要从 MySQL 回填</td><td>application.yml 配置</td></tr>\n    <tr><td>选型口诀</td><td>流水 Mongo，交易 MySQL</td><td>Redis 是缓存不能当仓库</td></tr>\n    <tr><td>MongoDB 事务</td><td>4.0 起支持但不擅长</td><td>支持≠擅长，核心交易别挪</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>源码行为依据本仓库 mall 的 mall-portal 模块；演练为模型模拟，非真实读写。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第四篇-MongoDB <span class=\"src\">— 本课重写底稿</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/</code>；编排 <code>mall-docker/docker-compose.yml</code> <span class=\"src\">— MongoDB 服务随编排启动</span></li>\n    </ul>\n    <h3>源码路标（相对 mall 工程根）</h3>\n    <ul>\n      <li><code>mall-portal/.../portal/repository/MemberReadHistoryRepository.java</code> <span class=\"src\">— 方法名生成查询</span></li>\n      <li><code>mall-portal/.../portal/service/impl/MemberReadHistoryServiceImpl.java</code> <span class=\"src\">— create 三步与 sqlEnable 回填</span></li>\n      <li><code>mall-portal/src/main/resources/application.yml</code> <span class=\"src\">— mongodb 连接与 mongo.insert.sqlEnable</span></li>\n    </ul>\n    <h3>官方文档</h3>\n    <ul>\n      <li><a href=\"https://www.mongodb.com/docs/manual/\" target=\"_blank\" rel=\"noopener\">MongoDB Manual</a> <span class=\"src\">— 文档模型、CRUD、事务边界</span></li>\n      <li><a href=\"https://docs.spring.io/spring-data/mongodb/reference/\" target=\"_blank\" rel=\"noopener\">Spring Data MongoDB Reference</a> <span class=\"src\">— Repository 与方法名查询规则</span></li>\n      <li><a href=\"https://github.com/macrozheng/mall\" target=\"_blank\" rel=\"noopener\">macrozheng/mall · GitHub</a> <span class=\"src\">— 上游项目</span></li>\n    </ul>\n    <h3>下一课要用</h3>\n    <ul>\n      <li><a href=\"https://www.rabbitmq.com/docs\" target=\"_blank\" rel=\"noopener\">RabbitMQ Documentation</a> <span class=\"src\">— S5 延迟队列主角</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"流水账的麻烦"},{"id":"b","title":"文档型数据库"},{"id":"c","title":"create 三步"},{"id":"d","title":"快照的语义"},{"id":"e","title":"选型口诀"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    history:{code:\"数据：浏览记录\\n写入：用户每点一下一条，一天千万级\\n字段：今天名称价格，明天想加停留时长\\n事务：写丢一条无所谓\\n→ 分拣：MongoDB\",log:[[\"ok\",\"高写入+字段活+非强事务，三条全中\"],[\"c\",\"// mall-portal 的 MemberReadHistory 正是这么存的\"],[\"warn\",\"别塞 MySQL：疯狂追加+频繁改表结构\"]]},\n    order:{code:\"数据：订单扣款\\n写入：相对低频，但每笔涉及钱\\n字段：结构稳定\\n事务：扣款+减库存必须一起成功或一起撤销\\n→ 分拣：MySQL\",log:[[\"err\",\"放 MongoDB？核心交易要强事务强一致\"],[\"ok\",\"MySQL：事务+关联查询是它的强项\"],[\"c\",\"// 支持事务≠擅长事务\"]]},\n    token:{code:\"数据：登录用户缓存/权限列表\\n读取：每次请求都读\\n寿命：可以过期，丢了能从库里重建\\n→ 分拣：Redis\",log:[[\"ok\",\"快取快用+可过期+可重建 → 缓存\"],[\"warn\",\"MongoDB/MySQL 都太慢，这是上一课的活\"],[\"c\",\"// 三个存储各管一类数据\"]]},\n    log:{code:\"数据：点击流日志\\n写入：比浏览记录更猛\\n字段：随埋点方案天天变\\n事务：不需要\\n→ 分拣：MongoDB（或专用日志系统）\",log:[[\"ok\",\"典型流水账，文档型正合适\"],[\"c\",\"// 字段随便加，不用 ALTER TABLE\"],[\"warn\",\"量再大就考虑专门日志/大数据管道\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById(\"e1code\").textContent=c.code;\n    document.getElementById(\"e1log\").innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"history\");\n})();\n\n(function(){\n  function calc(){\n    var oldP=parseInt(document.getElementById('g1old').value,10);\n    var newP=parseInt(document.getElementById('g1new').value,10);\n    var sql=document.getElementById('g1sql').checked;\n    var del=document.getElementById('g1del').checked;\n    document.getElementById('g1oldV').textContent=oldP;\n    document.getElementById('g1newV').textContent=newP;\n    var recorded=!del;\n    var shown=sql?oldP:'(只有 productId)';\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+newP+'</b><small>商品现价(MySQL)</small></div>'+\n      '<div class=\"stat-box '+(recorded?'good':'bad')+'\"><b>'+(recorded?shown:'未记录')+'</b><small>历史记录里显示</small></div>'+\n      '<div class=\"stat-box\"><b>'+(sql?'快照':'仅ID')+'</b><small>存储模式</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      (del?'<span class=\"chip bad\">deleteStatus=1：create 返回 0，不记录</span>':'<span class=\"chip on\">已写入 MongoDB</span>')+\n      (sql?'<span class=\"chip on\">改价不影响历史：定格 '+oldP+'</span>':'<span class=\"chip bad\">没回填：看历史还得回 MySQL 查，查到的是现价</span>')+\n      (oldP!==newP&&sql?'<span class=\"chip on\">差价 '+(newP-oldP)+' 正是「当时犹豫过的价格」</span>':'');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">语义</span>'+\n      (del?'已删除商品直接不记——create 里查不到或 deleteStatus=1 就 return 0。':(sql?'快照模式：历史里永远是你浏览那天的 '+oldP+'。商品涨到 '+newP+' 也动不了它，这是产品要的「当时的样子」。':'关掉 sqlEnable 只存 id：展示时回 MySQL 查，看到的是现价 '+newP+'，历史失真。两种模式各有用途，mall 默认开回填。'));\n    var log=[];\n    log.push('<div><span class=\"api\">create: 查会员 ✓ '+(sql?'回填商品(name/price='+oldP+') ✓':'跳过回填(sqlEnable=false)')+'</span></div>');\n    log.push(del?'<div><span class=\"err\">商品 deleteStatus=1 → return 0，不写 Mongo</span></div>':'<div><span class=\"ok\">repository.save() → MongoDB 文档已存</span></div>');\n    log.push('<div><span class=\"api\">后来 MySQL 改价：'+oldP+' → '+newP+'</span></div>');\n    log.push('<div><span class=\"'+(sql?'ok':'warn')+'\">读历史：'+(sql?'显示快照 '+oldP+'（不回填就显示现价 '+newP+'）':'只有 id，需回查 MySQL')+'</span></div>');\n    document.getElementById('g1log').innerHTML=log.join('');\n  }\n  ['g1old','g1new'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  ['g1sql','g1del'].forEach(function(id){document.getElementById(id).addEventListener('change',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 浏览记录为什么不适合 MySQL？\",\"opts\":[[\"写入极频繁、字段会变、不需要强事务\",true,\"对。三条全中。\"],[\"MySQL 不能存 JSON\",false,\"能存，但不是强项。\"],[\"浏览记录需要强事务\",false,\"写丢一条再记即可。\"]]},{\"q\":\"2. MongoDB 文档和 MySQL 行的核心区别？\",\"opts\":[[\"文档字段可以不一样，不用提前定结构\",true,\"对。加字段不改表。\"],[\"文档必须统一字段\",false,\"那是关系型。\"],[\"行比文档更灵活\",false,\"反了。\"]]},{\"q\":\"3. findByMemberIdOrderByCreateTimeDesc 为什么不用写查询语句？\",\"opts\":[[\"Spring Data 按方法名自动生成查询\",true,\"对。方法名魔法。\"],[\"MongoDB 不需要查询条件\",false,\"需要，框架生成了。\"],[\"这是 Java 语法特性\",false,\"是框架能力。\"]]},{\"q\":\"4. 浏览记录里存商品名称价格快照的意义？\",\"opts\":[[\"定格当时的样子，改价下架不影响历史\",true,\"对。快照语义。\"],[\"为了省磁盘\",false,\"反而多占空间。\"],[\"为了和商品表实时一致\",false,\"故意不同步。\"]]},{\"q\":\"5. 订单扣款数据该放哪？\",\"opts\":[[\"MySQL，要强事务强一致\",true,\"对。核心交易别挪。\"],[\"MongoDB，写入快\",false,\"强事务是硬需求。\"],[\"Redis，读取快\",false,\"缓存不能当账本。\"]]},{\"q\":\"6. MongoDB 4.0 起支持事务，说明？\",\"opts\":[[\"支持但开销大，核心交易仍建议 MySQL\",true,\"对。支持≠擅长。\"],[\"可以完全替代 MySQL\",false,\"不是为强事务设计。\"],[\"从此没有一致性顾虑\",false,\"边界仍在。\"]]}];" },
    "backend|java|RabbitMQ：订单超时怎么自动取消": { "body": "<p class=\"lead\">源码解读第五课：下单 60 分钟不付款，订单怎么自动取消？看懂消息队列这张「任务排单表」，拆开 mall 用死信队列 + TTL 变出的延迟魔法，对比定时任务全表扫描的笨办法，最后算一笔账：几百万订单时两种方案差多少。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">问题</span><span class=\"s\">谁盯着超时订单</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">认识</span><span class=\"s\">任务排单表</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">魔法</span><span class=\"s\">死信+TTL</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">对比</span><span class=\"s\">扫描 vs 闹钟</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">动手</span><span class=\"s\">演练与自测</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>奶茶店不会为一杯养生茶停止接单</h2>\n  <p>奶茶店来了一单要现泡 20 分钟的养生茶。店员不会站在灶台前干等 20 分钟、把后面的客人全晾着——前台记在<b>排单表</b>上，继续接单，泡好了再处理这一单。这就是「异步」：<b>发完就走，回头再干</b>。</p>\n  <p>商城下单也一样：记订单之外还要扣库存、发通知、算积分，有些活很慢，不该让用户等。更典型的是这个需求：<b>下单后 60 分钟不付款，自动取消、释放库存</b>。谁来盯着成千上万笔订单，看谁超时了？总得有个东西负责「到点提醒」。</p>\n  <p><span class=\"term\">RabbitMQ</span> 就是那张排单表——一个<b>消息队列</b>：把要做的事（消息）排好队，交给后台慢慢处理。几个名词用人话对齐：</p>\n  <table>\n    <tr><th>名词</th><th>人话</th></tr>\n    <tr><td>生产者 Producer</td><td>发消息的人 / 点单的顾客</td></tr>\n    <tr><td>消费者 Consumer</td><td>收消息干活的人 / 做奶茶的师傅</td></tr>\n    <tr><td>队列 Queue</td><td>排单表 / 任务清单</td></tr>\n    <tr><td>交换机 Exchange</td><td>收件台，把消息分到正确的队列</td></tr>\n    <tr><td>路由键 Routing Key</td><td>门牌号，告诉交换机往哪个队列送</td></tr>\n  </table>\n  <div class=\"recap\"><b>收束：</b>主线一条：生产者发消息 → 交换机分拣 → 队列排队 → 消费者取走干活；生产者发完就走。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>延迟的魔法：消息先躺 60 分钟，到点自动搬家</h2>\n  <p>mall 的延迟队列用<b>死信队列 + TTL</b> 实现。看 <code>RabbitMqConfig</code>：定义两个交换机、两个队列，关键在 <code>orderTtlQueue</code>：</p>\n  <pre>@Bean\npublic Queue orderTtlQueue() {\n    return QueueBuilder.durable(QUEUE_TTL_ORDER_CANCEL.getName())\n        // 消息过期后，转发到这个交换机（实际消费的交换机）\n        .withArgument(\"x-dead-letter-exchange\", QUEUE_ORDER_CANCEL.getExchange())\n        // 转发时用这个路由键\n        .withArgument(\"x-dead-letter-routing-key\", QUEUE_ORDER_CANCEL.getRouteKey())\n        .build();\n}</pre>\n  <p>普通队列里消息过期就没了；这个队列配了「死信转发」——消息到期<b>不消失，被转进另一个队列</b>。于是「延迟」变出来了：消息先在延迟队列里躺 60 分钟，到点自动搬进实际消费队列，消费者这才开始干活。</p>\n  <figure>\n    <svg viewBox=\"0 0 760 220\" role=\"img\" aria-label=\"延迟队列完整链路\">\n      <defs><marker id=\"ars5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"30\" width=\"150\" height=\"62\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"83\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">下单成功</text><text x=\"83\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">CancelOrderSender</text>\n      <rect x=\"196\" y=\"30\" width=\"190\" height=\"62\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"291\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">延迟队列 orderTtlQueue</text><text x=\"291\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">消息躺 60 分钟（TTL）</text>\n      <rect x=\"424\" y=\"30\" width=\"160\" height=\"62\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"504\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">实际消费队列</text><text x=\"504\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">mall.order.cancel</text>\n      <rect x=\"620\" y=\"30\" width=\"132\" height=\"62\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"686\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">消费者取消</text><text x=\"686\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">CancelOrderReceiver</text>\n      <line x1=\"158\" y1=\"61\" x2=\"194\" y2=\"61\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars5)\"/>\n      <line x1=\"386\" y1=\"61\" x2=\"422\" y2=\"61\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars5)\"/>\n      <line x1=\"584\" y1=\"61\" x2=\"618\" y2=\"61\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars5)\"/>\n      <text x=\"291\" y=\"112\" text-anchor=\"middle\" font-size=\"11\" fill=\"#B04A35\">到期 → x-dead-letter-exchange 转发</text>\n      <text x=\"83\" y=\"112\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1E7268\">发完立刻返回，用户不等</text>\n      <rect x=\"8\" y=\"136\" width=\"744\" height=\"60\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n      <text x=\"380\" y=\"160\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">消费者 handle(orderId)：只取消 status=0 未付款订单 → 释放库存锁定、退优惠券、返积分</text>\n      <text x=\"380\" y=\"182\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">已付款的订单查不出来，直接 return——60 分钟内付了款就什么都不发生。RabbitMQ 只送到门口，取消的活是业务代码干的。</text>\n    </svg>\n    <figcaption>图 1 · 每单自带闹钟：下单发消息设 TTL → 躺 60 分钟 → 死信转发 → 消费者精准处理这一单。</figcaption>\n  </figure>\n  <p>生产者 <code>CancelOrderSender.sendMessage()</code> 就干一件事：把订单 ID 扔进延迟队列、用 <code>setExpiration()</code> 设延迟毫秒数，然后就走。毫秒数不是写死的：<code>orderSetting.getNormalOrderOvertime() * 60 * 1000</code>，从订单设置读「普通订单超时分钟数」（默认 60）。消费者 <code>CancelOrderReceiver</code> 标 <code>@RabbitListener(queues = \"mall.order.cancel\")</code>，消息一到就调 <code>portalOrderService.cancelOrder(orderId)</code>。</p>\n  <div class=\"key\"><span class=\"tag\">关键认知</span>RabbitMQ 全程没干任何「取消订单」的活，它只负责<b>到点把消息送到消费者门口</b>。真正取消订单、释放库存的是消费者里的业务方法。队列管送信，不管办事。</div>\n  <div class=\"recap\"><b>收束：</b>死信+TTL=延迟；生产者设闹钟就走，消费者到点办事；已付款的订单天然不会被取消。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>是推送不是轮询：你来我才动</h2>\n  <p>你可能以为 <code>@RabbitListener</code> 是每秒去队列问一次「有消息吗」。<b>不是轮询，是推送。</b>Spring 在后台开一个监听线程，RabbitMQ 一有消息就通过长连接<b>主动推</b>过来；没消息时监听线程睡着，几乎不耗资源。</p>\n  <p>轮询是「我每秒主动问一次，白耗 CPU」；推送是「你来我才动」。这也是为什么几百万个「闹钟」挂在队列上并不费应用服务器的力气——躺着的是消息，不是线程。</p>\n  <div class=\"recap\"><b>收束：</b>长连接推送，没消息就睡；别把监听器想成定时器。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>为什么不用定时任务：地毯式扫查 vs 每单自带闹钟</h2>\n  <p>直觉方案：写个定时任务，每 10 分钟扫一遍订单表，找「超时未付款」的取消掉。两个问题：</p>\n  <ul>\n    <li><b>全表扫描越来越慢</b>：几百万订单每 10 分钟扫一遍，SQL 慢、费数据库，订单越多越慢。</li>\n    <li><b>勤和准矛盾</b>：扫得勤数据库累；扫得懒取消不及时——间隔 10 分钟时，一笔订单可能 60~70 分钟之间才被取消。</li>\n  </ul>\n  <p>延迟队列是「每单下单时定一个 60 分钟闹钟」，到点精准处理这一单，不扫全表。订单再多，也是各响各的闹钟。<b>把扫描这种体力活，变成每个任务自带定时的精准活</b>，这是延迟队列的核心价值。</p>\n  <div class=\"note\"><span class=\"tag\">可靠投递三件套（面试必问）</span>生产者 confirm 确认 + 消息持久化到磁盘 + 消费者 ack 兜底。mall 用 Spring 默认的 AUTO 模式：监听方法正常跑完才 ack，处理到一半挂了消息重新入队，恢复后继续；要更细的控制可改手动 ack。重复消费靠<b>幂等</b>：按订单号判断已处理就跳过——mall 的 cancelOrder 只查 status=0 的订单，天然挡掉了重复取消。</div>\n  <div class=\"recap\"><b>收束：</b>扫描找超时 vs 闹钟自报到；confirm+持久化+处理完才 ack 保不丢，幂等保不重。</div>\n</section>\n\n<section id=\"e\">\n  <h2><span class=\"no\">第 5 步</span>选型边界：AI 聊天为什么偏偏不能用它</h2>\n  <p>判断口诀：<b>快、少、可丢、不拆 → 直接调；慢、多、不可丢、要拆 → 用队列。</b>发短信、算积分、秒杀削峰、超时取消都适合；又快又少丢了无所谓的活，别为「用上新技术」加一层队列。</p>\n  <p>最有意思的是反例：AI 聊天调大模型也很慢，为什么不能走队列？因为用户要<b>实时看过程</b>——打字机效果，边生成边看。RabbitMQ 是「发完再取」，走队列用户要干等 20 秒屏幕空白，然后一次性蹦出一大段，体验崩了。AI 聊天用 <span class=\"term2\">SSE</span>（服务器推送）+ 异步线程：建长连接，每生成一个字就推给前端。</p>\n  <div class=\"key\"><span class=\"tag\">一句话判断</span>用户要看过程 → SSE；用户只看结果 → RabbitMQ。异步不等于都要进队列。</div>\n  <div class=\"note\"><span class=\"tag\">本地三个坑</span>① RabbitMQ 没起，订单永远不自动取消——管理界面 <code>http://localhost:15672</code>（mall/mall）能打开才算起好；② 只发消息没写消费者，消息永远躺在队列里，业务根本不执行；③ 死信参数配错，消息到期直接丢，不会转进实际队列。</div>\n  <div class=\"recap\"><b>收束：</b>慢多不可丢要拆才上队列；看过程用 SSE 看结果用 MQ；排错先查服务、消费者、死信配置。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：三种方案对照、扫描成本沙盒</h2>\n  <p>演练一对比定时任务、延迟队列、以及「AI 聊天走队列」这个错误示范。演练二拖订单量和扫描间隔，算算定时任务每天要白扫多少行、取消最多迟多久。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 同一件事三种做法</b><span class=\"hint\">点按钮切换方案</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"cron\" class=\"on\">定时任务扫表</button><button data-k=\"mq\">延迟队列</button><button data-k=\"chat\">AI 聊天走队列？</button></div></div>\n    <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>方案评估</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">第三个是反面教材：异步≠都要进队列</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 扫描成本沙盒</b><span class=\"hint\">拖滑杆，看定时任务的账</span></div>\n    <div class=\"controls\">\n      <div class=\"ctl\"><label>订单总量(万)</label><input type=\"range\" id=\"g1orders\" min=\"1\" max=\"500\" value=\"100\"><span class=\"val\" id=\"g1ordersV\">100</span></div>\n      <div class=\"ctl\"><label>扫描间隔(分)</label><input type=\"range\" id=\"g1gap\" min=\"1\" max=\"60\" value=\"10\"><span class=\"val\" id=\"g1gapV\">10</span></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>算账过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">模型：每次扫描过一遍全表；延迟队列每单一条消息，到点精准触发</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>定时任务的成本随订单量线性涨，延迟队列的成本随「真正超时的单」走；及时性一个靠扫得勤，一个天然精准。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>六个问题</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。排单表和闹钟你已经玩明白了。下一课看商品搜索为什么快。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>速查表</h2>\n  <table>\n    <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n    <tr><td>消息队列</td><td>任务排单表</td><td>异步解耦：发完就走回头再干</td></tr>\n    <tr><td>五名词</td><td>点单/师傅/排单表/收件台/门牌</td><td>Producer/Consumer/Queue/Exchange/RoutingKey</td></tr>\n    <tr><td>死信+TTL</td><td>躺够时间自动搬家</td><td>x-dead-letter-exchange 转发实现延迟</td></tr>\n    <tr><td>每单自带闹钟</td><td>到点精准处理这一单</td><td>对比定时任务全表扫描</td></tr>\n    <tr><td>推送非轮询</td><td>你来我才动</td><td>长连接主动推，没消息就睡</td></tr>\n    <tr><td>可靠投递</td><td>confirm+持久化+处理完才 ack</td><td>消费者挂了消息还在队列</td></tr>\n    <tr><td>幂等</td><td>处理过就跳过</td><td>cancelOrder 只查 status=0</td></tr>\n    <tr><td>SSE vs MQ</td><td>看过程 vs 看结果</td><td>AI 聊天要打字机效果，不能走队列</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>链路依据本仓库 mall 的 RabbitMqConfig/CancelOrderSender/CancelOrderReceiver 与 cancelOrder 实现；扫描成本为模型估算，非实测。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第五篇-RabbitMQ <span class=\"src\">— 本课重写底稿</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/</code>；编排 <code>mall-docker/docker-compose.yml</code> <span class=\"src\">— RabbitMQ 服务随编排启动</span></li>\n    </ul>\n    <h3>源码路标（相对 mall 工程根）</h3>\n    <ul>\n      <li><code>mall-portal/.../config/RabbitMqConfig.java</code> <span class=\"src\">— 两交换机两队列与死信参数</span></li>\n      <li><code>mall-portal/.../component/CancelOrderSender.java</code>、<code>CancelOrderReceiver.java</code> <span class=\"src\">— 发延迟消息 / 监听取消</span></li>\n      <li><code>mall-portal/.../service/impl/OmsPortalOrderServiceImpl.java</code> <span class=\"src\">— cancelOrder：status=0 才取消，释放库存/退券/返积分</span></li>\n    </ul>\n    <h3>官方文档</h3>\n    <ul>\n      <li><a href=\"https://www.rabbitmq.com/docs/dlx\" target=\"_blank\" rel=\"noopener\">RabbitMQ · Dead Letter Exchanges</a> <span class=\"src\">— 死信转发机制</span></li>\n      <li><a href=\"https://www.rabbitmq.com/docs/confirms\" target=\"_blank\" rel=\"noopener\">RabbitMQ · Publisher Confirms and Consumer Acknowledgements</a> <span class=\"src\">— 可靠投递</span></li>\n      <li><a href=\"https://docs.spring.io/spring-amqp/reference/\" target=\"_blank\" rel=\"noopener\">Spring AMQP Reference</a> <span class=\"src\">— @RabbitListener 与推送模型</span></li>\n    </ul>\n    <h3>下一课要用</h3>\n    <ul>\n      <li><a href=\"https://www.elastic.co/docs\" target=\"_blank\" rel=\"noopener\">Elasticsearch Docs</a> <span class=\"src\">— S6 商品搜索主角</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"奶茶店排单表"},{"id":"b","title":"死信+TTL 魔法"},{"id":"c","title":"推送非轮询"},{"id":"d","title":"扫描 vs 闹钟"},{"id":"e","title":"边界与 AI 反例"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    cron:{code:\"@Scheduled(cron = \\\"0 */10 * * * ?\\\")\\n// 每 10 分钟：\\nSELECT * FROM oms_order\\nWHERE status=0 AND create_time < now()-60min\\n→ 全表扫一遍，找出超时的批量取消\",log:[[\"warn\",\"几百万订单每 10 分钟扫一遍，越来越慢\"],[\"warn\",\"取消时间落在 60~70 分钟之间，不精准\"],[\"err\",\"扫得勤 DB 累，扫得懒不及时——两头堵\"]]},\n    mq:{code:\"下单 → sender.sendMessage(orderId, 超时分钟*60*1000)\\n// 超时分钟读订单设置，默认 60\\n// 消息在 orderTtlQueue 躺 60 分钟\\n// 到期死信转发 → mall.order.cancel\\n@RabbitListener → cancelOrder(orderId)\\n// 只取消 status=0，已付款直接 return\",log:[[\"ok\",\"每单自带闹钟，到点精准处理这一单\"],[\"ok\",\"不扫全表，订单再多各响各的\"],[\"c\",\"// 队列只送信，取消的活是业务代码干的\"]]},\n    chat:{code:\"❌ 用户发消息 → 扔进 RabbitMQ → 等消费者调模型\\n// 用户盯着空白屏幕 20 秒……\\n// 然后一次性蹦出一大段文字\\n✅ 应该：SSE 长连接，每生成一个字就推\",log:[[\"err\",\"用户要看过程，队列是发完再取——体验崩了\"],[\"ok\",\"判断：看过程→SSE；看结果→MQ\"],[\"c\",\"// 慢任务≠都进队列\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById(\"e1code\").textContent=c.code;\n    document.getElementById(\"e1log\").innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"cron\");\n})();\n\n(function(){\n  function calc(){\n    var orders=parseInt(document.getElementById('g1orders').value,10);\n    var gap=parseInt(document.getElementById('g1gap').value,10);\n    document.getElementById('g1ordersV').textContent=orders;\n    document.getElementById('g1gapV').textContent=gap;\n    var rows=orders*10000;\n    var scansPerDay=1440/gap;\n    var rowsPerDay=rows*scansPerDay;\n    function fmt(n){\n      if(n>=1e8)return (n/1e8).toFixed(1)+' 亿';\n      if(n>=1e4)return (n/1e4).toFixed(0)+' 万';\n      return String(Math.round(n));\n    }\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box bad\"><b>'+fmt(rowsPerDay)+'</b><small>定时任务每天扫描行数</small></div>'+\n      '<div class=\"stat-box bad\"><b>最多 '+gap+' 分</b><small>取消额外延迟</small></div>'+\n      '<div class=\"stat-box good\"><b>'+fmt(rows)+'</b><small>延迟队列消息数(每单一条)</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip bad\">每天扫 '+Math.round(scansPerDay)+' 遍全表</span>'+\n      '<span class=\"chip on\">延迟队列：0 次全表扫描</span>'+\n      (gap<=5?'<span class=\"chip bad\">扫太勤：DB 压力 ×'+Math.round(scansPerDay)+'</span>':'')+\n      (gap>=30?'<span class=\"chip bad\">扫太懒：最多迟 '+gap+' 分钟才取消</span>':'');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">算账</span>'+\n      '定时任务每天白扫 '+fmt(rowsPerDay)+' 行，其中绝大多数订单根本不需要处理；延迟队列只在「真正到期」时动一次。订单量涨十倍，前者成本涨十倍，后者不变。';\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">全表行数 = '+orders+' 万 = '+fmt(rows)+'</span></div>',\n      '<div><span class=\"api\">每天扫描次数 = 1440 分 ÷ '+gap+' 分 = '+Math.round(scansPerDay)+'</span></div>',\n      '<div><span class=\"err\">每天扫描行数 = '+fmt(rows)+' × '+Math.round(scansPerDay)+' = '+fmt(rowsPerDay)+'</span></div>',\n      '<div><span class=\"ok\">延迟队列：'+fmt(rows)+' 条消息各躺 60 分钟，到点各处理一次</span></div>',\n      '<div><span class=\"c\">// 及时性：定时最多迟 '+gap+' 分；延迟队列到点即触发</span></div>'\n    ].join('');\n  }\n  ['g1orders','g1gap'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 消息队列的核心价值「异步」指？\",\"opts\":[[\"生产者发完就走，消费者后台处理\",true,\"对。发完就走回头再干。\"],[\"所有任务同时执行\",false,\"那是并行。\"],[\"消息立即被处理\",false,\"排队慢慢处理。\"]]},{\"q\":\"2. mall 的延迟队列怎么实现？\",\"opts\":[[\"死信队列+TTL，到期转发到实际消费队列\",true,\"对。x-dead-letter-exchange。\"],[\"定时器每秒查队列\",false,\"那是轮询思路。\"],[\"消息设个未来时间戳自动执行\",false,\"靠过期转发实现。\"]]},{\"q\":\"3. 订单超时为什么不用定时任务扫表？\",\"opts\":[[\"全表扫描随订单量变慢，且间隔与及时性矛盾\",true,\"对。每单自带闹钟更精准。\"],[\"定时任务写不出来\",false,\"写得出来，是成本问题。\"],[\"RabbitMQ 比定时器新\",false,\"新旧不是理由。\"]]},{\"q\":\"4. @RabbitListener 的工作方式？\",\"opts\":[[\"长连接推送，有消息 RabbitMQ 主动推\",true,\"对。没消息就睡。\"],[\"每秒轮询队列一次\",false,\"不是轮询。\"],[\"用户请求时才检查\",false,\"后台监听线程。\"]]},{\"q\":\"5. 消费者处理到一半挂了，消息会丢吗？\",\"opts\":[[\"不会，处理完才 ack，消息还在队列\",true,\"对。恢复后继续处理。\"],[\"会，取走就删\",false,\"处理完才 ack，不是取走就删。\"],[\"看运气\",false,\"机制保障。\"]]},{\"q\":\"6. AI 聊天为什么不能走 RabbitMQ？\",\"opts\":[[\"用户要实时看生成过程，应使用 SSE 推送\",true,\"对。看过程 SSE，看结果 MQ。\"],[\"模型不支持队列\",false,\"与模型无关。\"],[\"队列太慢\",false,\"是交互模式不匹配。\"]]}];" },
    "backend|java|Elasticsearch：商品搜索为什么快": { "body": "<p class=\"lead\">源码解读第六课：百万商品里搜「手机」，MySQL 要一条条翻，ES 为什么毫秒出结果？看懂倒排索引和中文分词，逐层拆 mall-search 的加权搜索、聚合筛选栏和猜你喜欢，最后揭开一个很多人没注意的真相——原版 mall 前端默认没接 ES，而本仓库已经把它接上了。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">问题</span><span class=\"s\">LIKE 全表扫</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">原理</span><span class=\"s\">倒排+分词</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">源码</span><span class=\"s\">模型与灌数据</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">重头戏</span><span class=\"s\">加权+聚合</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">真相</span><span class=\"s\">原版没接·本仓已接</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>图书馆找一本书，不该从第一个书架翻起</h2>\n  <p>百万册的图书馆里找讲「手机」的书。笨办法是从第一个书架一本本翻书名——商城数据库就是这么干的：</p>\n  <pre>SELECT * FROM product WHERE name LIKE '%手机%';</pre>\n  <p>数据少时没问题；几十万、几百万条时，<code>LIKE '%手机%'</code> 这种前后都带通配符的模糊查询<b>索引失效，只能全表扫描</b>，越来越慢。还想按品牌筛、按价格排、按相关度排？SQL 越写越难，性能越来越差。</p>\n  <p>图书馆的聪明办法是<b>检索卡片柜</b>：按关键词建卡，「手机」这张卡上直接写着哪几本书。<span class=\"term\">Elasticsearch</span>（ES）就是这个卡片柜——专为全文搜索设计的引擎，几百万条数据毫秒级返回。</p>\n  <table>\n    <tr><th></th><th>MySQL</th><th>Elasticsearch</th></tr>\n    <tr><td>索引方式</td><td>B+树（精确、范围）</td><td>倒排索引（全文）</td></tr>\n    <tr><td>搜「手机」</td><td>LIKE 全表扫</td><td>查倒排索引秒出</td></tr>\n    <tr><td>适合</td><td>精确查询、事务</td><td>全文搜索、相关度排序、聚合</td></tr>\n  </table>\n  <div class=\"recap\"><b>收束：</b>LIKE 是逐架翻书，倒排索引是卡片柜直查；海量全文搜索是 ES 的主场。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>倒排索引：把「文档→词」反过来记成「词→文档」</h2>\n  <figure>\n    <svg viewBox=\"0 0 760 210\" role=\"img\" aria-label=\"正排与倒排索引对比\">\n      <defs><marker id=\"ars6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <text x=\"8\" y=\"22\" font-size=\"12\" fill=\"#7C7166\">正排：文档 → 词（存的时候这样）</text>\n      <rect x=\"8\" y=\"34\" width=\"240\" height=\"44\" rx=\"8\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"128\" y=\"61\" text-anchor=\"middle\" font-size=\"12\" fill=\"#2F58A8\">文档1：苹果手机便宜</text>\n      <rect x=\"8\" y=\"90\" width=\"240\" height=\"44\" rx=\"8\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"128\" y=\"117\" text-anchor=\"middle\" font-size=\"12\" fill=\"#2F58A8\">文档2：华为手机贵</text>\n      <text x=\"400\" y=\"22\" font-size=\"12\" fill=\"#7C7166\">倒排：词 → 文档（搜的时候查这个）</text>\n      <rect x=\"400\" y=\"34\" width=\"120\" height=\"40\" rx=\"8\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"460\" y=\"59\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">苹果</text>\n      <rect x=\"400\" y=\"84\" width=\"120\" height=\"40\" rx=\"8\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"460\" y=\"109\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">手机</text>\n      <rect x=\"400\" y=\"134\" width=\"120\" height=\"40\" rx=\"8\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"460\" y=\"159\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">华为</text>\n      <rect x=\"580\" y=\"34\" width=\"160\" height=\"40\" rx=\"8\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"660\" y=\"59\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">→ 文档1</text>\n      <rect x=\"580\" y=\"84\" width=\"160\" height=\"40\" rx=\"8\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"660\" y=\"109\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">→ 文档1, 文档2</text>\n      <rect x=\"580\" y=\"134\" width=\"160\" height=\"40\" rx=\"8\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"660\" y=\"159\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">→ 文档2</text>\n      <line x1=\"520\" y1=\"54\" x2=\"578\" y2=\"54\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars6)\"/>\n      <line x1=\"520\" y1=\"104\" x2=\"578\" y2=\"104\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars6)\"/>\n      <line x1=\"520\" y1=\"154\" x2=\"578\" y2=\"154\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars6)\"/>\n      <text x=\"380\" y=\"196\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">搜「手机」直接命中两张卡，不用把百万条全扫一遍</text>\n    </svg>\n    <figcaption>图 1 · 倒排索引提前把「关键词→文档」映射建好，搜索时按词取卡。</figcaption>\n  </figure>\n  <p>还有个中文专属的坑：ES 处理英文按空格分词天然可行，中文「苹果手机」是一个整体，它不知道怎么拆。必须配<b>中文分词插件</b>，mall 用的是 <span class=\"term\">ik_max_word</span>。本地部署最大的坑就在这：ES 没装 ik，mall-search 一启动就报 <code>analyzer [ik_max_word] has not been configured</code>，而且插件版本必须和 ES 版本一致。</p>\n  <div class=\"recap\"><b>收束：</b>倒排=词到文档的卡片柜；中文要 ik 分词，版本必须对齐。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>mall-search 源码：模型是钥匙，数据从 MySQL 灌</h2>\n  <p>搜索被抽成独立模块 <code>mall-search</code>：有自己的启动类和 8081 端口，依赖 mbg（还排除了 redis starter，第一课见过的「退赠品」）和 ES 官方 starter。<code>scanBasePackages = \"com.macro.mall\"</code> 扫整包，才能用到 mbg 的 Mapper。</p>\n  <p>理解整个模块的钥匙是 <code>EsProduct</code> 模型的字段注解：</p>\n  <table>\n    <tr><th>注解</th><th>含义</th><th>用在哪</th></tr>\n    <tr><td><code>@Document(indexName=\"pms\")</code></td><td>对应 ES 的一个索引</td><td>相当于 MySQL 的「表」</td></tr>\n    <tr><td><code>@Field(type=Keyword)</code></td><td>不分词的精确字段</td><td>brandName/分类名 → term 筛选</td></tr>\n    <tr><td><code>@Field(analyzer=\"ik_max_word\", type=Text)</code></td><td>中文分词的全文字段</td><td>name/subTitle/keywords → match 搜索</td></tr>\n    <tr><td><code>@Field(type=Nested)</code></td><td>嵌套对象</td><td>attrValueList 商品属性 → 聚合</td></tr>\n  </table>\n  <p><b>全文搜索用 Text，精确筛选用 Keyword</b>——这一行分界决定了后面怎么搜、怎么筛。</p>\n  <p>ES 里的数据从哪来？从 MySQL 灌。<code>EsProductDao.xml</code> 一条多表联查，把商品、属性值、属性<b>三张表 JOIN 成一条大而全的搜索文档</b>，再由 <code>importAll()</code> 调 <code>repository.saveAll()</code> 批量写进 ES：</p>\n  <figure>\n    <svg viewBox=\"0 0 760 170\" role=\"img\" aria-label=\"MySQL 三表 JOIN 灌入 ES 一份文档\">\n      <defs><marker id=\"ars6c\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"20\" width=\"180\" height=\"40\" rx=\"8\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"98\" y=\"45\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8A5510\">pms_product 商品</text>\n      <rect x=\"8\" y=\"66\" width=\"180\" height=\"40\" rx=\"8\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"98\" y=\"91\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8A5510\">pms_product_attribute_value</text>\n      <rect x=\"8\" y=\"112\" width=\"180\" height=\"40\" rx=\"8\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"98\" y=\"137\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8A5510\">pms_product_attribute</text>\n      <rect x=\"256\" y=\"52\" width=\"180\" height=\"68\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"346\" y=\"80\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">EsProductDao JOIN</text><text x=\"346\" y=\"100\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">只取上架且未删除的</text>\n      <rect x=\"508\" y=\"52\" width=\"244\" height=\"68\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"630\" y=\"80\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">ES pms 索引：一条文档</text><text x=\"630\" y=\"100\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">saveAll 批量写入</text>\n      <line x1=\"188\" y1=\"40\" x2=\"254\" y2=\"72\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars6c)\"/>\n      <line x1=\"188\" y1=\"86\" x2=\"254\" y2=\"86\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars6c)\"/>\n      <line x1=\"188\" y1=\"132\" x2=\"254\" y2=\"100\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars6c)\"/>\n      <line x1=\"436\" y1=\"86\" x2=\"506\" y2=\"86\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars6c)\"/>\n      <text x=\"380\" y=\"158\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">MySQL 拆表防冗余（范式），ES 拼一份图快（反范式）——设计目标不同，取舍就不同</text>\n    </svg>\n    <figcaption>图 2 · MySQL 是数据源，ES 是搜索索引；importAll/create/delete 负责双写同步。</figcaption>\n  </figure>\n  <div class=\"recap\"><b>收束：</b>Text 搜、Keyword 筛、Nested 聚合；三表 JOIN 成一份文档灌进 ES，商品下架 ES 也要删。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>生产级搜索的重头戏：加权、筛选、聚合、推荐</h2>\n  <p><code>EsProductServiceImpl</code> 有两套搜索。简单版用 Repository 方法名 <code>findByNameOrSubTitleOrKeywords</code>，够用但不专业。综合版手写 <code>NativeQuery</code>，才是生产级搜索的精髓：</p>\n  <ul>\n    <li><b>筛选用 term + bool.must</b>：品牌、分类是精确匹配，走 Keyword 字段，不走全文。</li>\n    <li><b>加权打分 function_score</b>：商品名命中权重 <b>10</b>、副标题 <b>5</b>、关键词 <b>2</b>，Sum 求和，minScore=2 兜底。名字里带「手机」的商品，就该排在副标题里带的前面——这是「搜索排序为什么更合理」的核心。</li>\n    <li><b>四种排序</b>：新品（id 倒序）、销量、价格升/降，默认相关度 _score。</li>\n  </ul>\n  <pre>// 加权核心（简化）\nfunctions: [\n  match(name)     → weight 10,\n  match(subTitle) → weight 5,\n  match(keywords) → weight 2\n], scoreMode: Sum, minScore: 2</pre>\n  <p>搜索结果页左侧的品牌/分类/属性筛选栏也不是写死的：<code>searchRelatedInfo()</code> 对当前关键词的结果做 <span class=\"term\">Aggregation 聚合</span>——terms 聚合按字段分组统计出「有哪些品牌、哪些分类」，商品属性是嵌套对象，要用 nested 聚合。「猜你喜欢」则是 <code>recommend()</code>：拿当前商品的名称/品牌/分类做加权搜索找相似，mustNot 排除自己。</p>\n  <div class=\"key\"><span class=\"tag\">一句话分清</span>SQL 很难写「名称命中排最前」的相关度，也数不清结果里有几个品牌；ES 的 function_score 和 Aggregation 各一步搞定。这两样就是「搜索引擎思维」和「数据库思维」的分水岭。</div>\n  <div class=\"recap\"><b>收束：</b>term 筛、加权排、聚合出筛选栏、加权找相似；综合搜索才是该抄的那套。</div>\n</section>\n\n<section id=\"e\">\n  <h2><span class=\"no\">第 5 步</span>隐藏真相：原版没接 ES，本仓库把它接上了</h2>\n  <p>这门课最值钱的一个发现：<b>原版 mall</b> 里你在商城搜「手机」，走的其实不是 ES。翻前后端源码可以看到：</p>\n  <table>\n    <tr><th>环节</th><th>走哪套</th><th>证据</th></tr>\n    <tr><td>原版前台搜索</td><td><code>GET /product/search</code> → MySQL LIKE</td><td>原版前端 apis/product.ts 调它；后端 <code>andNameLike(\"%\"+keyword+\"%\")</code></td></tr>\n    <tr><td>mall-search ES 搜索</td><td><code>GET /esProduct/search</code> → ES</td><td>加权/聚合/推荐完整实现，但原版没有前端页面调用</td></tr>\n  </table>\n  <p>ES 能力做得很专业，在原版里却处于「已就绪、未启用」状态。这在实际项目里很常见：通用能力先沉淀成模块，当前版本用简单方案满足需求。<b>读源码要读到「谁在调用它」这一层</b>，只看模块存在就断言「商城搜索用了 ES」，是没读完整。</p>\n  <p><b>本仓库已经完成了这一步改造</b>（底稿 §4.4 留的实操作业）：前端 <code>apis/product.ts</code> 的搜索改调 <code>ES_SEARCH_BASE_URL = http://localhost:8060/esProduct</code>，返回类型换成 <code>CommonPage&lt;EsProduct&gt;</code>；nginx 网关把 <code>/esProduct/</code> 反代到 <code>mall-search:8081</code>。浏览器只跟 8060 同源通信，不直连后端端口，跨域和端口暴露一起解决——这是生产级网关做法。所以现在这套源码里搜「手机」，<b>真的走 ES</b>。</p>\n  <pre>// 本仓库前端（apis/product.ts，已改造）\nconst ES_SEARCH_BASE_URL = 'http://localhost:8060/esProduct'\nurl: `${ES_SEARCH_BASE_URL}/search`   // → nginx → mall-search:8081 → ES\n\n// nginx-app-web.conf（网关反代）\nlocation /esProduct/ { proxy_pass http://mall-search:8081; }</pre>\n  <div class=\"note\"><span class=\"tag\">选型与部署</span>要全文搜索+相关度+聚合+海量数据 → ES；几千条简单查询 → MySQL 索引就够，别上重武器；订单账户等交易数据永远归 MySQL，ES 不保证事务。部署四个坑：ik 没装或版本不对、ES 内存不足（设 ES_JAVA_OPTS）、起了 ES 没执行 importAll 搜索为空、ik 版本必须与 ES 一致。</div>\n  <div class=\"recap\"><b>收束：</b>判断用没用某技术，要顺着调用链找到调用方；原版 ES 就绪未接线，本仓库已接上；ES 是索引不是账本，数据少别硬上。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：链路对照、加权排序沙盒</h2>\n  <p>演练一看四条真实链路：原版前端走的、本仓库改造后走的、ES 搜索内部、数据怎么灌。演练二亲手调三个字段权重，看四件商品的得分和排名怎么变——这就是 function_score 的手感。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 搜「手机」到底走哪条路</b><span class=\"hint\">点按钮切换链路</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"front\" class=\"on\">原版前端链路</button><button data-k=\"repo\">本仓库现行链路</button><button data-k=\"es\">ES 搜索内部</button><button data-k=\"import\">数据灌入链路</button></div></div>\n    <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>链路日志</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">读到「谁在调用」这一层，才算读完源码</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 加权排序沙盒</b><span class=\"hint\">拖权重滑杆，看排名怎么变</span></div>\n    <div class=\"controls\">\n      <div class=\"ctl\"><label>name 权重</label><input type=\"range\" id=\"g1wn\" min=\"1\" max=\"10\" value=\"10\"><span class=\"val\" id=\"g1wnV\">10</span></div>\n      <div class=\"ctl\"><label>subTitle 权重</label><input type=\"range\" id=\"g1ws\" min=\"1\" max=\"10\" value=\"5\"><span class=\"val\" id=\"g1wsV\">5</span></div>\n      <div class=\"ctl\"><label>keywords 权重</label><input type=\"range\" id=\"g1wk\" min=\"1\" max=\"10\" value=\"2\"><span class=\"val\" id=\"g1wkV\">2</span></div>\n      <div class=\"seg\" id=\"g1sort\"><button data-k=\"score\" class=\"on\">相关度</button><button data-k=\"sale\">销量</button><button data-k=\"price\">价格↑</button></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>打分与排序</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">四件商品：A 名称命中 / B 副标题命中 / C 关键词命中 / D 无命中；minScore=2 过滤</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>权重就是产品意志：名字命中最值钱是默认，调低它排序立刻变脸；minScore 把蹭边的商品挡在门外。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>六个问题</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经能看穿「模块存在≠功能在用」。下一课看图片为什么单独存 MinIO。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>速查表</h2>\n  <table>\n    <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n    <tr><td>倒排索引</td><td>关键词卡片柜</td><td>词→文档；LIKE %x% 全表扫</td></tr>\n    <tr><td>ik_max_word</td><td>中文分词插件</td><td>版本必须与 ES 一致</td></tr>\n    <tr><td>Text vs Keyword</td><td>搜的 vs 筛的</td><td>match 用 Text，term 用 Keyword</td></tr>\n    <tr><td>反范式文档</td><td>三表 JOIN 拼一份</td><td>MySQL 拆表防冗余，ES 拼图快</td></tr>\n    <tr><td>function_score</td><td>命中字段不同分不同</td><td>name10/subTitle5/keywords2，Sum</td></tr>\n    <tr><td>Aggregation</td><td>结果分组统计</td><td>terms 出品牌分类，nested 出属性</td></tr>\n    <tr><td>recommend</td><td>拿自己找相似</td><td>加权搜索+mustNot 排除自己</td></tr>\n    <tr><td>隐藏真相</td><td>原版前端走 MySQL LIKE</td><td>就绪未启用是原版；本仓库已经 nginx 接上 ES</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>链路与权重依据本仓库 mall-search 源码、mall-app-web 前端调用与 mall-docker/nginx-app-web.conf；演练为打分模型模拟，非真实 ES 查询。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第六篇-Elasticsearch <span class=\"src\">— 本课重写底稿；其「前端未接入」指原版 mall，本仓库已按其 §4.4 思路完成接入</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/mall-search/</code>、前端 <code>code/source-reading/java/mall/mall-app-web/</code> <span class=\"src\">— 均在本地</span></li>\n    </ul>\n    <h3>源码路标</h3>\n    <ul>\n      <li><code>mall-search/.../domain/EsProduct.java</code> <span class=\"src\">— Text/Keyword/Nested 字段注解</span></li>\n      <li><code>mall-search/.../service/impl/EsProductServiceImpl.java</code> <span class=\"src\">— importAll/加权搜索/聚合/推荐</span></li>\n      <li><code>mall-search/src/main/resources/dao/EsProductDao.xml</code> <span class=\"src\">— 三表 JOIN 灌数据 SQL</span></li>\n      <li><code>mall-app-web/src/apis/product.ts</code> <span class=\"src\">— 本仓库已改走 8060 网关调 /esProduct/search 的证据</span></li>\n      <li><code>mall-docker/nginx-app-web.conf</code> <span class=\"src\">— location /esProduct/ 反代 mall-search:8081</span></li>\n      <li><code>mall-portal/.../PmsPortalProductServiceImpl.java</code> <span class=\"src\">— 原版 /product/search 的 MySQL LIKE，接口仍保留</span></li>\n    </ul>\n    <h3>官方文档</h3>\n    <ul>\n      <li><a href=\"https://www.elastic.co/docs/solutions/search\" target=\"_blank\" rel=\"noopener\">Elasticsearch · Search solutions</a> <span class=\"src\">— 倒排、相关度、聚合</span></li>\n      <li><a href=\"https://docs.spring.io/spring-data/elasticsearch/reference/\" target=\"_blank\" rel=\"noopener\">Spring Data Elasticsearch Reference</a> <span class=\"src\">— Repository 与 NativeQuery</span></li>\n      <li><a href=\"https://github.com/infinilabs/analysis-ik\" target=\"_blank\" rel=\"noopener\">infinilabs/analysis-ik · GitHub</a> <span class=\"src\">— IK 中文分词插件</span></li>\n    </ul>\n    <h3>下一课要用</h3>\n    <ul>\n      <li><a href=\"https://min.io/docs/minio/linux/index.html\" target=\"_blank\" rel=\"noopener\">MinIO Documentation</a> <span class=\"src\">— S7 对象存储主角</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"LIKE 为什么慢"},{"id":"b","title":"倒排与分词"},{"id":"c","title":"模型与灌数据"},{"id":"d","title":"加权+聚合"},{"id":"e","title":"隐藏真相"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    front:{code:\"原版 mall：用户在商城搜「手机」\\n前端 apis/product.ts → GET /product/search\\nmall-portal PmsPortalProductServiceImpl\\ncriteria.andNameLike(\\\"%手机%\\\")\\n→ MySQL LIKE 模糊查询\",log:[[\"warn\",\"原版默认走 MySQL，不是 ES\"],[\"c\",\"// 返回 CommonPage<PmsProduct>，MySQL 实体\"],[\"err\",\"数据量大时 LIKE 全表扫——演示够用，生产要换\"]]},\n    repo:{code:\"本仓库（已改造）：搜「手机」\\n前端 apis/product.ts\\nES_SEARCH_BASE_URL = http://localhost:8060/esProduct\\nGET /esProduct/search?keyword=手机\\n→ nginx location /esProduct/\\n→ proxy_pass http://mall-search:8081\\n→ ES pms 索引\",log:[[\"ok\",\"底稿 §4.4 的接入改造，本仓库已落地\"],[\"ok\",\"返回类型换成 CommonPage<EsProduct>\"],[\"api\",\"浏览器同源走 8060 网关，不直连后端端口\"]]},\n    es:{code:\"GET /esProduct/search?keyword=手机 (8081)\\nEsProductServiceImpl.search(...)\\n  term 筛品牌/分类\\n  function_score: name×10 subTitle×5 keywords×2\\n  排序: 新品/销量/价格/相关度\\n→ ES pms 索引倒排秒查\",log:[[\"ok\",\"加权+筛选+排序，生产级实现\"],[\"ok\",\"另有 /search/relate 聚合筛选栏、/recommend 推荐\"],[\"warn\",\"原版前端没调它；本仓库已接上\"]]},\n    import:{code:\"POST /esProduct/importAll\\nEsProductDao.getAllEsProductList(null)\\n  ← MySQL 三表 JOIN（商品+属性值+属性）\\nproductRepository.saveAll(list)\\n→ {\\\"code\\\":200,\\\"data\\\":20}\",log:[[\"ok\",\"MySQL 是源，ES 是索引\"],[\"api\",\"商品变更走 create/delete 同步\"],[\"warn\",\"光起 ES 不 importAll，搜索永远是空的\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById(\"e1code\").textContent=c.code;\n    document.getElementById(\"e1log\").innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"front\");\n})();\n\n(function(){\n  var sort='score';\n  var PRODUCTS=[\n    {name:'A 小米手机14',field:'name',sale:500,price:3999},\n    {name:'B 旗舰新品(副标题:拍照手机)',field:'subTitle',sale:2000,price:6999},\n    {name:'C 数码配件(关键词:手机壳)',field:'keywords',sale:100,price:59},\n    {name:'D 旅行背包',field:'none',sale:800,price:199}\n  ];\n  function calc(){\n    var wn=parseInt(document.getElementById('g1wn').value,10);\n    var ws=parseInt(document.getElementById('g1ws').value,10);\n    var wk=parseInt(document.getElementById('g1wk').value,10);\n    document.getElementById('g1wnV').textContent=wn;\n    document.getElementById('g1wsV').textContent=ws;\n    document.getElementById('g1wkV').textContent=wk;\n    var W={name:wn,subTitle:ws,keywords:wk,none:0};\n    var scored=PRODUCTS.map(function(p){return {name:p.name,score:W[p.field],sale:p.sale,price:p.price};});\n    var hits=scored.filter(function(p){return p.score>=2;});\n    var sorted=hits.slice().sort(function(a,b){\n      if(sort==='sale')return b.sale-a.sale;\n      if(sort==='price')return a.price-b.price;\n      return b.score-a.score;\n    });\n    var top=sorted.length?sorted[0].name:'(无结果)';\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+hits.length+'/4</b><small>过 minScore=2 的商品</small></div>'+\n      '<div class=\"stat-box good\"><b>'+top.split(' ')[0]+'</b><small>当前排第一</small></div>'+\n      '<div class=\"stat-box\"><b>'+(sort==='score'?'相关度':sort==='sale'?'销量':'价格↑')+'</b><small>排序方式</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(wn>=ws&&wn>=wk?'on':'bad')+'\">'+(wn>=ws&&wn>=wk?'名称命中最值钱(默认思路)':'名称权重被调低了')+'</span>'+\n      '<span class=\"chip bad\">D 无命中 score=0 被 minScore 挡掉</span>'+\n      (wk>=2?'':'<span class=\"chip bad\">keywords 权重<2：C 也被挡掉</span>');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">打分</span>'+\n      'score = 命中字段权重求和（这里每件商品只命中一个字段）。mall 默认 10/5/2：名字带关键词的排最前。把 subTitle 权重拖过 name，B 立刻反超 A——权重就是产品意志。';\n    var log=scored.map(function(p){\n      return '<div><span class=\"'+(p.score>=2?'ok':'err')+'\">'+p.name+' → score='+p.score+(p.score>=2?'':'（<minScore=2，过滤）')+'</span></div>';\n    });\n    log.push('<div><span class=\"api\">排序后：'+(sorted.map(function(p){return p.name.split(' ')[0];}).join(' > ')||'空')+'</span></div>');\n    log.push('<div><span class=\"c\">// '+(sort==='score'?'按 _score 倒序（默认）':sort==='sale'?'按 sale 倒序，得分只决定入围':'按 price 升序，得分只决定入围')+'</span></div>');\n    document.getElementById('g1log').innerHTML=log.join('');\n  }\n  ['g1wn','g1ws','g1wk'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  document.querySelectorAll('#g1sort button').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('#g1sort button').forEach(function(x){x.classList.remove('on');});b.classList.add('on');sort=b.getAttribute('data-k');calc();});});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. ES 搜索快的核心是？\",\"opts\":[[\"倒排索引：关键词→文档的映射提前建好\",true,\"对。按词取卡不全表扫。\"],[\"机器配置更高\",false,\"与硬件无关。\"],[\"数据存在内存\",false,\"那是 Redis 的故事。\"]]},{\"q\":\"2. LIKE '%手机%' 数据量大时为什么慢？\",\"opts\":[[\"前置通配符让索引失效，全表扫描\",true,\"对。\"],[\"MySQL 不支持中文\",false,\"支持。\"],[\"手机这个词太长\",false,\"无关。\"]]},{\"q\":\"3. EsProduct 里 brandName 用 Keyword、name 用 Text+ik，为什么？\",\"opts\":[[\"品牌要精确筛选，商品名要分词全文搜\",true,\"对。term 筛 Keyword，match 搜 Text。\"],[\"随便写的\",false,\"决定搜与筛的方式。\"],[\"Keyword 更省内存所以都用它\",false,\"分词字段必须 Text。\"]]},{\"q\":\"4. mall 综合搜索的加权是？\",\"opts\":[[\"name 10 / subTitle 5 / keywords 2，Sum 求和\",true,\"对。名称命中最值钱。\"],[\"三个字段权重一样\",false,\"那是简单搜索的思路。\"],[\"按价格加权\",false,\"价格是排序维度。\"]]},{\"q\":\"5. 搜索结果页的品牌/分类筛选栏数据怎么来？\",\"opts\":[[\"对结果做 terms/nested 聚合统计\",true,\"对。Aggregation。\"],[\"前端写死的\",false,\"随关键词变。\"],[\"每次 GROUP BY 查 MySQL\",false,\"ES 一步聚合。\"]]},{\"q\":\"6. 关于商城前端搜索，哪句是对的？\",\"opts\":[[\"原版前端走 /product/search 的 MySQL LIKE；本仓库已改走 nginx 网关接 ES\",true,\"对。就绪未启用是原版状态，本仓库已完成接入。\"],[\"原版和本仓库前端都走 ES\",false,\"原版前端调的是 /product/search。\"],[\"本仓库前端仍走 MySQL LIKE\",false,\"product.ts 已改走 8060 网关到 ES。\"]]}];" },
    "backend|java|MinIO：图片为什么单独存": { "body": "<p class=\"lead\">源码解读第七课：几十万张商品图为什么不塞进数据库？看懂对象存储这间「大仓库」，拆开 mall 上传图片拿 URL、数据库只存地址的分工，再算一笔账：把图片 base64 进库，账本会被撑成什么样。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">问题</span><span class=\"s\">账本里塞货</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">认识</span><span class=\"s\">对象存储</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">源码</span><span class=\"s\">上传拿 URL</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">边界</span><span class=\"s\">谁存什么</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">动手</span><span class=\"s\">演练与自测</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>账本里塞满货，账本就不叫账本了</h2>\n  <p>商城有几十万张商品图，每张几百 KB 到几 MB。有人图省事，把图片转成 base64 字符串塞进数据库字段。结果可想而知：库迅速变大，备份变慢，连查个商品名都要拖着几 MB 的「货」一起挪。数据库是<b>账本</b>，记的是「什么商品、多少钱、库存几件」；把货本身堆进账本，翻页都翻不动。</p>\n  <p>图片的本质是<b>静态文件</b>：不需要 SQL 去查它的内容，谁来取都是原样给。这种活该交给专门存文件的地方——<span class=\"term\">对象存储</span>。mall 选的是 <span class=\"term\">MinIO</span>，开源、兼容 S3 协议（亚马逊定下的对象存储事实标准）。</p>\n  <div class=\"recap\"><b>收束：</b>账本记结构化数据，仓库存文件；图片是货不是账，别塞数据库。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>对象存储：桶、对象、URL 三个词就够了</h2>\n  <ul>\n    <li><b>桶 bucket</b>：类似顶层文件夹，mall 配置里就叫 <code>mall</code>（minio.bucketName）。</li>\n    <li><b>对象 object</b>：存进去的文件本体，带个对象名。mall 用「日期/原文件名」，比如 <code>20261127/phone.jpg</code>。几百 MB 到几 GB 都没问题。</li>\n    <li><b>URL</b>：每个文件一个地址，谁拿着 URL 就能取，天然适合静态资源分发。</li>\n  </ul>\n  <table>\n    <tr><th></th><th>MySQL</th><th>MinIO</th></tr>\n    <tr><td>存什么</td><td>结构化数据（订单、商品信息）</td><td>文件（图片、视频、附件）</td></tr>\n    <tr><td>关于图片存什么</td><td>只存图片的 URL 地址</td><td>图片内容本体</td></tr>\n    <tr><td>类比</td><td>账本</td><td>仓库</td></tr>\n  </table>\n  <div class=\"key\"><span class=\"tag\">关键思想</span>数据库只存「在哪」（URL），MinIO 真的存「内容」。前端拿数据库里的 URL 去 MinIO 取图，两边各司其职。</div>\n  <div class=\"recap\"><b>收束：</b>桶装对象、对象有 URL；海量、按址取件，是对象存储的三个卖点。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>mall 源码：上传拿 URL，数据库存地址</h2>\n  <p>上传入口在后台 <code>MinioController</code>：<code>POST /minio/upload</code> 收 <code>MultipartFile</code>，活全在 Controller 里干完：先查桶在不在，不在就<b>建桶并设只读策略</b>（所以图片 URL 能匿名访问）；再把文件流 <code>minioClient.putObject()</code> 放进桶，对象名是「yyyyMMdd/原文件名」；最后拼出 <code>endpoint/桶名/对象名</code> 的 URL，装进 <code>MinioUploadDto</code>（name + url）用 <code>CommonResult.success()</code> 返回。没有单独的 Service 层——读源码时别想当然按三层去找。</p>\n  <figure>\n    <svg viewBox=\"0 0 760 200\" role=\"img\" aria-label=\"图片上传与 URL 流通\">\n      <defs><marker id=\"ars7\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"30\" width=\"160\" height=\"60\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"88\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">管理员上传图片</text><text x=\"88\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">mall-admin /minio/upload</text>\n      <rect x=\"228\" y=\"30\" width=\"180\" height=\"60\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"318\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">MinIO 仓库</text><text x=\"318\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">putObject → mall/20261127/phone.jpg</text>\n      <rect x=\"470\" y=\"30\" width=\"180\" height=\"60\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"560\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">MySQL 账本</text><text x=\"560\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">商品记录只存 URL 字符串</text>\n      <rect x=\"470\" y=\"126\" width=\"180\" height=\"56\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"560\" y=\"149\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">顾客前端展示</text><text x=\"560\" y=\"167\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">拿 URL 直接去 MinIO 取图</text>\n      <line x1=\"168\" y1=\"60\" x2=\"226\" y2=\"60\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars7)\"/>\n      <line x1=\"408\" y1=\"60\" x2=\"468\" y2=\"60\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars7)\"/>\n      <line x1=\"560\" y1=\"90\" x2=\"560\" y2=\"124\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars7)\"/>\n      <line x1=\"470\" y1=\"154\" x2=\"330\" y2=\"92\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars7)\"/>\n      <text x=\"240\" y=\"112\" font-size=\"11\" fill=\"#7C7166\">① 文件进仓库</text>\n      <text x=\"430\" y=\"48\" font-size=\"11\" fill=\"#7C7166\">② URL 进账本</text>\n      <text x=\"380\" y=\"192\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">前台 portal 不直接碰 MinIO，只读 URL——但整套系统没 MinIO 就没图可看</text>\n    </svg>\n    <figcaption>图 1 · 文件走仓库、地址走账本；上传在 admin，展示在顾客端。</figcaption>\n  </figure>\n  <p>一个容易读错的点：<b>MinIO 主要给后台 mall-admin 用</b>。商品图是管理员上传的；前台商城只是「读」URL，不直接依赖 MinIO 客户端。但部署时它仍要一起起——没有仓库，店面就没货可摆。这又是第一课那句「不同岗位按需依赖不同中间件」的实例。</p>\n  <div class=\"recap\"><b>收束：</b>upload 返回 URL、库里存 URL、前端凭 URL 取图；admin 写仓库，portal 只读地址。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>为什么不存本地磁盘，以及选型边界</h2>\n  <p>另一个候选是「存应用服务器本地磁盘」。单台机器能跑，多台就露馅：图片传到 A 服务器，请求落到 B 就 404；扩容要同步文件，麻烦且易错。MinIO 是<b>独立服务</b>，几台应用服务器都连同一个仓库，天然共享、海量扩展。</p>\n  <table>\n    <tr><th>方案</th><th>问题</th></tr>\n    <tr><td>base64 塞数据库</td><td>库爆炸、查询慢、备份拖累，编码还膨胀约 1/3 体积</td></tr>\n    <tr><td>应用本地磁盘</td><td>多服务器文件不一致，扩容要搬文件</td></tr>\n    <tr><td>MinIO 对象存储</td><td>独立服务共享，按 URL 访问，海量扩展</td></tr>\n  </table>\n  <p>判断一句话：<b>大文件 + 静态资源 + 按 URL 访问 → 对象存储；结构化数据 + 要查询要事务 → 数据库。</b>几 KB 的配置文字别往对象存储塞，那是账本的活。</p>\n  <div class=\"note\"><span class=\"tag\">本地三个坑</span>① MinIO 没起，上传接口报错——<code>curl localhost:9000</code> 确认；② 容器互连写容器名，别写 localhost；③ 返回的 URL 前缀（host/端口/bucket）要能被浏览器访问，否则前端拿到地址也取不到图。管理界面在 9001 端口，minioadmin/minioadmin 登录能看桶和文件。</div>\n  <div class=\"recap\"><b>收束：</b>独立仓库解决多机共享；文件归仓库、数据归账本，按「是不是静态大文件」分家。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：三种存法对照、账本膨胀计算器</h2>\n  <p>演练一把同一张图用三种方案存，看各自的命运。演练二拖图片数量和大小，算算 base64 进库会把数据库撑到多大，而 URL 方案只占多少。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 一张商品图的三种命运</b><span class=\"hint\">点按钮切换方案</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"db\" class=\"on\">base64 进数据库</button><button data-k=\"disk\">应用本地磁盘</button><button data-k=\"minio\">MinIO 对象存储</button></div></div>\n    <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>方案评估</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">单机都能跑，差别在多机、扩容和账本健康</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 账本膨胀计算器</b><span class=\"hint\">拖滑杆，看两种存法的体积差</span></div>\n    <div class=\"controls\">\n      <div class=\"ctl\"><label>图片数量(万)</label><input type=\"range\" id=\"g1n\" min=\"1\" max=\"50\" value=\"10\"><span class=\"val\" id=\"g1nV\">10</span></div>\n      <div class=\"ctl\"><label>平均大小(KB)</label><input type=\"range\" id=\"g1kb\" min=\"100\" max=\"2000\" step=\"100\" value=\"500\"><span class=\"val\" id=\"g1kbV\">500</span></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>算账过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">模型：base64 膨胀约 4/3；URL 按 100 字节/条计</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>数据库里那行记录本该几十字节，塞进图片就变成几 MB——查询、备份、主从同步全被拖累。URL 方案账本轻、仓库大，各得其所。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>六个问题</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。账本和仓库的分工清楚了。下一课看所有接口共用的那张回执单。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>速查表</h2>\n  <table>\n    <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n    <tr><td>对象存储</td><td>专存文件的大仓库</td><td>海量、按 URL 取件</td></tr>\n    <tr><td>MinIO</td><td>开源 S3 兼容仓库</td><td>桶/对象/URL 三个词</td></tr>\n    <tr><td>数据库存 URL</td><td>账本只记「在哪」</td><td>内容在仓库，地址在账本</td></tr>\n    <tr><td>upload 链路</td><td>文件进桶→返回 URL→存库</td><td>MinioController→MinioService</td></tr>\n    <tr><td>admin 写 portal 读</td><td>管理员上传，顾客看图</td><td>前台不直接依赖 MinIO 客户端</td></tr>\n    <tr><td>本地磁盘的问题</td><td>多机文件不一致</td><td>独立服务天然共享</td></tr>\n    <tr><td>base64 的代价</td><td>体积膨胀约 1/3</td><td>库变大变慢，备份拖累</td></tr>\n    <tr><td>选型口诀</td><td>静态大文件→仓库</td><td>结构化要查询→数据库</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>上传链路依据本仓库 mall-admin 的 MinioController/MinioService；体积计算为模型估算。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第七篇-MinIO <span class=\"src\">— 本课重写底稿</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/</code>；编排 <code>mall-docker/docker-compose.yml</code> <span class=\"src\">— MinIO 服务随编排启动</span></li>\n    </ul>\n    <h3>源码路标（相对 mall 工程根）</h3>\n    <ul>\n      <li><code>mall-admin/.../controller/MinioController.java</code> <span class=\"src\">— /minio/upload 上传入口</span></li>\n      <li><code>mall-admin/.../service/impl/MinioServiceImpl.java</code> <span class=\"src\">— putObject 与 URL 拼装</span></li>\n      <li><code>mall-admin/src/main/resources/application-dev.yml</code> <span class=\"src\">— minio endpoint/bucketName: mall 配置</span></li>\n    </ul>\n    <h3>官方文档</h3>\n    <ul>\n      <li><a href=\"https://min.io/docs/minio/linux/index.html\" target=\"_blank\" rel=\"noopener\">MinIO Documentation</a> <span class=\"src\">— 部署、桶与对象</span></li>\n      <li><a href=\"https://min.io/docs/minio/linux/developers/java/API.html\" target=\"_blank\" rel=\"noopener\">MinIO Java SDK API Reference</a> <span class=\"src\">— putObject 等接口</span></li>\n      <li><a href=\"https://github.com/macrozheng/mall\" target=\"_blank\" rel=\"noopener\">macrozheng/mall · GitHub</a> <span class=\"src\">— 上游项目</span></li>\n    </ul>\n    <h3>下一课要用</h3>\n    <ul>\n      <li><a href=\"https://docs.spring.io/spring-framework/reference/web/webmvc/mvc-controller/ann-exceptionhandler.html\" target=\"_blank\" rel=\"noopener\">Spring MVC · @ExceptionHandler</a> <span class=\"src\">— S8 全局异常处理的框架基础</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"账本里塞货"},{"id":"b","title":"桶对象URL"},{"id":"c","title":"上传拿URL"},{"id":"d","title":"边界与部署"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    db:{code:\"INSERT INTO pms_product (pic) VALUES\\n('data:image/jpeg;base64,/9j/4AAQSkZJRg...');\\n// 一张 500KB 图 → 约 667KB 字符串\\n// 商品表每行都拖着这么一坨\",log:[[\"err\",\"库爆炸：查询/备份/主从同步全被拖累\"],[\"warn\",\"base64 编码体积膨胀约 4/3\"],[\"c\",\"// 图片不需要 SQL 查内容，塞账本纯属浪费\"]]},\n    disk:{code:\"file.transferTo(new File(\\\"/app/uploads/uuid.jpg\\\"));\\n// 图片在 A 服务器磁盘上\\n// 负载均衡把请求分到 B → 404\",log:[[\"warn\",\"多服务器文件不一致\"],[\"err\",\"扩容要搬文件，麻烦且易错\"],[\"c\",\"// 单机演示能跑，生产多机露馅\"]]},\n    minio:{code:\"minioClient.putObject(bucket, object, stream);\\nreturn \\\"http://localhost:9000/mall/20261127/phone.jpg\\\";\\n// 数据库只存这个 URL\\n// 所有应用服务器连同一个仓库\",log:[[\"ok\",\"独立服务：多机天然共享\"],[\"ok\",\"按 URL 取件，海量扩展\"],[\"c\",\"// 账本轻、仓库大，各得其所\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById(\"e1code\").textContent=c.code;\n    document.getElementById(\"e1log\").innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"db\");\n})();\n\n(function(){\n  function fmt(mb){\n    if(mb>=1024)return (mb/1024).toFixed(1)+' GB';\n    return mb.toFixed(1)+' MB';\n  }\n  function calc(){\n    var n=parseInt(document.getElementById('g1n').value,10);\n    var kb=parseInt(document.getElementById('g1kb').value,10);\n    document.getElementById('g1nV').textContent=n;\n    document.getElementById('g1kbV').textContent=kb;\n    var count=n*10000;\n    var rawMb=count*kb/1024;\n    var b64Mb=rawMb*4/3;\n    var urlMb=count*100/1024/1024;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box bad\"><b>'+fmt(b64Mb)+'</b><small>base64 进库增量</small></div>'+\n      '<div class=\"stat-box good\"><b>'+fmt(urlMb)+'</b><small>URL 进库增量</small></div>'+\n      '<div class=\"stat-box\"><b>'+fmt(rawMb)+'</b><small>文件本体(在 MinIO)</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip bad\">base64 是 URL 方案的约 '+Math.round(b64Mb/urlMb)+' 倍</span>'+\n      '<span class=\"chip on\">MinIO 存 '+fmt(rawMb)+' 毫无压力</span>'+\n      (b64Mb>10240?'<span class=\"chip bad\">账本超 10GB：备份和同步开始遭罪</span>':'');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">算账</span>'+\n      '同样的 '+n+' 万张图：URL 方案账本只涨 '+fmt(urlMb)+'，base64 方案涨 '+fmt(b64Mb)+'。商品表的每次查询、每次备份、每次主从同步，都要拖着这些字节走。';\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">文件总量 = '+count.toLocaleString()+' × '+kb+'KB ≈ '+fmt(rawMb)+'</span></div>',\n      '<div><span class=\"err\">base64 进库 ≈ '+fmt(rawMb)+' × 4/3 = '+fmt(b64Mb)+'</span></div>',\n      '<div><span class=\"ok\">URL 进库 ≈ '+count.toLocaleString()+' × 100B = '+fmt(urlMb)+'</span></div>',\n      '<div><span class=\"c\">// 文件本体放 MinIO，账本只记地址</span></div>'\n    ].join('');\n  }\n  ['g1n','g1kb'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 图片为什么不塞数据库？\",\"opts\":[[\"静态文件不需要 SQL 查内容，塞进去库变大变慢\",true,\"对。账本不该存货。\"],[\"数据库存不下图片\",false,\"存得下，是不该存。\"],[\"图片需要事务\",false,\"不需要。\"]]},{\"q\":\"2. 对象存储的三个关键词？\",\"opts\":[[\"桶、对象、URL\",true,\"对。文件夹、文件、地址。\"],[\"表、行、索引\",false,\"那是关系型。\"],[\"键、值、TTL\",false,\"那是 Redis。\"]]},{\"q\":\"3. mall 里数据库和图片相关的字段存的是？\",\"opts\":[[\"图片的 URL 地址\",true,\"对。内容在 MinIO。\"],[\"图片 base64\",false,\"反面教材。\"],[\"图片二进制\",false,\"同上。\"]]},{\"q\":\"4. MinIO 相比应用本地磁盘的优势？\",\"opts\":[[\"独立服务，多台应用服务器共享同一仓库\",true,\"对。扩容不用搬文件。\"],[\"读写更快\",false,\"不是核心差异。\"],[\"不需要网络\",false,\"恰恰通过网络共享。\"]]},{\"q\":\"5. MinIO 在 mall 里主要谁在用？\",\"opts\":[[\"mall-admin 上传；portal 只读 URL\",true,\"对。但部署要一起起。\"],[\"portal 直接上传\",false,\"顾客不传商品图。\"],[\"search 模块\",false,\"搜索不碰文件。\"]]},{\"q\":\"6. 什么数据不适合放对象存储？\",\"opts\":[[\"要 SQL 查询和事务的结构化数据\",true,\"对。那是数据库的活。\"],[\"商品图片\",false,\"正适合。\"],[\"视频附件\",false,\"正适合。\"]]}];" },
    "backend|java|接口规范：统一回执与全局异常": { "body": "<p class=\"lead\">源码解读第八课：前端拿到一个 null，是成功还是失败？看懂 mall 让所有接口共用一张回执单 CommonResult，再用全局异常处理器把散落各处的 try-catch 收进一个兜底网。这套是纯代码，读完就能搬进自己的项目。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">问题</span><span class=\"s\">返回五花八门</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">回执</span><span class=\"s\">CommonResult</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">兜底</span><span class=\"s\">全局异常</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>前端拿到 null 一脸问号：这算成功还是失败</h2>\n  <p>没定规范的后端项目长这样：这个接口 <code>return new HashMap()</code>，那个接口 <code>return List</code>，报错的地方直接 <code>return null</code>。前端拿到 null 只能猜——是没查到数据？是出错了？还是接口挂了？每个接口的「表达习惯」都不一样，前后端天天为「你这个字段什么意思」开会。</p>\n  <p>更糟的是异常处理：数据库连不上、参数校验没过，就在 Controller 里 try-catch 包一层 return null。错误信息散落代码各处，排查靠全文搜日志，用户看到的要么是白屏，要么是一坨英文堆栈。</p>\n  <p>mall 的治法就两招：<b>所有接口返回同一张回执单</b>（CommonResult），<b>所有异常进同一张兜底网</b>（GlobalExceptionHandler）。这一课没有中间件要装，两招都是纯代码。</p>\n  <div class=\"recap\"><b>收束：</b>乱的不是某个接口，是「没有统一标准」；回执统一 + 异常统一，两招治本。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>CommonResult：code、message、data 三件套</h2>\n  <p>第一课见过这张回执单，这次拆开看它怎么造出来的。<code>CommonResult&lt;T&gt;</code> 三个字段加一组静态工厂：</p>\n  <pre>public class CommonResult&lt;T&gt; {\n    private long code;      // 业务状态码\n    private String message; // 提示信息\n    private T data;         // 具体数据\n\n    public static &lt;T&gt; CommonResult&lt;T&gt; success(T data) { ... }\n    public static &lt;T&gt; CommonResult&lt;T&gt; failed(IErrorCode errorCode) { ... }\n    public static &lt;T&gt; CommonResult&lt;T&gt; failed(String message) { ... }\n}</pre>\n  <p>配套一套固定错误码枚举 <code>ResultCode</code>，前端看 code 就知道下一步做什么：</p>\n  <table>\n    <tr><th>code</th><th>含义</th><th>前端的动作</th></tr>\n    <tr><td>200</td><td>操作成功</td><td>取 data 渲染</td></tr>\n    <tr><td>401</td><td>暂未登录或 token 已过期</td><td>跳登录页（双 token 项目先试刷新）</td></tr>\n    <tr><td>403</td><td>没有相关权限</td><td>提示无权限</td></tr>\n    <tr><td>404</td><td>参数检验失败</td><td>提示检查输入</td></tr>\n    <tr><td>500</td><td>操作失败</td><td>展示 message</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">两个提醒</span>① 这是<b>业务状态码</b>，别和 HTTP 状态码混为一谈——mall 把「参数检验失败」定为 404，就是自家约定，HTTP 层可能仍是 200。② 翻遍 mall 任何一个 Controller，返回类型全是 CommonResult，没有例外。规范的价值就在「没有例外」。</div>\n  <div class=\"recap\"><b>收束：</b>三字段回执 + 固定错误码枚举；前端不再猜，看 code 分支处理。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>全局异常处理器：业务只管喊，兜底有人接</h2>\n  <p>mall 用 <code>@ControllerAdvice</code> 声明一个全局异常处理器，所有 Controller 抛出的异常都被它接住，翻译成前端能看懂的 CommonResult：</p>\n  <pre>@ControllerAdvice\npublic class GlobalExceptionHandler {\n    @ExceptionHandler(value = ApiException.class)\n    public CommonResult handle(ApiException e) {\n        if (e.getErrorCode() != null) {\n            return CommonResult.failed(e.getErrorCode());\n        }\n        return CommonResult.failed(e.getMessage());\n    }\n}</pre>\n  <figure>\n    <svg viewBox=\"0 0 760 190\" role=\"img\" aria-label=\"异常统一兜底流程\">\n      <defs><marker id=\"ars8\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"30\" width=\"180\" height=\"62\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"98\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">业务代码发现问题</text><text x=\"98\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">Asserts.fail(\"密码不正确\")</text>\n      <rect x=\"248\" y=\"30\" width=\"160\" height=\"62\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"328\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">抛 ApiException</text><text x=\"328\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">不用自己 try-catch</text>\n      <rect x=\"468\" y=\"30\" width=\"180\" height=\"62\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"558\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">全局处理器接住</text><text x=\"558\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">@ControllerAdvice</text>\n      <rect x=\"468\" y=\"122\" width=\"180\" height=\"52\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"558\" y=\"143\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">CommonResult.failed</text><text x=\"558\" y=\"161\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">code=500, message=密码不正确</text>\n      <line x1=\"188\" y1=\"61\" x2=\"246\" y2=\"61\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars8)\"/>\n      <line x1=\"408\" y1=\"61\" x2=\"466\" y2=\"61\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars8)\"/>\n      <line x1=\"558\" y1=\"92\" x2=\"558\" y2=\"120\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars8)\"/>\n      <text x=\"240\" y=\"130\" font-size=\"12\" fill=\"#7C7166\">Controller 干干净净，一个 try-catch 都不用写</text>\n      <text x=\"240\" y=\"152\" font-size=\"11\" fill=\"#A39B8E\">错误信息集中在一张网里，排查有固定入口</text>\n    </svg>\n    <figcaption>图 1 · 业务一行 Asserts.fail 喊出问题，全局处理器统一翻译成回执。</figcaption>\n  </figure>\n  <p>业务代码想报错，一行 <code>Asserts.fail(\"用户名或密码错误\")</code> 就够——它内部抛 <code>ApiException</code>，剩下的全交给兜底网。第二课登录流程里那句「密码不正确」，走的就是这条路。</p>\n  <div class=\"key\"><span class=\"tag\">分工一句话</span>业务代码负责<b>发现问题</b>，全局处理器负责<b>表达问题</b>。发现的逻辑分散在各处没问题，表达的方式必须只有一种。</div>\n  <div class=\"recap\"><b>收束：</b>@ControllerAdvice 接所有异常，ApiException 带错误码，Asserts.fail 一行喊话；Controller 零 try-catch。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>这套东西怎么搬进自己的项目</h2>\n  <p>这一课不用装任何中间件——CommonResult、ResultCode、ApiException、Asserts、GlobalExceptionHandler 加起来就几个类，从 <code>mall-common</code> 和 <code>mall-admin</code> 里抄出来改改包名就能用。任何给前端提供接口的 Spring Boot 项目都该有这套，多人协作、前后端分离的项目尤其如此。</p>\n  <ul>\n    <li>第一步：抄 <code>CommonResult</code> + <code>ResultCode</code>，所有 Controller 返回它。</li>\n    <li>第二步：抄 <code>ApiException</code> + <code>Asserts</code>，业务代码用它喊错。</li>\n    <li>第三步：写 <code>@ControllerAdvice</code> 处理器，把 ApiException 和其他异常都翻译成回执。</li>\n    <li>第四步：和前端约定 code 表，401 跳登录、403 提示无权限，写进接口文档。</li>\n  </ul>\n  <div class=\"note\"><span class=\"tag\">别过度设计</span>极简脚本、内部一次性工具，可以不搞这么完整。但凡有第二个人要对接你的接口，这张回执单就值回票价——规范省下的沟通成本，远超写这几个类的时间。</div>\n  <div class=\"recap\"><b>收束：</b>纯代码四步搬走；有对接方就该统一，一人一次性脚本可免。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：写法对照、前端分支模拟器</h2>\n  <p>演练一看同一个「密码错误」在无规范、有回执、有兜底三种项目里各长什么样。演练二模拟前端收到不同 code 时的分支动作，体会「看 code 不用猜」。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 同一个错误的三种表达</b><span class=\"hint\">点按钮切换项目风格</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"raw\" class=\"on\">无规范项目</button><button data-k=\"result\">统一回执</button><button data-k=\"advice\">回执+全局兜底</button></div></div>\n    <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>前端视角</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">错误还是那个错误，差别在表达方式统不统一</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 前端分支模拟器</b><span class=\"hint\">选场景，看回执长什么样、前端做什么</span></div>\n    <div class=\"controls\">\n      <div class=\"seg\" id=\"g1case\"><button data-k=\"ok\" class=\"on\">查询成功</button><button data-k=\"auth\">token 过期</button><button data-k=\"perm\">无权限</button><button data-k=\"param\">参数错</button><button data-k=\"biz\">密码错误</button></div>\n      <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1advice\" checked> 启用全局异常处理器</label></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>响应与前端动作</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">关掉兜底再看「密码错误」：前端收到的就不是回执了</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>统一回执让前端只写一套分支逻辑；全局兜底保证「无论哪里出错，前端拿到的都是同一张回执」。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>六个问题</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。回执和兜底网可以直接搬进你的项目了。下一课看一百张表怎么不手写。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>速查表</h2>\n  <table>\n    <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n    <tr><td>CommonResult</td><td>统一回执单</td><td>code/message/data，全项目无例外</td></tr>\n    <tr><td>ResultCode</td><td>固定错误码表</td><td>200/401/403/404/500，前端按 code 分支</td></tr>\n    <tr><td>业务码 vs HTTP 码</td><td>自家约定 vs 协议规定</td><td>别混为一谈</td></tr>\n    <tr><td>@ControllerAdvice</td><td>全局兜底网</td><td>接住所有 Controller 的异常</td></tr>\n    <tr><td>ApiException + Asserts</td><td>一行喊话</td><td>Asserts.fail 内部抛 ApiException</td></tr>\n    <tr><td>分工</td><td>业务发现，处理器表达</td><td>表达方式只有一种</td></tr>\n    <tr><td>可搬性</td><td>纯代码几个类</td><td>抄走改包名即用</td></tr>\n    <tr><td>边界</td><td>有对接方就该统一</td><td>一次性脚本可免</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>结构依据本仓库 mall-common 的 api 包与 mall-admin 的异常处理实现；错误码含义以 ResultCode 枚举为准。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第八篇-接口规范 <span class=\"src\">— 本课重写底稿</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/</code> <span class=\"src\">— 纯代码，无中间件依赖</span></li>\n    </ul>\n    <h3>源码路标（相对 mall 工程根）</h3>\n    <ul>\n      <li><code>mall-common/.../api/CommonResult.java</code>、<code>ResultCode.java</code>、<code>IErrorCode.java</code> <span class=\"src\">— 回执与错误码</span></li>\n      <li><code>mall-common/.../exception/ApiException.java</code>、<code>Asserts.java</code> <span class=\"src\">— 业务异常与一行喊话</span></li>\n      <li><code>mall-common/.../exception/GlobalExceptionHandler.java</code> <span class=\"src\">— @ControllerAdvice 全局兜底（就在 common 里，各应用共用）</span></li>\n    </ul>\n    <h3>官方文档</h3>\n    <ul>\n      <li><a href=\"https://docs.spring.io/spring-framework/reference/web/webmvc/mvc-controller/ann-exceptionhandler.html\" target=\"_blank\" rel=\"noopener\">Spring MVC · @ExceptionHandler</a> <span class=\"src\">— 异常处理机制</span></li>\n      <li><a href=\"https://docs.spring.io/spring-framework/reference/web/webmvc/mvc-controller/ann-advice.html\" target=\"_blank\" rel=\"noopener\">Spring MVC · @ControllerAdvice</a> <span class=\"src\">— 全局增强的作用范围</span></li>\n      <li><a href=\"https://github.com/macrozheng/mall\" target=\"_blank\" rel=\"noopener\">macrozheng/mall · GitHub</a> <span class=\"src\">— 上游项目</span></li>\n    </ul>\n    <h3>下一课要用</h3>\n    <ul>\n      <li><a href=\"https://mybatis.org/generator/\" target=\"_blank\" rel=\"noopener\">MyBatis Generator</a> <span class=\"src\">— S9 代码生成器主角</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"返回为什么乱"},{"id":"b","title":"三件套回执"},{"id":"c","title":"全局兜底网"},{"id":"d","title":"搬进自己项目"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    raw:{code:\"// 无规范项目\\n@PostMapping(\\\"/login\\\")\\npublic Object login(...) {\\n  try {\\n    ...\\n  } catch (Exception e) {\\n    return null;   // 前端：？？？\\n  }\\n}\",log:[[\"err\",\"前端拿到 null：成功？失败？没数据？\"],[\"warn\",\"每个接口表达习惯不同，天天开会对字段\"],[\"c\",\"// 错误信息散落各处，排查靠搜日志\"]]},\n    result:{code:\"// 统一回执\\n@PostMapping(\\\"/login\\\")\\npublic CommonResult login(...) {\\n  if (!passwordEncoder.matches(...)) {\\n    return CommonResult.failed(\\\"密码不正确\\\");\\n  }\\n  return CommonResult.success(token);\\n}\",log:[[\"ok\",\"前端看 code：500 失败，展示 message\"],[\"warn\",\"但每个失败点还要手写 return failed\"],[\"c\",\"// 回执统一了，异常处理还没统一\"]]},\n    advice:{code:\"// 回执 + 全局兜底\\npublic String login(...) {\\n  Asserts.fail(\\\"密码不正确\\\");  // 一行喊话\\n}\\n@ControllerAdvice\\npublic class GlobalExceptionHandler {\\n  @ExceptionHandler(ApiException.class)\\n  public CommonResult handle(ApiException e) {...}\\n}\",log:[[\"ok\",\"Controller 零 try-catch，干干净净\"],[\"ok\",\"无论哪里出错，前端拿到的都是同一张回执\"],[\"c\",\"// 业务发现问题，处理器表达问题\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById(\"e1code\").textContent=c.code;\n    document.getElementById(\"e1log\").innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"raw\");\n})();\n\n(function(){\n  var CASES={\n    ok:{code:200,msg:'操作成功',data:'[{id:1,name:\"小米手机14\"}]',act:'取 data 渲染列表',exc:false},\n    auth:{code:401,msg:'暂未登录或token已经过期',data:'null',act:'跳登录页（双 token 先试刷新）',exc:false},\n    perm:{code:403,msg:'没有相关权限',data:'null',act:'提示无权限，不跳转',exc:false},\n    param:{code:404,msg:'参数检验失败',data:'null',act:'提示检查输入',exc:false},\n    biz:{code:500,msg:'密码不正确',data:'null',act:'展示 message 给用户',exc:true}\n  };\n  var cur='ok';\n  function calc(){\n    var c=CASES[cur];\n    var advice=document.getElementById('g1advice').checked;\n    var broken=c.exc&&!advice;\n    var json=broken?'HTTP 500 + 一坨异常堆栈(英文)':('{ \"code\": '+c.code+', \"message\": \"'+c.msg+'\", \"data\": '+c.data+' }');\n    var act=broken?'白屏或弹英文报错，不知道发生了什么':c.act;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box '+(broken?'bad':'good')+'\"><b>'+(broken?'堆栈':c.code)+'</b><small>前端收到的 code</small></div>'+\n      '<div class=\"stat-box\"><b>'+(broken?'猜':'分支')+'</b><small>前端处理方式</small></div>'+\n      '<div class=\"stat-box '+(advice?'good':'bad')+'\"><b>'+(advice?'开':'关')+'</b><small>全局兜底</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(broken?'bad':'on')+'\">'+(broken?'回执被异常打断':'统一回执')+'</span>'+\n      '<span class=\"chip '+(broken?'bad':'on')+'\">'+act+'</span>'+\n      (c.exc?'<span class=\"chip '+(advice?'on':'bad')+'\">此场景走 Asserts.fail 抛异常</span>':'');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(broken?'事故':'规范')+'</span>'+\n      (broken?'业务抛了 ApiException 却没人接：异常直接冒到容器层，前端收到的不再是回执。兜底网必须常驻。':'前端只写一套分支：200 渲染、401 登录、403 提示、404 查输入、500 展示 message。不用猜。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">响应体：'+json+'</span></div>',\n      '<div><span class=\"'+(broken?'err':'ok')+'\">前端动作：'+act+'</span></div>',\n      '<div><span class=\"c\">// '+(c.exc?'业务异常路径：Asserts.fail → ApiException → '+(advice?'GlobalExceptionHandler → CommonResult':'(无人接住)'):'正常返回路径：Controller 直接返回 CommonResult')+'</span></div>'\n    ].join('');\n  }\n  document.querySelectorAll('#g1case button').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('#g1case button').forEach(function(x){x.classList.remove('on');});b.classList.add('on');cur=b.getAttribute('data-k');calc();});});\n  document.getElementById('g1advice').addEventListener('change',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 接口统一返回结构的直接收益？\",\"opts\":[[\"前端看 code 就知结果，不用猜、少开会\",true,\"对。沟通成本大降。\"],[\"接口跑得更快\",false,\"与性能无关。\"],[\"代码行数更少\",false,\"不是主要目的。\"]]},{\"q\":\"2. CommonResult 的三个字段？\",\"opts\":[[\"code / message / data\",true,\"对。状态、提示、数据。\"],[\"status / error / result\",false,\"不是 mall 的约定。\"],[\"header / payload / signature\",false,\"那是 JWT。\"]]},{\"q\":\"3. mall 的 ResultCode 里 404 表示？\",\"opts\":[[\"参数检验失败（业务码，别当 HTTP 码）\",true,\"对。自家约定。\"],[\"页面不存在\",false,\"那是 HTTP 语义。\"],[\"未登录\",false,\"那是 401。\"]]},{\"q\":\"4. @ControllerAdvice 的作用？\",\"opts\":[[\"接住所有 Controller 抛出的异常统一处理\",true,\"对。全局兜底网。\"],[\"只处理一个 Controller\",false,\"那是局部 @ExceptionHandler。\"],[\"拦截所有请求做鉴权\",false,\"那是过滤器的活。\"]]},{\"q\":\"5. Asserts.fail(\\\"密码不正确\\\") 之后发生什么？\",\"opts\":[[\"抛 ApiException，全局处理器转成 failed 回执\",true,\"对。一行喊话有人接。\"],[\"直接返回字符串给前端\",false,\"要经兜底翻译。\"],[\"程序崩溃退出\",false,\"异常被接住了。\"]]},{\"q\":\"6. 这套规范什么时候可以不上？\",\"opts\":[[\"一人用的一次性极简脚本\",true,\"对。有对接方就该统一。\"],[\"前后端分离项目\",false,\"尤其需要。\"],[\"多人协作项目\",false,\"尤其需要。\"]]}];" },
    "backend|java|代码生成器：一百张表不手写": { "body": "<p class=\"lead\">源码解读第九课：mall 一百多张表，每张都要实体类、Mapper、XML 三件套，手写要写到手软。看懂 MyBatis Generator 这台「生产代码的代码」机器怎么读表出代码，分清生成器管通用 CRUD、你管复杂业务的边界，再算算一百张表能省多少工时。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">问题</span><span class=\"s\">一百张表手写</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">机器</span><span class=\"s\">读表出代码</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">分工</span><span class=\"s\">通用 vs 复杂</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">边界</span><span class=\"s\">坑与替代</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">动手</span><span class=\"s\">演练与自测</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>一百多张表，每张都要照着抄一遍</h2>\n  <p>mall 光商品、订单、用户、优惠券就一百多张表。每张表你都得写三样：<b>实体类</b>（把字段翻译成 Java 属性）、<b>Mapper 接口</b>（增删改查方法声明）、<b>XML 映射</b>（SQL 语句）。这些代码高度重复、毫无技术含量，就是「照着表结构翻译成 Java」。</p>\n  <p>手写的代价不只是慢：一张 30 个字段的表，少抄一个字段，编译不报错，<b>运行才炸</b>；类型抄错一个，排查半天。纯体力活干一百遍，出错概率随次数线性涨。</p>\n  <p>这种活就该交给机器。<span class=\"term\">MyBatis Generator</span>（MBG）是 MyBatis 官方的代码生成工具，干的事一句话：<b>读数据库表结构，自动生成三件套</b>。第一课那个 <code>mall-mbg</code> 模块——「资料卡+取数工具」——整包都是它生成的。</p>\n  <div class=\"recap\"><b>收束：</b>重复翻译是机器的活；手写一百遍 CRUD，慢且必然出错。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>mall-mbg 源码：一个 main 方法，几百个文件</h2>\n  <p><code>mall-mbg</code> 模块结构极简：<code>Generator.java</code> 是入口（一个 main 方法），<code>model/</code> 放生成的实体类，<code>mapper/</code> 放生成的接口和 XML。入口核心就几行：</p>\n  <pre>InputStream is = Generator.class.getResourceAsStream(\"/generatorConfig.xml\");\nConfiguration config = cp.parseConfiguration(is);\nMyBatisGenerator generator = new MyBatisGenerator(config, new DefaultShellCallback(true), warnings);\ngenerator.generate(null);   // 跑完，几百个文件就位</pre>\n  <p>指挥它的是 <code>generatorConfig.xml</code>，回答三个问题：<b>连哪个库</b>（jdbcConnection）、<b>生成到哪</b>（javaModelGenerator/javaClientGenerator 的包和目录）、<b>生成哪些表</b>（一行一个 <code>&lt;table tableName=\"pms_product\" domainObjectName=\"PmsProduct\"/&gt;</code>）。运行 main，几秒钟后 <code>PmsProduct</code>、<code>UmsAdmin</code>、<code>OmsOrder</code>……字段和表结构一一对应，无遗漏。</p>\n  <div class=\"note\"><span class=\"tag\">回看第一课</span>当时说 mall-mbg 像「资料卡+取数工具」，现在你知道这些资料卡是印刷机印的，不是手抄的。admin/portal/search 依赖它，等于共享同一台印刷机的产出——表结构一变，重新印一次，所有使用方拿到的资料卡同步更新。</div>\n  <div class=\"recap\"><b>收束：</b>Generator.main + generatorConfig.xml；连库、定位置、点表名，一键出三件套。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>分工：生成器管地基，你管业务</h2>\n  <figure>\n    <svg viewBox=\"0 0 760 190\" role=\"img\" aria-label=\"生成代码与手写代码的分工\">\n      <defs><marker id=\"ars9\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"30\" width=\"200\" height=\"60\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"108\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">MySQL 一百多张表</text><text x=\"108\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">表结构=唯一事实来源</text>\n      <rect x=\"268\" y=\"30\" width=\"200\" height=\"60\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"368\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">MBG 生成（mall-mbg）</text><text x=\"368\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">selectByExample / insert / update...</text>\n      <rect x=\"528\" y=\"30\" width=\"224\" height=\"60\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"640\" y=\"55\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">手写 DAO（业务模块）</text><text x=\"640\" y=\"75\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">多表关联 / 特殊查询</text>\n      <line x1=\"208\" y1=\"60\" x2=\"266\" y2=\"60\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars9)\"/>\n      <rect x=\"268\" y=\"122\" width=\"484\" height=\"52\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n      <text x=\"510\" y=\"144\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">业务代码两边都用：adminMapper.selectByExample(example) ← 生成的</text>\n      <text x=\"510\" y=\"164\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">adminRoleRelationDao.getResourceList(adminId) ← 手写的多表关联</text>\n      <line x1=\"368\" y1=\"90\" x2=\"420\" y2=\"120\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars9)\"/>\n      <line x1=\"640\" y1=\"90\" x2=\"600\" y2=\"120\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars9)\"/>\n    </svg>\n    <figcaption>图 1 · 生成的通用 CRUD 是躺着的地基，复杂业务 SQL 在业务模块手写，两者在 Service 里汇合。</figcaption>\n  </figure>\n  <p>第一课品牌查询里那句 <code>brandMapper.selectByExample(new PmsBrandExample())</code>，就是生成器给的通用条件查询；而查「某管理员有哪些接口权限」要联用户-角色-资源好几张表，这种 <code>getResourceList</code> 就在 mall-admin 里手写 DAO。<b>把重复劳动自动化，让人专心写有业务含量的部分</b>——这就是代码生成器的全部价值。</p>\n  <div class=\"recap\"><b>收束：</b>Example 条件查询是生成的地基，多表关联是手写的业务；分工清晰，互不越界。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>三个坑与一个替代：什么时候不用 MBG</h2>\n  <ul>\n    <li><b>表结构变了要重新生成</b>：不然实体类字段对不上，又是运行时才炸。</li>\n    <li><b>别覆盖手改的代码</b>：生成区和手写区分开放（mall 的做法：生成的进 mall-mbg，手写的进业务模块 DAO——模块边界天然隔开）。</li>\n    <li><b>连不上库生成失败</b>：先核对 generatorConfig.xml 里的连接串、账号密码。</li>\n  </ul>\n  <table>\n    <tr><th>场景</th><th>选择</th></tr>\n    <tr><td>表多 + 大量 CRUD 的 MyBatis 项目</td><td>MBG，批量生成保一致</td></tr>\n    <tr><td>就几张表、结构简单</td><td>手写也快，别引工具</td></tr>\n    <tr><td>新项目想更省事</td><td>MyBatis-Plus：自带 CRUD，连生成器都可以不要</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">为什么 mall 用 MBG 不用 Plus</span>mall 是有年头的项目，MBG 是当年的主流选择。读老项目要理解「当时的合理决策」，做新项目可以选更省事的——技术选型带着时代背景，别拿今天的答案嘲笑昨天的选择。</div>\n  <div class=\"recap\"><b>收束：</b>重新生成、分区防覆盖、先通库；表少手写、新项目可 Plus，MBG 不是唯一解。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：三种路线对照、工时计算器</h2>\n  <p>演练一对比手写、MBG、MyBatis-Plus 三条路线的代价。演练二拖表数量和字段数，算算手写要多少工时、生成器几秒出多少文件。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 一百张表的三条路线</b><span class=\"hint\">点按钮切换路线</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"hand\" class=\"on\">全手写</button><button data-k=\"mbg\">MBG 生成</button><button data-k=\"plus\">MyBatis-Plus</button></div></div>\n    <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>路线评估</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">三条路线都能跑，差在重复劳动谁来干</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 工时计算器</b><span class=\"hint\">拖滑杆，看手写和生成的差距</span></div>\n    <div class=\"controls\">\n      <div class=\"ctl\"><label>表数量</label><input type=\"range\" id=\"g1t\" min=\"5\" max=\"150\" value=\"100\"><span class=\"val\" id=\"g1tV\">100</span></div>\n      <div class=\"ctl\"><label>平均每表字段</label><input type=\"range\" id=\"g1f\" min=\"5\" max=\"40\" value=\"20\"><span class=\"val\" id=\"g1fV\">20</span></div>\n      <div class=\"ctl\"><label>手写每表(分钟)</label><input type=\"range\" id=\"g1m\" min=\"15\" max=\"90\" step=\"5\" value=\"40\"><span class=\"val\" id=\"g1mV\">40</span></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>算账过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">模型：三件套=实体+接口+XML；手写时间含核对字段，生成按秒级计</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>生成器省的不只是时间，还有「漏一个字段运行才炸」的出错面；表越多，机器的优势越大。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>六个问题</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。地基交给机器，业务留给自己。最后一课把十项技术串成一张地图。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>速查表</h2>\n  <table>\n    <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n    <tr><td>MBG</td><td>生产代码的代码</td><td>读表结构→实体+Mapper+XML</td></tr>\n    <tr><td>三件套</td><td>资料卡+取数声明+SQL</td><td>每张表一套，高度重复</td></tr>\n    <tr><td>Generator.main</td><td>印刷机开关</td><td>读 generatorConfig.xml 执行</td></tr>\n    <tr><td>配置三问</td><td>连哪库/生成到哪/哪些表</td><td>jdbc/位置/table 名单</td></tr>\n    <tr><td>分工</td><td>生成管地基，手写管业务</td><td>Example 通用 vs 多表 DAO</td></tr>\n    <tr><td>防覆盖</td><td>生成区手写区分开</td><td>mall 用模块边界隔开</td></tr>\n    <tr><td>表结构变更</td><td>重新生成</td><td>否则字段对不上运行炸</td></tr>\n    <tr><td>替代</td><td>MyBatis-Plus 自带 CRUD</td><td>新项目可更省事</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>结构依据本仓库 mall-mbg 模块；工时为模型估算，非实测。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第九篇-代码生成器 <span class=\"src\">— 本课重写底稿</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/mall-mbg/</code> <span class=\"src\">— Generator 与生成产物均在本地</span></li>\n    </ul>\n    <h3>源码路标（相对 mall 工程根）</h3>\n    <ul>\n      <li><code>mall-mbg/src/main/java/com/macro/mall/Generator.java</code> <span class=\"src\">— 生成入口 main</span></li>\n      <li><code>mall-mbg/src/main/resources/generatorConfig.xml</code> <span class=\"src\">— 连库/位置/表名单配置</span></li>\n      <li><code>mall-mbg/.../model/</code>、<code>mapper/</code> <span class=\"src\">— 生成的实体与 Mapper</span></li>\n      <li><code>mall-admin/.../dao/</code> 与对应 XML <span class=\"src\">— 手写复杂业务 SQL 的去处</span></li>\n    </ul>\n    <h3>官方文档</h3>\n    <ul>\n      <li><a href=\"https://mybatis.org/generator/\" target=\"_blank\" rel=\"noopener\">MyBatis Generator</a> <span class=\"src\">— 官方文档与配置参考</span></li>\n      <li><a href=\"https://baomidou.com/\" target=\"_blank\" rel=\"noopener\">MyBatis-Plus</a> <span class=\"src\">— 自带 CRUD 的替代路线</span></li>\n      <li><a href=\"https://github.com/macrozheng/mall\" target=\"_blank\" rel=\"noopener\">macrozheng/mall · GitHub</a> <span class=\"src\">— 上游项目</span></li>\n    </ul>\n    <h3>下一课要用</h3>\n    <ul>\n      <li>前九课全部速查表 <span class=\"src\">— S10 收网：十项技术一张地图</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"一百张表的痛"},{"id":"b","title":"印刷机怎么开"},{"id":"c","title":"地基与业务"},{"id":"d","title":"坑与替代"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    hand:{code:\"// 100 张表 × 3 件套 = 300 个文件手写\\npublic class PmsProduct {\\n  private Long id;\\n  private String name;\\n  // ...还有 28 个字段，抄漏一个运行才炸\\n}\",log:[[\"err\",\"纯体力活 ×100，慢且必然出错\"],[\"warn\",\"字段漏写/类型抄错，编译不报运行炸\"],[\"c\",\"// 表少可以，表多是灾难\"]]},\n    mbg:{code:\"// generatorConfig.xml 点表名\\n<table tableName=\\\"pms_product\\\" domainObjectName=\\\"PmsProduct\\\"/>\\n// 跑 Generator.main()\\n// 几秒后：实体+Mapper+XML 全部就位\",log:[[\"ok\",\"读表结构生成，字段无遗漏\"],[\"ok\",\"表结构变了重跑一次即可\"],[\"warn\",\"复杂业务 SQL 仍要手写 DAO——分工不是全包\"]]},\n    plus:{code:\"// MyBatis-Plus：接口继承就有 CRUD\\npublic interface ProductMapper extends BaseMapper<PmsProduct> {}\\n// selectById/insert/updateById... 自带\",log:[[\"ok\",\"连生成器都可以不要，更省事\"],[\"c\",\"// 新项目的主流选择\"],[\"warn\",\"mall 是老项目用 MBG——选型带时代背景\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById(\"e1code\").textContent=c.code;\n    document.getElementById(\"e1log\").innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"hand\");\n})();\n\n(function(){\n  function calc(){\n    var t=parseInt(document.getElementById('g1t').value,10);\n    var f=parseInt(document.getElementById('g1f').value,10);\n    var m=parseInt(document.getElementById('g1m').value,10);\n    document.getElementById('g1tV').textContent=t;\n    document.getElementById('g1fV').textContent=f;\n    document.getElementById('g1mV').textContent=m;\n    var minutes=t*m;\n    var hours=minutes/60;\n    var days=hours/8;\n    var files=t*3;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box bad\"><b>'+hours.toFixed(1)+'h</b><small>手写总工时(≈'+days.toFixed(1)+' 人天)</small></div>'+\n      '<div class=\"stat-box good\"><b>秒级</b><small>MBG 生成 '+files+' 个文件</small></div>'+\n      '<div class=\"stat-box\"><b>'+(t*f).toLocaleString()+'</b><small>要核对的字段总数</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip bad\">手写 '+t+' 遍三件套</span>'+\n      '<span class=\"chip on\">生成 0 漏字段</span>'+\n      (t>=50?'<span class=\"chip on\">表多：机器优势拉满</span>':'<span class=\"chip\">表少：手写也未尝不可</span>');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">算账</span>'+\n      t+' 张表 × 每表 '+m+' 分钟 = '+hours.toFixed(1)+' 小时，还没算抄错返工。MBG 跑一次 main 秒级出 '+files+' 个文件，字段和表结构严格一致。省下的时间拿去写复杂业务 SQL。';\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">手写工时 = '+t+' 表 × '+m+' 分 = '+minutes+' 分 ≈ '+hours.toFixed(1)+'h</span></div>',\n      '<div><span class=\"api\">文件数 = '+t+' × 3(实体/接口/XML) = '+files+'</span></div>',\n      '<div><span class=\"err\">出错面：'+(t*f).toLocaleString()+' 个字段每个都可能抄错</span></div>',\n      '<div><span class=\"ok\">MBG：读表生成，一致性由机器保证</span></div>',\n      '<div><span class=\"c\">// 复杂业务 SQL 不在此账内——那才是人的活</span></div>'\n    ].join('');\n  }\n  ['g1t','g1f','g1m'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. MBG 是干什么的？\",\"opts\":[[\"读表结构自动生成实体/Mapper/XML\",true,\"对。生产代码的代码。\"],[\"运行时执行 SQL\",false,\"那是 MyBatis 本体。\"],[\"优化慢查询\",false,\"与性能无关。\"]]},{\"q\":\"2. 手写一百张表 CRUD 的最大风险？\",\"opts\":[[\"字段漏写类型抄错，运行时才暴露\",true,\"对。出错面随次数涨。\"],[\"写得太快\",false,\"恰恰是慢。\"],[\"编译器不支持\",false,\"无关。\"]]},{\"q\":\"3. mall 里生成代码和手写代码怎么分工？\",\"opts\":[[\"生成管通用 CRUD，业务模块手写复杂 SQL\",true,\"对。地基与业务。\"],[\"全部生成不用手写\",false,\"多表关联要手写。\"],[\"全部手写不用生成\",false,\"那是体力活。\"]]},{\"q\":\"4. 表结构改了之后要做什么？\",\"opts\":[[\"重新生成，否则字段对不上\",true,\"对。\"],[\"什么都不用做\",false,\"实体类会过时。\"],[\"只改 XML\",false,\"三件套都要同步。\"]]},{\"q\":\"5. mall 怎么避免生成器覆盖手改代码？\",\"opts\":[[\"生成的进 mall-mbg，手写的进业务模块，边界隔开\",true,\"对。模块即隔离。\"],[\"每次生成前备份\",false,\"不是 mall 的做法。\"],[\"不允许手改任何代码\",false,\"复杂 SQL 必须手写。\"]]},{\"q\":\"6. 新项目想更省事可以选？\",\"opts\":[[\"MyBatis-Plus，自带 CRUD 连生成器都可省\",true,\"对。\"],[\"必须用 MBG\",false,\"不是唯一解。\"],[\"回到全手写\",false,\"更费事。\"]]}];" },
    "backend|java|毕业：把 mall 九项技术串成一张地图": { "body": "<p class=\"lead\">源码解读毕业课：九课九个零件，这一课把它们装回一台完整的机器。跟着「用户下单一部手机」走一遍全链路，收拢贯穿全系列的三条主线，给每个决策标上可复用星级——带走的不该是 API 用法，而是「识别问题 → 匹配方案 → 判断边界」这套架构师的工作方式。</p>\n\n<div class=\"journey\">\n  <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">收网</span><span class=\"s\">九件装一机</span></div>\n  <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">地图</span><span class=\"s\">问题对方案</span></div>\n  <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">主线</span><span class=\"s\">三条方法论</span></div>\n  <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">沉淀</span><span class=\"s\">星级与复用</span></div>\n  <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">毕业</span><span class=\"s\">演练与自测</span></div>\n</div>\n\n<section id=\"a\">\n  <h2><span class=\"no\">第 1 步</span>九课走完，零件还在地上摊着</h2>\n  <p>前九课每课拆一个零件：模块分工、JWT、Redis、MongoDB、RabbitMQ、ES、MinIO、统一回执、代码生成器。单独看每个都懂了，但真到自己做项目，问题往往是「我该用哪些、怎么组合」——零件认知不等于整机认知。</p>\n  <p>这一课换个视角：<b>不再按技术分课，按一次真实请求走</b>。用户在 mall 商城下单一部手机，这一次点击会路过前面学过的几乎每一个零件。走完这一趟，地图就自己长出来了。</p>\n  <div class=\"recap\"><b>收束：</b>毕业考的不是「Redis 有哪些 API」，是「一次请求进来，每个零件在哪个位置接住它」。</div>\n</section>\n\n<section id=\"b\">\n  <h2><span class=\"no\">第 2 步</span>全景地图：一次下单路过的所有零件</h2>\n  <figure>\n    <svg viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"mall 十项技术全景地图\">\n      <defs><marker id=\"ars10\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n      <rect x=\"8\" y=\"10\" width=\"150\" height=\"50\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"83\" y=\"32\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#5B4A2F\">用户下单</text><text x=\"83\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">前端页面发起</text>\n      <rect x=\"218\" y=\"10\" width=\"170\" height=\"50\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"303\" y=\"32\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">S2 JWT + Security</text><text x=\"303\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">闸机验票 + 动态权限</text>\n      <rect x=\"448\" y=\"10\" width=\"150\" height=\"50\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"523\" y=\"32\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">S3 Redis</text><text x=\"523\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">用户/权限/验证码缓存</text>\n      <rect x=\"218\" y=\"96\" width=\"380\" height=\"50\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"408\" y=\"118\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">业务逻辑（S1 模块分工 · S9 MBG 地基 · S8 统一回执）</text><text x=\"408\" y=\"136\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">portal 下单：算价、锁库存、生成订单</text>\n      <rect x=\"8\" y=\"196\" width=\"136\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"76\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">MySQL</text><text x=\"76\" y=\"238\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">订单/账户 强事务</text>\n      <rect x=\"164\" y=\"196\" width=\"136\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"232\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">S4 MongoDB</text><text x=\"232\" y=\"238\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">浏览记录 行为流水</text>\n      <rect x=\"320\" y=\"196\" width=\"136\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"388\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">S5 RabbitMQ</text><text x=\"388\" y=\"238\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">30分钟后查超时单</text>\n      <rect x=\"476\" y=\"196\" width=\"136\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"544\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">S6 ES</text><text x=\"544\" y=\"238\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">下单前的商品搜索</text>\n      <rect x=\"628\" y=\"196\" width=\"124\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"690\" y=\"218\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">S7 MinIO</text><text x=\"690\" y=\"238\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">商品图只存 URL</text>\n      <line x1=\"158\" y1=\"35\" x2=\"216\" y2=\"35\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars10)\"/>\n      <line x1=\"388\" y1=\"35\" x2=\"446\" y2=\"35\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars10)\"/>\n      <line x1=\"408\" y1=\"60\" x2=\"408\" y2=\"94\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars10)\"/>\n      <line x1=\"280\" y1=\"146\" x2=\"90\" y2=\"194\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars10)\"/>\n      <line x1=\"340\" y1=\"146\" x2=\"240\" y2=\"194\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars10)\"/>\n      <line x1=\"408\" y1=\"146\" x2=\"390\" y2=\"194\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars10)\"/>\n      <line x1=\"480\" y1=\"146\" x2=\"540\" y2=\"194\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars10)\"/>\n      <line x1=\"540\" y1=\"146\" x2=\"680\" y2=\"194\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#ars10)\"/>\n      <text x=\"380\" y=\"292\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">出口：S8 CommonResult 统一回执 → 前端看 code 渲染</text>\n      <text x=\"380\" y=\"314\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A39B8E\">九个零件各守一个维度：架构 · 安全 · 性能 · 存储 · 消息 · 搜索 · 文件 · 规范 · 效率</text>\n    </svg>\n    <figcaption>图 1 · 一次下单的全链路：先验票，再查缓存，业务落库分诊，异步交给队列，出口统一回执。</figcaption>\n  </figure>\n  <table>\n    <tr><th>课</th><th>技术</th><th>解决什么问题</th><th>维度</th></tr>\n    <tr><td>S1</td><td>多模块 Maven</td><td>公共复用、独立部署、团队协作</td><td>架构</td></tr>\n    <tr><td>S2</td><td>JWT + Spring Security</td><td>无状态认证，多机不用共享 Session</td><td>安全</td></tr>\n    <tr><td>S3</td><td>Redis</td><td>高频读不打库，扛并发</td><td>性能</td></tr>\n    <tr><td>S4</td><td>MongoDB</td><td>高写入、字段灵活的行为数据</td><td>存储</td></tr>\n    <tr><td>S5</td><td>RabbitMQ</td><td>延迟任务、异步解耦、削峰</td><td>消息</td></tr>\n    <tr><td>S6</td><td>Elasticsearch</td><td>海量数据全文搜索</td><td>搜索</td></tr>\n    <tr><td>S7</td><td>MinIO</td><td>大文件出库，账本只存 URL</td><td>文件</td></tr>\n    <tr><td>S8</td><td>CommonResult + 全局异常</td><td>回执统一、异常统一</td><td>规范</td></tr>\n    <tr><td>S9</td><td>MyBatis Generator</td><td>一百张表不手写</td><td>效率</td></tr>\n  </table>\n  <div class=\"recap\"><b>收束：</b>九个零件对应九个维度，一个生产级系统就是它们的组合；没有哪个是「为了用而用」。</div>\n</section>\n\n<section id=\"c\">\n  <h2><span class=\"no\">第 3 步</span>三条主线：比九个技术点更值钱的东西</h2>\n  <p><b>主线一：按数据特性选存储。</b>光「存数据」一件事 mall 分了四处——订单账户进 MySQL（要强事务），浏览记录进 MongoDB（高写入、字段会变），验证码热点进 Redis（内存级快读），图片进 MinIO（大文件别塞账本）。选型看的是「数据长什么样、怎么被读写」，不看哪个火。</p>\n  <p><b>主线二：按场景选异步。</b>判断口诀：<b>用户要看过程 → SSE 边做边推；只看结果 → RabbitMQ 做完通知；又快又少 → 直接同步，别引队列</b>。第五课取消订单属于「只看结果」，所以用死信延迟而不是轮询扫描，更不是 SSE。</p>\n  <p><b>主线三：机制与业务解耦。</b>mall-security 只给闸机机制，谁来验票各模块自己实现 UserDetailsService；MBG 只印通用资料卡，复杂 SQL 业务自己写；CommonResult 只定回执格式，错误内容业务自己喊。这个「通用抽出来写一次，业务各写各的」在多模块、生成器、统一返回里反复出现——它就是第一课到第九课共同的骨架。</p>\n  <div class=\"key\"><span class=\"tag\">毕业重点</span>技术会换代（MBG 可能被 MyBatis-Plus 替，ES 可能被别家替），三条主线不会过时：<b>看数据选存储、看场景选异步、机制业务分家</b>。</div>\n  <div class=\"recap\"><b>收束：</b>九个技术点是招式，三条主线是内功；招式会旧，内功保值。</div>\n</section>\n\n<section id=\"d\">\n  <h2><span class=\"no\">第 4 步</span>沉淀清单：哪些搬走就用，哪些要先判断</h2>\n  <table>\n    <tr><th>决策</th><th>可复用性</th><th>怎么复用</th></tr>\n    <tr><td>JWT + Spring Security</td><td>★★★ 整模块可搬</td><td>mall-security 搬走，只改 UserDetailsService</td></tr>\n    <tr><td>CommonResult + 全局异常</td><td>★★★ 纯代码可搬</td><td>抄几个类改包名即用</td></tr>\n    <tr><td>Cache-Aside 缓存</td><td>★★★ 模式可搬</td><td>先缓存再库、查到写回，到处适用</td></tr>\n    <tr><td>死信延迟队列</td><td>★★★ 模式可搬</td><td>超时取消、定时提醒通用</td></tr>\n    <tr><td>MongoDB 行为数据</td><td>★★ 场景判断可搬</td><td>行为流水类数据适用</td></tr>\n    <tr><td>ES 搜索 / MinIO 文件 / MBG</td><td>★★ 模式或工具可搬</td><td>命中对应场景再上</td></tr>\n    <tr><td>多模块架构</td><td>★ 思想可搬</td><td>有独立部署需求才拆，别为拆而拆</td></tr>\n  </table>\n  <p>规律一句话：<b>越通用的越能直接搬（认证、回执、缓存模式），越和业务绑定的越要先判断（存储选型、架构拆分）</b>。星级低的不是没价值，是「搬之前要多想一步」。</p>\n  <p>最后把这套读源码的方法本身也沉淀下来，五步循环：</p>\n  <div class=\"card\"><b>① 遇到一个问题</b>（高并发读？慢任务？海量数据？）→ <b>② 项目用了什么技术</b> → <b>③ 为什么用它</b>（优势正好命中问题）→ <b>④ 什么情况能搬、什么情况不能搬</b> → <b>⑤ 沉淀下来，下次直接用</b>。这个系列你已经走完九遍，第十遍该用在自己的项目上了。</div>\n  <div class=\"recap\"><b>收束：</b>架构师的工作方式是「识别问题 → 匹配方案 → 判断边界」，不是每个问题都从零发明。</div>\n</section>\n\n<section id=\"lab\">\n  <h2><span class=\"no\">动手</span>两场演练：综合分诊台、一次下单的旅程</h2>\n  <p>演练一是全系列存储知识的综合测验：给数据找家。演练二当一次「请求导游」，逐站走完下单全链路，每站对应一课。</p>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练一 · 综合分诊台</b><span class=\"hint\">这份数据该进哪个存储？先想再点</span></div>\n    <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"order\" class=\"on\">订单交易</button><button data-k=\"read\">浏览记录</button><button data-k=\"code\">短信验证码</button><button data-k=\"img\">商品图片</button><button data-k=\"search\">搜索索引</button></div></div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"e1stats\"></div><div class=\"key\" id=\"e1key\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>分诊依据</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">口诀：看数据长什么样、怎么被读写，不看哪个火</span></div>\n  </div>\n  <div class=\"lab\">\n    <div class=\"lab-head\"><b>演练二 · 一次下单的旅程</b><span class=\"hint\">点「下一站」，看请求路过哪些零件</span></div>\n    <div class=\"controls\">\n      <div class=\"seg\" id=\"g1nav\"><button data-k=\"prev\">← 上一站</button><button data-k=\"next\" class=\"on\">下一站 →</button><button data-k=\"reset\">回到起点</button></div>\n    </div>\n    <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>旅程日志</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n    <div class=\"lab-foot\"><span class=\"hint\">七站走完，前九课就在这一次点击里</span></div>\n  </div>\n  <div class=\"key\"><span class=\"tag\">毕业标准</span>能不看课本说出每一站「为什么是这个零件接住」，并能判断自己项目里哪些站可以直接抄、哪些站要先想。</div>\n</section>\n\n<section id=\"quiz\">\n  <h2><span class=\"no\">自测</span>毕业六问</h2>\n  <div class=\"card\" id=\"quiz-box\"></div>\n  <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对，毕业。带着三条主线和五步方法，去解剖你自己的下一个项目。</p>\n</section>\n\n<section id=\"map\">\n  <h2><span class=\"no\">回顾</span>毕业速查表</h2>\n  <table>\n    <tr><th>主线</th><th>口诀</th><th>出处</th></tr>\n    <tr><td>选存储</td><td>看数据特性：强事务 MySQL / 流水 Mongo / 热读 Redis / 大文件 MinIO</td><td>S3 S4 S7</td></tr>\n    <tr><td>选异步</td><td>看过程 SSE / 看结果 MQ / 又快又少同步</td><td>S5</td></tr>\n    <tr><td>解耦</td><td>机制写一次，业务各写各的</td><td>S1 S2 S8 S9</td></tr>\n    <tr><td>复用星级</td><td>越通用越能搬，越绑定业务越要判断</td><td>本课第 4 步</td></tr>\n    <tr><td>五步方法</td><td>问题→技术→为什么→边界→沉淀</td><td>本课第 4 步</td></tr>\n    <tr><td>诚实提醒</td><td>原版 mall 前端搜索走 MySQL LIKE；本仓库已改走 nginx 网关接 ES</td><td>S6</td></tr>\n  </table>\n  <div class=\"note\"><span class=\"tag\">说明</span>星级评估依据底稿第十篇的复用性表；地图为教学示意，请求实际路径以源码为准。</div>\n</section>\n\n<section id=\"refs\">\n  <h2><span class=\"no\">依据</span>参考链接</h2>\n  <div class=\"card refs\">\n    <h3 style=\"margin-top:0;\">原始底稿与配套代码（本仓库）</h3>\n    <ul>\n      <li>《AI 后端开发：Java 实战》源码阅读 · 第十篇-系列总结 <span class=\"src\">— 本课重写底稿</span></li>\n      <li>配套源码 <code>code/source-reading/java/mall/mall/</code> 及同级 <code>mall-admin-web/</code>、<code>mall-app-web/</code>、<code>mall-docker/</code> <span class=\"src\">— 全系列代码与部署脚本</span></li>\n    </ul>\n    <h3>全系列课内回顾</h3>\n    <ul>\n      <li>S1 模块分工 → S2 登录 JWT → S3 Redis → S4 MongoDB → S5 延迟队列 → S6 搜索 ES → S7 MinIO → S8 接口规范 → S9 代码生成 <span class=\"src\">— 每课速查表即复习卡</span></li>\n    </ul>\n    <h3>官方文档（全系列汇总）</h3>\n    <ul>\n      <li><a href=\"https://github.com/macrozheng/mall\" target=\"_blank\" rel=\"noopener\">macrozheng/mall · GitHub</a> <span class=\"src\">— 上游项目与文档站入口</span></li>\n      <li><a href=\"https://spring.io/projects/spring-security\" target=\"_blank\" rel=\"noopener\">Spring Security</a> · <a href=\"https://redis.io/docs/\" target=\"_blank\" rel=\"noopener\">Redis</a> · <a href=\"https://www.mongodb.com/docs/\" target=\"_blank\" rel=\"noopener\">MongoDB</a> <span class=\"src\">— 安全与存储</span></li>\n      <li><a href=\"https://www.rabbitmq.com/docs\" target=\"_blank\" rel=\"noopener\">RabbitMQ</a> · <a href=\"https://www.elastic.co/guide/index.html\" target=\"_blank\" rel=\"noopener\">Elasticsearch</a> · <a href=\"https://min.io/docs/minio/linux/index.html\" target=\"_blank\" rel=\"noopener\">MinIO</a> <span class=\"src\">— 消息、搜索与文件</span></li>\n      <li><a href=\"https://mybatis.org/generator/\" target=\"_blank\" rel=\"noopener\">MyBatis Generator</a> <span class=\"src\">— 效率工具</span></li>\n    </ul>\n  </div>\n</section>", "toc": [{"id":"a","title":"零件与整机"},{"id":"b","title":"全景地图"},{"id":"c","title":"三条主线"},{"id":"d","title":"沉淀清单"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"毕业六问"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var CASES={\n    order:{home:'MySQL',why:'要钱要账，强事务强一致',log:[[\"ok\",\"订单/账户：扣款和落单必须同生共死\"],[\"ok\",\"关联查询多：订单联商品联用户\"],[\"warn\",\"浏览记录也塞这里？高写入拖垮交易库(S4 反面)\"]]},\n    read:{home:'MongoDB',why:'高写入流水，字段还会变',log:[[\"ok\",\"每次浏览都写一条，写入量大\"],[\"ok\",\"快照字段随版本增减，文档型免改表\"],[\"warn\",\"放 MySQL：表结构天天改，索引越来越重\"]]},\n    code:{home:'Redis',why:'高频读 + 几分钟就过期',log:[[\"ok\",\"验证码 5 分钟有效：TTL 天然匹配\"],[\"ok\",\"每次登录都要验：内存级快读\"],[\"warn\",\"放 MySQL：读写都浪费，还要自己清过期\"]]},\n    img:{home:'MinIO',why:'大文件不进账本，只存 URL',log:[[\"ok\",\"图片二进制大，塞库会让备份/主从全变慢(S7)\"],[\"ok\",\"对象存储拿 URL，账本只存一行字符串\"],[\"warn\",\"放 Mongo？文档也扛不住二进制大对象\"]]},\n    search:{home:'Elasticsearch',why:'分词倒排，LIKE 追不上',log:[[\"ok\",\"海量商品全文搜索：倒排索引毫秒出结果(S6)\"],[\"warn\",\"MySQL LIKE '%词%'：全表扫描且无法分词\"],[\"warn\",\"诚实提醒：原版前端走 LIKE 没接 ES；本仓库已接上\"]]}\n  };\n  function show(k){\n    var c=CASES[k];\n    document.getElementById('e1stats').innerHTML=\n      '<div class=\"stat-box good\"><b>'+c.home+'</b><small>分诊结果</small></div>'+\n      '<div class=\"stat-box\"><b>'+c.why.split('，')[0]+'</b><small>关键特性</small></div>';\n    document.getElementById('e1key').innerHTML='<span class=\"tag\">依据</span>'+c.why+'。判断入口永远是「数据长什么样、怎么被读写」。';\n    document.getElementById('e1log').innerHTML=c.log.map(function(l){return '<div><span class=\"'+l[0]+'\">'+l[1]+'</span></div>';}).join('');\n  }\n  document.querySelectorAll('#e1 button').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('#e1 button').forEach(function(x){x.classList.remove('on');});b.classList.add('on');show(b.getAttribute('data-k'));});});\n  show('order');\n})();\n\n(function(){\n  var STOPS=[\n    {n:'起点',tech:'前端页面',s:'S1',act:'用户点「提交订单」，mall-app-web 发出 POST /order/generateOrder',why:'前后端分离：页面只管发请求和渲染回执'},\n    {n:'第1站',tech:'JWT 闸机',s:'S2',act:'JwtAuthenticationTokenFilter 解析 token，确认「你是你」；DynamicAuthorizationManager 查你有没有下单权限',why:'无状态验票，多机部署不用共享 Session'},\n    {n:'第2站',tech:'Redis 缓存',s:'S3',act:'查用户信息/收货地址先打 Redis，未命中才回 MySQL 并写回',why:'Cache-Aside：高频读别每次打库'},\n    {n:'第3站',tech:'MySQL 落单',s:'S1/S9',act:'portal 算价、锁 SKU 库存、订单落库；用的 Mapper 是 MBG 印的地基',why:'交易要强事务；通用 CRUD 机器生成'},\n    {n:'第4站',tech:'MongoDB 流水',s:'S4',act:'下单前看商品详情时，浏览记录已异步写进 Mongo（带商品快照）',why:'行为流水高写入，别挤交易库'},\n    {n:'第5站',tech:'RabbitMQ 闹钟',s:'S5',act:'订单号进延迟队列，30 分钟后死信投递；到时未支付则 cancelOrder 释放库存退券返积分',why:'只看结果的慢任务交队列，不轮询'},\n    {n:'第6站',tech:'MinIO 图片',s:'S7',act:'订单里的商品图是一个 URL，浏览器直接找对象存储取图',why:'大文件出库，账本只存字符串'},\n    {n:'终点',tech:'CommonResult 回执',s:'S8',act:'{code:200, message:\"操作成功\", data:{订单号...}}；若中途抛 ApiException，全局兜底也转成同格式回执',why:'无论成败，前端拿到的都是同一张回执'}\n  ];\n  var cur=0;\n  function render(){\n    var s=STOPS[cur];\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+(cur+1)+'/'+STOPS.length+'</b><small>当前站：'+s.n+'</small></div>'+\n      '<div class=\"stat-box good\"><b>'+s.tech+'</b><small>接住请求的零件</small></div>'+\n      '<div class=\"stat-box\"><b>'+s.s+'</b><small>对应课程</small></div>';\n    document.getElementById('g1chips').innerHTML=STOPS.map(function(x,i){return '<span class=\"chip '+(i===cur?'on':(i<cur?'':''))+'\">'+(i<=cur?x.tech:'？')+'</span>';}).join('');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">为什么是它</span>'+s.why+'。';\n    var lines=[];\n    for(var i=0;i<=cur;i++){\n      lines.push('<div><span class=\"'+(i===cur?'ok':'api')+'\">['+STOPS[i].n+' · '+STOPS[i].tech+'] '+STOPS[i].act+'</span></div>');\n    }\n    if(cur===STOPS.length-1){lines.push('<div><span class=\"c\">// 旅程完成：九个零件在一次点击里各就各位</span></div>');}\n    document.getElementById('g1log').innerHTML=lines.join('');\n  }\n  document.querySelectorAll('#g1nav button').forEach(function(b){b.addEventListener('click',function(){\n    var k=b.getAttribute('data-k');\n    if(k==='next'&&cur<STOPS.length-1)cur++;\n    if(k==='prev'&&cur>0)cur--;\n    if(k==='reset')cur=0;\n    render();\n  });});\n  render();\n})();\n\nconst QUIZ=[{\"q\":\"1. 订单交易数据为什么进 MySQL？\",\"opts\":[[\"要强事务强一致，扣款落单同生共死\",true,\"对。钱的账本。\"],[\"MySQL 最流行\",false,\"选型看数据特性不看热度。\"],[\"MySQL 写入最快\",false,\"高写入流水反而选 Mongo。\"]]},{\"q\":\"2. 取消超时订单为什么用延迟队列而不是定时扫描？\",\"opts\":[[\"到点才投递，不空转不轮询\",true,\"对。闹钟不是巡逻。\"],[\"队列比数据库便宜\",false,\"不是成本问题。\"],[\"扫描写不出来\",false,\"能写但浪费。\"]]},{\"q\":\"3. 「用户要看过程」的慢任务该选？\",\"opts\":[[\"SSE 边做边推\",true,\"对。看过程用流式。\"],[\"RabbitMQ\",false,\"那是只看结果。\"],[\"定时轮询\",false,\"两头不讨好。\"]]},{\"q\":\"4. 机制与业务解耦在 mall 的体现？\",\"opts\":[[\"security 给机制，各模块实现 UserDetailsService\",true,\"对。通用写一次。\"],[\"所有代码写在一个模块\",false,\"恰是反面。\"],[\"每个模块各写一套 JWT 解析\",false,\"重复造轮子。\"]]},{\"q\":\"5. 哪组决策可以近乎原样搬进新项目？\",\"opts\":[[\"JWT 模块 + CommonResult + Cache-Aside 模式\",true,\"对。越通用越能搬。\"],[\"七模块拆法 + 表结构\",false,\"和业务绑定，要先判断。\"],[\"ES 集群规模\",false,\"容量要按自己场景算。\"]]},{\"q\":\"6. 这套读源码方法的正确顺序？\",\"opts\":[[\"问题→技术→为什么→边界→沉淀\",true,\"对。识别问题、匹配方案、判断边界。\"],[\"背 API→抄代码→上线\",false,\"那是工具使用不是架构能力。\"],[\"先选流行的技术再找问题\",false,\"方向反了。\"]]}];" }
  };
  return { get: function (t, s, l) { var k = t + "|" + s + "|" + l; return data[k] || (prev ? prev.get(t, s, l) : null); } };
})(window.QZ_CONTENT);
